gemEffects={
["ArbitersReachWardPlayer"]={["Arbiter's Reach"]={["enDescription"]="Supports Persistent Buff Skills, causing you periodically grant Guard to allies in your Presence while the Skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами. Вы периодически даруете оборону союзникам в вашем присутствии, пока умение активно.",["name"]="Охват Арбитра"}},
["CompressedDurationSupportPlayer"]={["Compressed Duration I"]={["enDescription"]="Supports any skill that has a duration making that duration shorter.",["description"]="Усиливает любое умение с длительностью, сокращая её.",["name"]="Сокращение длительности I"}},
["CompressedDurationSupportPlayerTwo"]={["Compressed Duration II"]={["enDescription"]="Supports any skill that has a duration making that duration shorter.",["description"]="Усиливает любое умение с длительностью, сокращая её.",["name"]="Сокращение длительности II"}},
["FistOfWarSupportPlayer"]={["Fist of War I"]={["enDescription"]="Supports Slams you use yourself, providing a powerful Ancestral Boost every few seconds.",["description"]="Усиливает мощные удары, которые вы используете самостоятельно, каждые несколько секунд даруя мощное усиление предками.",["name"]="Кулак войны I"}},
["FistOfWarSupportPlayerThree"]={["Fist of War III"]={["enDescription"]="Supports Slams you use yourself, providing a very powerful Ancestral Boost infrequently.",["description"]="Усиливает мощные удары, которые вы используете самостоятельно, изредка даруя очень мощное усиление предками.",["name"]="Кулак войны III"}},
["FistOfWarSupportPlayerTwo"]={["Fist of War II"]={["enDescription"]="Supports Slams you use yourself, providing a powerful Ancestral Boost every few seconds.",["description"]="Усиливает мощные удары, которые вы используете самостоятельно, каждые несколько секунд даруя мощное усиление предками.",["name"]="Кулак войны II"}},
["ImpactShockwaveSupportPlayer"]={["Impact Shockwave"]={["enDescription"]="Supports Melee Strike Skills and Wind Attack Skills, causing them to create an Aftershock that damages enemies around the target when they Heavy Stun an enemy.",["description"]="Усиливает умения ударов ближнего боя и умения атак ветром. Усиленные умения при сильном оглушении врага создают остаточную волну, наносящую урон врагам вокруг цели.",["name"]="Ударная волна"}},
["InternecineDrawReservationPlayer"]={["DNT Internecine Draw"]={["enDescription"]="DNT Gem effect description.",["description"]="DNT Gem effect description.",["name"]="DNT Internecine Draw"}},
["ProlongedDurationSupportPlayer"]={["Prolonged Duration I"]={["enDescription"]="Supports any skill that has a duration, making that duration longer.",["description"]="Усиливает любое умение с длительностью, увеличивая её.",["name"]="Продление I"}},
["ProlongedDurationSupportPlayerThree"]={["Prolonged Duration III"]={["enDescription"]="Supports any skill that has a duration, making that duration significantly longer while applying a cooldown. Cannot support Skills which already have a cooldown.",["description"]="Усиливает любое умение с длительностью, значительно увеличивая её, но добавляя умению перезарядку. Не может усиливать умения, уже обладающие перезарядкой.",["name"]="Продление III"}},
["ProlongedDurationSupportPlayerTwo"]={["Prolonged Duration II"]={["enDescription"]="Supports any skill that has a duration, making that duration longer.",["description"]="Усиливает любое умение с длительностью, увеличивая её.",["name"]="Продление II"}},
["RuthlessSupportPlayer"]={["Ruthless"]={["enDescription"]="Supports Attacks, causing repeated uses to be more effective at Stunning enemies.",["description"]="Усиливает атаки, делая повторные применения более эффективными в оглушении врагов.",["name"]="Беспощадность"}},
["SupporTekarusSnare"]={["DNT Tekaru's Snare"]={["enDescription"]="DNT Supports Mark Skills. Trigger Savage Snare when you Mark enemies with Supported Skills.",["description"]="DNT Supports Mark Skills. Trigger Savage Snare when you Mark enemies with Supported Skills.",["name"]="DNT Tekaru's Snare"}},
["SupportAbidingHexPlayer"]={["Abiding Hex"]={["enDescription"]="Supports Curse Skills you cast yourself. Supported Skills will consume Power Charges on use, gaining significant Curse duration if they do. Cannot Support Skills which consume Power Charges.",["description"]="Усиливает умения проклятий, которые вы сотворяете самостоятельно. Усиленные умения поглощают заряды энергии при использовании, приобретая при этом существенное увеличение длительности проклятий. Не может усиливать умения, поглощающие заряды энергии.",["name"]="Подчиняющая порча"}},
["SupportAcrimonyPlayer"]={["Acrimony"]={["enDescription"]="Supports Skills which can Damage Enemies. Enemies affected by Damage over time from Supported Skills which was not caused by a Damaging Ailment have reduced Life regeneration rate. Only the strongest instance of this Debuff will apply. Does not Support Skills used by Minions.",["description"]="Усиливает умения, которые могут наносить урон врагам. Противники под действием постепенного урона от усиленных умений, который не вызван состоянием, медленнее регенерируют здоровье. Действовать будет только наиболее сильный из всех одноимённых отрицательных эффектов замедления регенерации здоровья. Не может усиливать умения, используемые приспешниками.",["name"]="Едкость"}},
["SupportAddedChaosDamagePlayer"]={["Chaos Attunement"]={["enDescription"]="Supports any skill that deals damage, causing them to Gain Chaos Damage but deal less Damage of other Types.",["description"]="Усиливает любое умение, наносящее урон. Усиленные умения приобретают урон хаосом, но наносят меньше урона других типов.",["name"]="Власть хаоса"}},
["SupportAddedColdDamagePlayer"]={["Cold Attunement"]={["enDescription"]="Supports any skill that deals damage, causing them to Gain Cold Damage but deal less Fire and Lightning Damage.",["description"]="Усиливает любое умение, наносящее урон. Усиленные умения приобретают урон от холода, но наносят меньше урона от огня и молнии.",["name"]="Власть холода"}},
["SupportAddedFireDamagePlayer"]={["Fire Attunement"]={["enDescription"]="Supports any skill that deals damage, causing them to Gain Fire Damage but deal less Cold and Lightning Damage.",["description"]="Усиливает любое умение, наносящее урон. Усиленные умения приобретают урон от огня, но наносят меньше урона от холода и молнии.",["name"]="Власть огня"}},
["SupportAddedLightningDamagePlayer"]={["Lightning Attunement"]={["enDescription"]="Supports any skill that deals damage, causing them to Gain Lightning Damage but deal less Cold and Fire Damage.",["description"]="Усиливает любое умение, наносящее урон. Усиленные умения приобретают урон от молнии, но наносят меньше урона от холода и огня.",["name"]="Власть молний"}},
["SupportAdhesiveGrenadesPlayer"]={["Adhesive Grenades I"]={["enDescription"]="Supports Grenade Skills. Grenades from Supported Skills do not bounce, instead halting movement where they intially land, but doing lower damage when they detonate.",["description"]="Усиливает умения гранат. Гранаты усиленных умений не отскакивают, вместо этого останавливаясь в точке изначального приземления, но наносят сниженный урон при детонации.",["name"]="Гранаты-липучки I"}},
["SupportAdhesiveGrenadesPlayerThree"]={["Adhesive Grenades III"]={["enDescription"]="Supports Grenade Skills. Grenades from Supported Skills do not bounce, instead halting movement where they intially land. Grenades from Supported Skills have longer cooldowns, and a chance to detonate an additional time.",["description"]="Усиливает умения гранат. Гранаты усиленных умений не отскакивают, вместо этого останавливаясь в точке изначального приземления. Гранаты усиленных умений имеют более длительную перезарядку и шанс детонировать ещё раз.",["name"]="Гранаты-липучки III"}},
["SupportAdhesiveGrenadesPlayerTwo"]={["Adhesive Grenades II"]={["enDescription"]="Supports Grenade Skills. Grenades from Supported Skills do not bounce, instead halting movement where they intially land.",["description"]="Усиливает умения гранат. Гранаты усиленных умений не отскакивают, вместо этого останавливаясь в точке изначального приземления.",["name"]="Гранаты-липучки II"}},
["SupportAdmixturePlayer"]={["Admixture"]={["enDescription"]="Supports Skills which can cause Damaging Hits. Bleeding inflicted by those Hits is more effective against Poisoned Enemies, and Poison inflicted by Supported Skills is more effective against Bleeding Enemies.",["description"]="Усиливает умения, которые могут наносить урон ударами. Наложенное этими ударами кровотечение более эффективно против отравленных врагов, а отравление, наложенное усиленными умениями, более эффективно против врагов под действием кровотечения.",["name"]="Примесь"}},
["SupportAdvancingStormPlayer"]={["Advancing Storm"]={["enDescription"]="Supports Storm skills, causing them to appear at the user's location and move towards the target location.",["description"]="Усиливает умения бурь. Усиленные умения возникают в местоположении сотворившего и движутся в указанную точку.",["name"]="Надвигающаяся буря"}},
["SupportAftershockChancePlayer"]={["Aftershock I"]={["enDescription"]="Supports Slams you use yourself, giving them a chance to create an Aftershock.",["description"]="Усиливает мощные удары, которые вы используете самостоятельно, даруя им шанс создать остаточную волну.",["name"]="Остаточная волна I"}},
["SupportAftershockChancePlayerThree"]={["Aftershock III"]={["enDescription"]="Supports Slam Skills. Supported Skills a chance to create an Aftershock as well as increased chance to cause Aftershocks the longer their Attack time",["description"]="Усиливает умения мощных ударов, даруя им шанс создать остаточную волну. Шанс вызвать остаточные волны усиленными умениями увеличивается соразмерно их времени атаки.",["name"]="Остаточная волна III"}},
["SupportAftershockChancePlayerTwo"]={["Aftershock II"]={["enDescription"]="Supports Slams you use yourself, giving them a chance to create an Aftershock.",["description"]="Усиливает мощные удары, которые вы используете самостоятельно, даруя им шанс создать остаточную волну.",["name"]="Остаточная волна II"}},
["SupportAhnsCitadelPlayer"]={["Ahn's Citadel"]={["enDescription"]="Supports skills that create walls in a line, causing them to instead be created along a fissure.",["description"]="Усиливает умения, которые создают линию из стен. Вместо этого усиленные умения создают стены вдоль расселины.",["name"]="Цитадель Ахна"}},
["SupportAilithLineagePlayer"]={["Ailith's Chimes"]={["enDescription"]="Supports Skills which can expend Combo. On expending Combo with Supported Skills, you have a chance to gain Power Charges based on the amount of Combo expended.",["description"]="Усиливает умения, которые могут тратить Комбо. При трате Комбо усиленными умениями есть шанс получить заряды энергии в зависимости от количества потраченного Комбо.",["name"]="Мелодия Эйлит"}},
["SupportAlignmentPlayer"]={["Alignment I"]={["enDescription"]="Supports Bow Attacks. Supported Skills indicate one of four directions, changing indicated direction when an Attack with Supported Skill matches that direction. Attacks from Supported Skills which match the indicated direction deal much more Damage. Cannot Support Channelled Skills.",["description"]="Усиливает атаки луками. Усиленные умения выбирают одно из четырёх направлений, меняя его при атаке усиленным умением в выбранном направлении. Если направление атаки усиленным умением совпадает с выбранным, то наносится гораздо больше урона. Не может усиливать поддерживаемые умения.",["name"]="Сонаправленность I"}},
["SupportAlignmentPlayerThree"]={["Alignment III"]={["enDescription"]="Supports Bow Attacks. Supported Skills indicate one of four directions, changing indicated direction when an Attack with Supported Skill matches that direction. Attacks from Supported Skills which match the indicated direction fire additional Projectiles. Cannot Support Channelled Skills.",["description"]="Усиливает атаки луками. Усиленные умения выбирают одно из четырёх направлений, меняя его при атаке усиленным умением в выбранном направлении. Если направление атаки усиленным умением совпадает с выбранным, то выпускаются дополнительные снаряды. Не может усиливать поддерживаемые умения.",["name"]="Сонаправленность III"}},
["SupportAlignmentPlayerTwo"]={["Alignment II"]={["enDescription"]="Supports Bow Attacks. Supported Skills indicate one of four directions, changing indicated direction when an Attack with Supported Skill matches that direction. Attacks from Supported Skills which match the indicated direction deal much more Damage. Cannot Support Channelled Skills.",["description"]="Усиливает атаки луками. Усиленные умения выбирают одно из четырёх направлений, меняя его при атаке усиленным умением в выбранном направлении. Если направление атаки усиленным умением совпадает с выбранным, то наносится гораздо больше урона. Не может усиливать поддерживаемые умения.",["name"]="Сонаправленность II"}},
["SupportAmanamusTithePlayer"]={["Amanamu's Tithe"]={["enDescription"]="Supports Persistent Minion Skills, granting a chance when Supported Minions die for you to gain an Abyssal Monster Modifier.",["description"]="Усиливает умения постоянных приспешников, даруя шанс при смерти усиленных приспешников получить свойство монстров Бездны.",["name"]="Десятина Аманаму"}},
["SupportAmbrosiaPlayer"]={["Ambrosia"]={["enDescription"]="Supports Skills you use yourself which damage enemies with Hits. Supported Skills consume a percentage of your maximum Mana Flask charges, Gaining a percentage of damage as extra Lightning damage per Mana Flask charge consumed.",["description"]="Усиливает самостоятельно используемые вами умения, которые наносят урон врагам ударами. Усиленные умения поглощают часть вашего максимума зарядов флакона маны и наносят часть своего урона в виде дополнительного урона от молнии за каждый поглощённый заряд флакона маны.",["name"]="Амброзия"}},
["SupportAmbrosiaPlayerTwo"]={["Ambrosia II"]={["enDescription"]="Supports Skills you use yourself which damage enemies with Hits. Supported Skills consume a percentage of your maximum Mana Flask charges, Gaining a percentage of damage as extra Lightning damage per Mana Flask charge consumed.",["description"]="Усиливает самостоятельно используемые вами умения, которые наносят урон врагам ударами. Усиленные умения поглощают часть вашего максимума зарядов флакона маны и наносят часть своего урона в виде дополнительного урона от молнии за каждый поглощённый заряд флакона маны.",["name"]="Амброзия II"}},
["SupportAmbushPlayer"]={["Ambush"]={["enDescription"]="Supports any skill that Hits enemies, making it more likely to Critically Hit enemies on full life.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения с большей вероятностью наносят критические попадания врагам с полным здоровьем.",["name"]="Засада"}},
["SupportAmmoConservationPlayer"]={["Ammo Conservation I"]={["enDescription"]="Supports Crossbow Ammunition Skills, granting a chance to not consume a Bolt when firing.",["description"]="Усиливает умения боезапаса самострелов. Усиленные умения даруют шанс не израсходовать болт при выстреле.",["name"]="Сохранение боеприпаса I"}},
["SupportAmmoConservationPlayerFour"]={["Arjun's Medal"]={["enDescription"]="Supports Crossbow Skills, causing them to load a bolt into all Crossbow Ammunition on kill.",["description"]="Усиливает умения самострелов. Усиленные умения заряжают по болту в весь боезапас самострелов при убийстве.",["name"]="Медаль Аржуна"}},
["SupportAmmoConservationPlayerThree"]={["Ammo Conservation III"]={["enDescription"]="Supports Crossbow Ammunition Skills, granting a chance to not consume a Bolt when firing, at the cost of Reload speed.",["description"]="Усиливает умения боезапаса самострелов. Усиленные умения даруют шанс не израсходовать болт при выстреле ценой скорости перезарядки.",["name"]="Сохранение боеприпаса III"}},
["SupportAmmoConservationPlayerTwo"]={["Ammo Conservation II"]={["enDescription"]="Supports Crossbow Ammunition Skills, granting a chance to not consume a Bolt when firing.",["description"]="Усиливает умения боезапаса самострелов. Усиленные умения даруют шанс не израсходовать болт при выстреле.",["name"]="Сохранение боеприпаса II"}},
["SupportAncestralAidPlayer"]={["Ancestral Aid"]={["enDescription"]="Supports Strikes you use yourself. Supported Skills cannot be used until you have Blocked a certain number of Hits, but will be Ancestrally Boosted when used. After use, this Blocked Hit counter will reset. Cannot Support Channelled Skills or Skills which already have a Condition for use.",["description"]="Усиливает удары, которые вы используете самостоятельно. Усиленные умения нельзя использовать, пока вы не заблокируете определённое количество ударов, но при использовании они будут усилены предками. После использования счётчик заблокированных ударов сбрасывается. Не может усиливать поддерживаемые умения и умения, уже обладающие условием использования.",["name"]="Помощь предков"}},
["SupportAncestralCallPlayer"]={["Ancestral Call I"]={["enDescription"]="Supports Strikes you use yourself, providing a powerful Ancestral Boost every few seconds. Cannot Support Channelled Skills and does not modify Skills used by Minions.",["description"]="Усиливает удары, которые вы используете самостоятельно, даруя мощное усиление предками каждые несколько секунд. Не может усиливать поддерживаемые умения и умения, используемые приспешниками.",["name"]="Зов предков I"}},
["SupportAncestralCallPlayerThree"]={["Ancestral Call III"]={["enDescription"]="Supports Strikes you use yourself, providing a powerful Ancestral Boost every second, at the cost of a damage penalty. Cannot Support Channelled Skills and does not modify Skills used by Minions.",["description"]="Усиливает удары, которые вы используете самостоятельно, даруя мощное усиление предками каждую секунду ценой штрафа к урону. Не может усиливать поддерживаемые умения и умения, используемые приспешниками.",["name"]="Зов предков III"}},
["SupportAncestralCallPlayerTwo"]={["Ancestral Call II"]={["enDescription"]="Supports Strikes you use yourself, providing a powerful Ancestral Boost every few seconds. Cannot Support Channelled Skills and does not modify Skills used by Minions.",["description"]="Усиливает удары, которые вы используете самостоятельно, даруя мощное усиление предками каждые несколько секунд. Не может усиливать поддерживаемые умения и умения, используемые приспешниками.",["name"]="Зов предков II"}},
["SupportArakaalisLustPlayer"]={["Arakaali's Lust"]={["enDescription"]="Supports any Skill that Hits Enemies, causing it to deal increasingly higher damage the more Poisons are on the target.",["description"]="Усиливает любое умение, наносящее удары по врагам. Урон усиленных умений тем выше, чем больше яда на цели.",["name"]="Похоть Аракаали"}},
["SupportArbitersCallingPlayer"]={["DNT Arbiters Calling"]={["enDescription"]="DNT Description",["description"]="DNT-UNUSED Description",["name"]="DNT Arbiters Calling"}},
["SupportArbitersIgnitionPlayer"]={["Arbiter's Ignition"]={["enDescription"]="Supports Fire Spell Skills causing you to gain Elemental Archon when Igniting with them.",["description"]="Усиливает умения чар огня. Усиленные умения даруют эффект архонта стихий при поджоге ими.",["name"]="Воспламенение Арбитра"}},
["SupportArcaneSurgePlayer"]={["Arcane Surge"]={["enDescription"]="Supports Spells you cast yourself, tracking the mana you spend to cast them. Spending enough mana grants a burst of Mana Regeneration and Cast Speed.",["description"]="Усиливает чары, которые вы сотворяете самостоятельно, отслеживая количество израсходованной на них маны. Расход достаточного количества маны даёт кратковременный прирост регенерации маны и скорости сотворения чар.",["name"]="Колдовской выброс"}},
["SupportArmourBreakPlayer"]={["Armour Break I"]={["enDescription"]="Supports Skills that Hit Enemies, causing those Hits to Break Armour based on a portion of Physical Damage dealt.",["description"]="Усиливает умения, наносящие удары по врагам. Удары усиленными умениями разрушают броню на основе части нанесённого физического урона.",["name"]="Разрушение брони I"}},
["SupportArmourBreakPlayerThree"]={["Armour Break III"]={["enDescription"]="Supports Skills that Hit Enemies, causing those Hits to Break Armour based on a portion of Physical Damage dealt. On Fully Breaking Armour with Supported Skills, you have a chance to gain an Endurance Charge.",["description"]="Усиливает умения, наносящие удары по врагам. Удары усиленными умениями разрушают броню на основе части нанесённого физического урона. При полном разрушении брони усиленными умениями вы имеете шанс получить заряд выносливости.",["name"]="Разрушение брони III"}},
["SupportArmourBreakPlayerTwo"]={["Armour Break II"]={["enDescription"]="Supports Skills that Hit Enemies, causing those Hits to Break Armour based on a portion of Physical Damage dealt. On Fully Breaking Armour with Supported Skills, you have a chance to gain an Endurance Charge.",["description"]="Усиливает умения, наносящие удары по врагам. Удары усиленными умениями разрушают броню на основе части нанесённого физического урона. При полном разрушении брони усиленными умениями вы имеете шанс получить заряд выносливости.",["name"]="Разрушение брони II"}},
["SupportArmourDemolisherPlayer"]={["Armour Demolisher I"]={["enDescription"]="Supports any skill, causing Armour Break it inflicts to be stronger.",["description"]="Усиливает любое умение, делая накладываемое им разрушение брони сильнее.",["name"]="Разбиватель брони I"}},
["SupportArmourDemolisherPlayerTwo"]={["Armour Demolisher II"]={["enDescription"]="Supports any skill, causing Armour Break it inflicts to be stronger.",["description"]="Усиливает любое умение, делая накладываемое им разрушение брони сильнее.",["name"]="Разбиватель брони II"}},
["SupportArmourExplosionPlayer"]={["Armour Explosion"]={["enDescription"]="Supports Attacks and Warcries, causing them to trigger a Fiery explosion when they Fully Break an enemy's Armour.",["description"]="Усиливает атаки. Усиленные умения вызывают срабатывание огненного взрыва при полном разрушении вражеской брони.",["name"]="Взрыв брони"}},
["SupportArmsLengthPlayer"]={["Arms Length"]={["enDescription"]="Supports Skills which Hit Enemies, causing Knockback from those Hits to be significantly more effective.",["description"]="Усиливает умения, наносящие удары по врагам, делая отбрасывание от этих ударов значительно более эффективным.",["name"]="На длину руки"}},
["SupportAstralProjectionPlayer"]={["Astral Projection"]={["enDescription"]="Supports Nova Skills, causing those Skills to take place at the targeted location when used instead of around you.",["description"]="Усиливает умения колец, заставляя их срабатывать в указанном месте, а не вокруг вас.",["name"]="Астральная проекция"}},
["SupportAtaluiBloodlettingPlayer"]={["Atalui's Bloodletting"]={["enDescription"]="Supports any Skill, turning a portion of its Mana cost into a Life cost. Does not support Skills which reserve Spirit. Supported Skills Gain a portion of their Life cost as extra Physical Damage.",["description"]="Усиливает любое умение, заменяя часть его расхода маны расходом здоровья. Не может усиливать умения, удерживающие дух. Усиленные умения наносят дополнительно часть своего расхода здоровья в виде физического урона.",["name"]="Кровопускание Аталуи"}},
["SupportAtzirisAllurePlayer"]={["Atziri's Allure"]={["enDescription"]="Supports Curse Spells you cast yourself, causing those Curses to ignore the usual Curse Limit, but be reflected back to you when inflicted.",["description"]="Усиливает чары проклятий, которые вы сотворяете самостоятельно. Усиленные проклятия игнорируют обычный лимит проклятий, но при наложении отражаются в вас.",["name"]="Искушение Атзири"}},
["SupportAtzirisCallPlayer"]={["Atziri's Call"]={["enDescription"]="DNT-UNUSED Supports Spells you use yourself which Hit enemies. On Critical Hit with supported Spells, Trigger Atziri's Storm at the location of the nearest enemy.",["description"]="DNT-UNUSED Supports Spells you use yourself which Hit enemies. On Critical Hit with supported Spells, Trigger Atziri's Storm at the location of the nearest enemy.",["name"]="Призыв Атзири"}},
["SupportAtzirisCommunionPlayer"]={["Atziri's Communion"]={["enDescription"]="Supports Persistent Skills, making them Reserve Life instead of Spirit. Cannot Support Skills which create Minions.",["description"]="Усиливает постоянные умения, заставляя их удерживать здоровье вместо духа. Не может усиливать умения, создающие приспешников.",["name"]="Причастие Атзири"}},
["SupportAtzirisImpatiencePlayer"]={["Atziri's Impatience"]={["enDescription"]="Supports Skills you use yourself that have Cooldowns, dramatically increasing the rate at which those Cooldowns Recover, but causing you to lose Life, Mana, and Energy Shield when they are used. Cannot Support Meta Skills or Persistent Skills, or modify the Skills of Minions.",["description"]="Усиливает самостоятельно используемые вами умения с перезарядкой, кардинально ускоряя перезарядку, но заставляет вас терять здоровье, ману и энергетический щит при их использовании. Не может усиливать мета-умения, постоянные умения и умения приспешников.",["name"]="Нетерпение Атзири"}},
["SupportAutoReloadPlayer"]={["Auto Reload"]={["enDescription"]="Supports Crossbow Ammunition Skills, causing them to automatically reload when they Heavy Stun an enemy.",["description"]="Усиливает умения боезапаса самострелов. Усиленные умения автоматически перезаряжаются при сильном оглушении ими врага.",["name"]="Автоматическая перезарядка"}},
["SupportBarbsPlayer"]={["Barbs I"]={["enDescription"]="Supports Melee Strike Skills. After you Retaliate with Thorns Damage, you also deal your Thorns damage to enemies you Hit with Supported Skills.",["description"]="Усиливает умения ударов ближнего боя. После того как вы нанесли ответный урон шипами, вы также наносите ваш урон от шипов врагам, которых вы поразили усиленными умениями.",["name"]="Колючки I"}},
["SupportBarbsPlayerThree"]={["Barbs III"]={["enDescription"]="Supports Melee Strike Skills. After you Retaliate with Thorns Damage, you also deal your Thorns damage twice to enemies you Hit with Supported Skills.",["description"]="Усиливает умения ударов ближнего боя. После того как вы нанесли ответный урон шипами, вы также дважды наносите ваш урон от шипов врагам, которых вы поразили усиленными умениями.",["name"]="Колючки III"}},
["SupportBarbsPlayerTwo"]={["Barbs II"]={["enDescription"]="Supports Melee Strike Skills. After you Retaliate with Thorns Damage, you also deal your Thorns damage to enemies you Hit with Supported Skills.",["description"]="Усиливает умения ударов ближнего боя. После того как вы нанесли ответный урон шипами, вы также наносите ваш урон от шипов врагам, которых вы поразили усиленными умениями.",["name"]="Колючки II"}},
["SupportBattershoutPlayer"]={["Battershout"]={["enDescription"]="Supports Warcry Skills. Supported Skills Consume Fully Broken Armour to trigger Physical Damage explosions on Enemies within their range but cannot themselves Break Armour.",["description"]="Усиливает умения боевых кличей. Усиленные умения поглощают полностью разрушенную броню и вызывают срабатывание физических взрывов на врагах в пределах области действия, но не могут сами разрушать броню.",["name"]="Крушащий крик"}},
["SupportBeheadPlayer"]={["Behead I"]={["enDescription"]="Supports Strike skills, causing them to steal a Modifier from Rare monsters they kill.",["description"]="Усиливает умения ударов. Усиленные умения похищают свойство у убитых ими редких монстров.",["name"]="Обезглавливание I"}},
["SupportBeheadPlayerTwo"]={["Behead II"]={["enDescription"]="Supports Strike skills, causing them to steal two Modifiers from Rare monsters they kill.",["description"]="Усиливает умения ударов. Усиленные умения похищают два свойства у убитых ими редких монстров.",["name"]="Обезглавливание II"}},
["SupportBhatairsVengeancePlayer"]={["Bhatair's Vengeance"]={["enDescription"]="Supports Attacks and Warcries you use yourself. Freezing an enemy with Supported Skills infuses you and your allies with Cold damage for a short time.",["description"]="Усиливает атаки, которые вы используете самостоятельно. Замораживание врага усиленными умениями наделяет вас и ваших союзников уроном от холода на короткое время.",["name"]="Возмездие Батира"}},
["SupportBiddingPlayer"]={["Bidding I"]={["enDescription"]="Supports Minion Skills. Supported Minions deal more damage and have increased Cooldown Recovery Rate with Command Skills.",["description"]="Усиливает умения приспешников. Усиленные приспешники наносят больше урона и у них повышена скорость перезарядки умений приказов.",["name"]="Приказание I"}},
["SupportBiddingPlayerThree"]={["Bidding III"]={["enDescription"]="Supports Minion Skills. Supported Minions have significantly increased Cooldown Recovery Rate with Command Skills.",["description"]="Усиливает умения приспешников. Усиленные приспешники имеют значительно повышенную скорость перезарядки умений приказов.",["name"]="Приказание III"}},
["SupportBiddingPlayerTwo"]={["Bidding II"]={["enDescription"]="Supports Minion Skills. Supported Minions deal more damage and have increased Cooldown Recovery Rate with Command Skills.",["description"]="Усиливает умения приспешников. Усиленные приспешники наносят больше урона и у них повышена скорость перезарядки умений приказов.",["name"]="Приказание II"}},
["SupportBitingFrostPlayer"]={["Biting Frost I"]={["enDescription"]="Supports any skill that Hits enemies, causing them to deal more damage to Frozen enemies but consume their Freeze. Cannot support skills that Consume Freeze.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения наносят больше урона по замороженным врагам, но поглощают заморозку. Не может усиливать умения, поглощающие заморозку.",["name"]="Кусачий мороз I"}},
["SupportBitingFrostPlayerTwo"]={["Biting Frost II"]={["enDescription"]="Supports any skill that Hits enemies, causing them to deal more damage to Frozen enemies but consume their Freeze, leaving them Chilled. Cannot support skills that Consume Freeze.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения наносят больше урона по замороженным врагам, но поглощают заморозку, оставляя врагов охлаждёнными. Не может усиливать умения, поглощающие заморозку.",["name"]="Кусачий мороз II"}},
["SupportBlazingCriticalPlayer"]={["Blazing Critical"]={["enDescription"]="Supports Skills you use yourself which Hit enemies. Critical Hits with Supported Skills imbue all of your Attacks with Fire damage for a duration.",["description"]="Усиливает самостоятельно используемые вами умения, которые наносят удары по врагам. Критические попадания усиленными умениями временно наделяют все ваши атаки уроном от огня.",["name"]="Жгучие критические удары"}},
["SupportBleedPlayer"]={["Bleed I"]={["enDescription"]="Supports any skill that Hits enemies, giving it a chance to inflict Bleeding.",["description"]="Усиливает любое умение, наносящее удары по врагам, добавляя ему шанс наложения кровотечения.",["name"]="Кровотечение I"}},
["SupportBleedPlayerFour"]={["Bleed IV"]={["enDescription"]="Supports any skill that Hits enemies, causing it to deal more Melee Physical Damage to Bleeding Enemies, but be unable to inflict Bleeding itself. Supported Skills also inflict Incision on Hit.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения наносят больше физического урона в ближнем бою по истекающим кровью врагам, но сами не могут накладывать кровотечение. Усиленные умения также накладывают Разрез при нанесении удара.",["name"]="Кровотечение IV"}},
["SupportBleedPlayerThree"]={["Bleed III"]={["enDescription"]="Supports any skill that Hits enemies, causing it to inflict Bleeding.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения накладывают кровотечение.",["name"]="Кровотечение III"}},
["SupportBleedPlayerTwo"]={["Bleed II"]={["enDescription"]="Supports any skill that Hits enemies, giving it a chance to inflict Bleeding.",["description"]="Усиливает любое умение, наносящее удары по врагам, добавляя ему шанс наложения кровотечения.",["name"]="Кровотечение II"}},
["SupportBlindPlayer"]={["Blind I"]={["enDescription"]="Supports any skill that Hits enemies, causing them to Blind on Hit.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения накладывают ослепление при нанесении удара.",["name"]="Ослепление I"}},
["SupportBlindPlayerTwo"]={["Blind II"]={["enDescription"]="Supports any skill that Hits enemies, causing them to Blind on Hit with increased effect.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения накладывают ослепление при нанесении удара, с усиленным эффектом.",["name"]="Ослепление II"}},
["SupportBlindsidePlayer"]={["Blindside"]={["enDescription"]="Supports Skills which can cause Damaging Hits. Supported Skills are more likely to Critically Hit Blinded Enemies, and deal more Damage with Critical Hits against Blinded Enemies, but cannot themselves inflict Blind.",["description"]="Усиливает умения, которые могут наносить урон ударами. Усиленные умения с большей вероятностью совершают критические попадания по ослеплённым врагам и наносят больше урона критическими попаданиями по ослеплённым врагам, но сами не могут накладывать ослепление.",["name"]="Удар врасплох"}},
["SupportBloodFountainPlayer"]={["Font of Blood"]={["enDescription"]="Supports Skills which create Totems. Totems created by supported Skills generate a Font of Blood which will Leech Life to Allies within it.",["description"]="Усиливает умения, создающие тотемы. Тотемы, созданные усиленными умениями, создают купель крови, которая восстанавливает здоровье от похищения союзникам в ней.",["name"]="Купель крови"}},
["SupportBloodMagicPlayer"]={["Lifetap"]={["enDescription"]="Supports any Skill, turning its Mana cost into a Life cost. Does not support Skills which reserve Spirit.",["description"]="Усиливает любое умение, заменяя его расход маны расходом здоровья. Не может усиливать умения, удерживающие дух.",["name"]="Жизнеотвод"}},
["SupportBloodlustPlayer"]={["Bloodlust"]={["enDescription"]="Supports Melee Attacks, causing them to deal more damage against Bleeding enemies, but preventing them from inflicting Bleeding.",["description"]="Усиливает атаки ближнего боя. Усиленные умения наносят больше урона по истекающим кровью врагам, но при этом не могут накладывать кровотечение.",["name"]="Кровожадность"}},
["SupportBoneShrapnelPlayer"]={["Bone Shrapnel"]={["enDescription"]="Supports Skills which Hit Enemies. Supported Skills trigger Bone Shrapnel explosions when killing Pinned Enemies.",["description"]="Усиливает умения, наносящие удары по врагам. Усиленные умения вызывают срабатывание взрывов костяной шрапнели при убийстве пригвождённых врагов.",["name"]="Костяная шрапнель"}},
["SupportBoundlessEnergyPlayer"]={["Boundless Energy I"]={["enDescription"]="Supports Meta Skills. Supported Skills generate Energy significantly faster.",["description"]="Усиливает мета-умения. Усиленные умения вырабатывают энергию значительно быстрее.",["name"]="Безграничная энергия I"}},
["SupportBoundlessEnergyPlayerTwo"]={["Boundless Energy II"]={["enDescription"]="Supports Meta Skills. Supported Skills generate Energy significantly faster.",["description"]="Усиливает мета-умения. Усиленные умения вырабатывают энергию значительно быстрее.",["name"]="Безграничная энергия II"}},
["SupportBountyPlayer"]={["Bounty I"]={["enDescription"]="Supports any Skill that Hits Enemies, causing Enemies it kills to grant more Flask and Charm charges.",["description"]="Усиливает любое умение, наносящее удары по врагам. Убитые усиленным умением враги даруют больше зарядов флакона и оберега.",["name"]="Щедрость I"}},
["SupportBountyPlayerTwo"]={["Bounty II"]={["enDescription"]="Supports any Skill that Hits Enemies, causing Enemies it kills to grant more Flask and Charm charges.",["description"]="Усиливает любое умение, наносящее удары по врагам. Убитые усиленным умением враги даруют больше зарядов флакона и оберега.",["name"]="Щедрость II"}},
["SupportBrambleslamPlayer"]={["Brambleslam"]={["enDescription"]="Supports Slam Skills, making them Trigger Brambles to create Hazardous brambles which damage and Maim enemies. Does not modify Skills used by Minions or Totems.",["description"]="Усиливает умения мощных ударов. Усиленные умения вызывают срабатывание Терновника, создавая на земле помехи, наносящие урон и увечье. Не может усиливать умения, используемые приспешниками или тотемами.",["screenshot"]="Screenshot_25.png",["pobDescription"]="Supports Slam Skills. Supported Skills create Hazardous Brambles on the ground that activate after a duration. Enemies which come in contact with these thorns take damage and are Maimed. A maximum of 20 Brambles are allowed at one time. Does not modify Skills used by Minions or Totems.",["comparisonNote"]="Описание PoB 0.23.1 дополнительно указывает задержку срабатывания и лимит в 20 колючек.",["name"]="Терновник"}},
["SupportBranchingFissuresPlayer"]={["Branching Fissures I"]={["enDescription"]="Supports Skills which create Fissures in the ground, causing them to create additional secondary Fissures which branch off from the primary fissure, with lowered area of effect and Damage.",["description"]="Усиливает умения, создающие расселины в земле. Усиленные умения создают дополнительные второстепенные расселины, которые ответвляются от основной, со сниженной областью действия и уроном.",["name"]="Ветвящиеся расселины I"}},
["SupportBranchingFissuresPlayerTwo"]={["Branching Fissures II"]={["enDescription"]="Supports Skills which create Fissures in the ground, causing them to create additional secondary Fissures which branch off from the primary fissure, with lowered area of effect and Damage.",["description"]="Усиливает умения, создающие расселины в земле. Усиленные умения создают дополнительные второстепенные расселины, которые ответвляются от основной, со сниженной областью действия и уроном.",["name"]="Ветвящиеся расселины II"}},
["SupportBreachlordsAmalgam"]={["Breachlord's Amalgam"]={["enDescription"]="Supports Lightning or Cold skills you use yourself which fire Projectiles and do not already have cooldowns, adding a cooldown and making the Projectiles return, piercing through targets as they do so.",["description"]="Усиливает самостоятельно используемые вами умения молнии или холода, выпускающие снаряды и не обладающие перезарядкой. Усиленные умения приобретают перезарядку, а их снаряды возвращаются, пронзая цели по пути.",["name"]="Слияние Повелителя Разлома"}},
["SupportBreachlordsRift"]={["Breachlord's Rift"]={["enDescription"]="Supports any skill that Hits enemies, causing it to Break Armour of enemies it Freezes or Electrocutes.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения разрушают броню врагов, которых замораживают или наэлектризовывают.",["name"]="Разрыв повелителя Разлома"}},
["SupportBrinkPlayer"]={["Brink I"]={["enDescription"]="Supports Melee Attack Skills. Supported Skills build up Heavy Stun more quickly, but cannot themselves Heavy Stun.",["description"]="Усиливает умения атак ближнего боя. Усиленные умения накапливают сильное оглушение быстрее, но сами не могут сильно оглушать.",["name"]="Порог I"}},
["SupportBrinkPlayerTwo"]={["Brink II"]={["enDescription"]="Supports Melee Attack Skills. Supported Skills build up Stun more quickly, but cannot themselves Stun.",["description"]="Усиливает умения атак ближнего боя. Усиленные умения накапливают оглушение быстрее, но сами не могут оглушать.",["name"]="Порог II"}},
["SupportBrittleArmourPlayer"]={["Brittle Armour"]={["enDescription"]="Supports Skills which can Hit enemies. Hits with Supported Skills which Freeze enemies cause Physical damage against them to Break their Armour while they remain Frozen.",["description"]="Усиливает умения, которые могут наносить удары по врагам. Удары усиленными умениями, которые замораживают врагов, заставляют наносимый им физический урон разрушать их броню, пока враги остаются замороженными.",["name"]="Хрупкая броня"}},
["SupportBrutalityPlayer"]={["Brutality I"]={["enDescription"]="Supports any skill that deals damage, boosting its Physical damage at the expense of all other Damage Types.",["description"]="Усиливает любое умение, наносящее урон, повышая его физический урон за счёт всех остальных типов урона.",["name"]="Жестокость I"}},
["SupportBrutalityPlayerThree"]={["Brutality III"]={["enDescription"]="Supports any skill that deals damage, boosting its Physical damage at the expense of all other Damage Types, as well as giving Hits from that skill a chance to ignore Physical Damage reduction.",["description"]="Усиливает любое умение, наносящее урон, повышая его физический урон за счёт всех остальных типов урона. Удары усиленными умениями также имеют шанс игнорировать уменьшение получаемого физического урона.",["name"]="Жестокость III"}},
["SupportBrutalityPlayerTwo"]={["Brutality II"]={["enDescription"]="Supports any skill that deals damage, boosting its Physical damage at the expense of all other Damage Types.",["description"]="Усиливает любое умение, наносящее урон, повышая его физический урон за счёт всех остальных типов урона.",["name"]="Жестокость II"}},
["SupportBrutusBrainPlayer"]={["Brutus' Brain"]={["enDescription"]="Supports skills which create Minions, causing those Minions to be unable to deal or take Damage. Cannot support skills which create undamageable Minions.",["description"]="Усиливает умения, создающие приспешников. Приспешники не могут получать или наносить урон. Не может усиливать умения, создающие приспешников, которым нельзя нанести урон.",["name"]="Мозг Изувера"}},
["SupportBuffedHeraldPlayer"]={["Infusion"]={["enDescription"]="Supports Persistent Buff Skills, making the Buff they grant more powerful.",["description"]="Усиливает умения с постоянными положительными эффектами, делая эти положительные эффекты мощнее.",["name"]="Интенсивность"}},
["SupportBurgeonPlayer"]={["Burgeon I"]={["enDescription"]="Supports Channelling Skills you use yourself, causing them to deal more damage the longer they have been Channelled.",["description"]="Усиливает поддерживаемые умения, которые вы используете самостоятельно. Усиленные умения наносят тем больше урона, чем дольше длится их поддержание.",["name"]="Разрастание I"}},
["SupportBurgeonPlayerTwo"]={["Burgeon II"]={["enDescription"]="Supports Channelling Skills you use yourself, causing them to deal more damage the longer they have been Channelled.",["description"]="Усиливает поддерживаемые умения, которые вы используете самостоятельно. Усиленные умения наносят тем больше урона, чем дольше длится их поддержание.",["name"]="Разрастание II"}},
["SupportBurningRunesPlayer"]={["Burning Inscription"]={["enDescription"]="Supports any Skill which creates Runic Inscriptions when Cast, causing those Runic Inscriptions to trigger Burning Inscription when they expire. Burning Inscription is a Spell which creates Ignited Ground based off of your Maximum Mana.",["description"]="Усиливает любое умение, создающее рунические начертания при сотворении. После истечения рунические начертания вызывают срабатывание Пылающего начертания. Пылающее начертание – это чары, которые создают подожжённую землю на основе максимума вашей маны.",["name"]="Пылающее начертание"}},
["SupportBurstingPlaguePlayer"]={["Bursting Plague"]={["enDescription"]="Supports skills that can Poison enemies, causing Poisoned enemies to gain Plague over time and explode in a Plague Burst on death. Cannot support the skills of Minions.",["description"]="Усиливает умения, которые могут отравлять врагов. Отравленные враги получают постепенный эффект Чумы и взрываются Взрывом чумы при смерти. Не может усиливать умения приспешников.",["name"]="Вспышка чумы"}},
["SupportCadencePlayer"]={["Cadence"]={["enDescription"]="Supports Attacks you use yourself. Supported Skills gain more Attack speed each time you use them, but will become unusable if used too frequently in a short time frame. Sustained Skills will instead gain Attack speed periodically while being used.",["description"]="Усиливает атаки, которые вы используете самостоятельно. Усиленные умения приобретают всё большую скорость атаки при каждом использовании, но станут недоступными, если использовать их слишком часто за короткий промежуток времени. Непрерывные умения вместо этого приобретают скорость атаки периодически во время использования.",["name"]="Ритм"}},
["SupportCaltropsPlayer"]={["Caltrops"]={["enDescription"]="Supports Ranged Spear Attacks. Supported Skills create Caltrops when Projectiles they create reach the end of their flight.",["description"]="Усиливает дальнобойные атаки копьём. Усиленные умения разбрасывают кальтропы, когда созданные ими снаряды достигают конца полёта.",["name"]="Кальтропы"}},
["SupportCannibalismPlayer"]={["Cannibalism I"]={["enDescription"]="Supports Persistent Buff Skills, causing you to recover Life on kill while the Skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами. Пока активно, усиленное умение даёт вам восстановление здоровья при убийстве.",["name"]="Каннибализм I"}},
["SupportCannibalismPlayerTwo"]={["Cannibalism II"]={["enDescription"]="Supports Persistent Buff Skills, causing you to recover Life on kill while the Skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами. Пока активно, усиленное умение даёт вам восстановление здоровья при убийстве.",["name"]="Каннибализм II"}},
["SupportCatalysingElementsPlayer"]={["Catalysing Elements"]={["enDescription"]="Supports Skills which are boosted by Elemental Ground Surfaces, Triggering Catalysing Discharge of the corresponding type when they are boosted by an allied Elemental Ground Surface.",["description"]="Усиливает умения, которые взаимодействуют со стихийными наземными эффектами, вызывая срабатывание Катализирующего разряда соответствующего типа, когда они усиливаются дружественным стихийным наземным эффектом.",["name"]="Катализирующие стихии"}},
["SupportCatharsisPlayer"]={["Catharsis"]={["enDescription"]="Supports any Skill you use yourself, causing supported Skill to detonate Volatility that is present on you. Supported Skill can only be used while you have a certain amount of Volatility and cannot support Skills which already have another Condition.",["description"]="Усиливает любое умение, которое вы используете самостоятельно, заставляя его подрывать присутствующую на вас Нестабильность. Усиленное умение можно использовать только если вы накопили определённый заряд Нестабильности. Не может усиливать умения, уже обладающие другим условием.",["name"]="Катарсис"}},
["SupportCathasBrilliance"]={["Catha's Brilliance"]={["enDescription"]="Supports skills which create Companions, causing enemies near them to be Blinded and Ignited. The damage of the Ignite is based on the Life of the supported Minion.",["description"]="Усиливает умения, создающие компаньонов, ослепляя и поджигая врагов рядом с ними. Урон, наносимый поджогом, основывается на здоровье усиленного Minion|приспешника].",["name"]="Великолепие Каты"}},
["SupportChainPlayer"]={["Chain I"]={["enDescription"]="Supports Projectile skills and any other skills that Chain, causing them to Chain additional times.",["description"]="Усиливает умения снарядов и любые другие умения, наносящие удары по цепи. Усиленные умения наносят дополнительные удары по цепи.",["name"]="Цепь I"}},
["SupportChainPlayerThree"]={["Chain III"]={["enDescription"]="Supports Projectile skills and any other skills that Chain, causing them to Chain additional times.",["description"]="Усиливает умения снарядов и любые другие умения, наносящие удары по цепи. Усиленные умения наносят дополнительные удары по цепи.",["name"]="Цепь III"}},
["SupportChainPlayerTwo"]={["Chain II"]={["enDescription"]="Supports Projectile skills and any other skills that Chain, causing them to Chain additional times.",["description"]="Усиливает умения снарядов и любые другие умения, наносящие удары по цепи. Усиленные умения наносят дополнительные удары по цепи.",["name"]="Цепь II"}},
["SupportChaosMasteryPlayer"]={["Chaos Mastery"]={["enDescription"]="Supports Chaos skills, granting them an additional level. Does not support skills which do not have levels.",["description"]="Усиливает умения хаоса, даруя им дополнительный уровень. Не усиливает умения, не имеющие уровней.",["name"]="Мастерство хаоса"}},
["SupportChaoticFreezePlayer"]={["Chaotic Freeze"]={["enDescription"]="Supports Spells that deal non-Ailment Chaos damage over time. Enemies taking damage over time from Debuffs caused by supported skills will suffer Freeze build up from Chaos damage Hits from any source. Does not Support Skills used by Minions.",["description"]="Усиливает чары, наносящие постепенный урон хаосом не от состояний. Враги, получающие постепенный урон от отрицательных эффектов, вызванных усиленными умениями, накапливают заморозку от наносящих урон хаосом ударов из любого источника. Не может усиливать умения, используемые приспешниками.",["name"]="Хаотичная заморозка"}},
["SupportChargeInhibitionPlayer"]={["Inhibitor"]={["enDescription"]="Supports any Skill you use or Trigger yourself. Supported Skills cannot consume Charges or Infusion by any means. Cannot Support Skills which require Charges or Infusion to be used.",["description"]="Усиливает любое умение, которое вы используете самостоятельно или сами вызываете его срабатывание. Усиленные умения не могут поглощать заряды или насыщения никаким образом. Не может усиливать умения, требующие зарядов или насыщений для использования.",["name"]="Ингибитор"}},
["SupportChargeProfusionPlayer"]={["Charge Profusion I"]={["enDescription"]="Supports skills that can generate Charges, giving them a chance to generate an additional Charge when they do so.",["description"]="Усиливает умения, которые могут вырабатывать заряды, даруя им шанс выработать дополнительный заряд.",["name"]="Избыток зарядов I"}},
["SupportChargeProfusionPlayerTwo"]={["Charge Profusion II"]={["enDescription"]="Supports skills that can generate Charges, giving them a chance to generate an additional Charge when they do so, as well as a chance to generate an additional Charge of a random type.",["description"]="Усиливает умения, которые могут вырабатывать заряды, даруя им шанс выработать дополнительный заряд, а также шанс даровать ещё один заряд случайного типа.",["name"]="Избыток зарядов II"}},
["SupportChargedMarkPlayer"]={["Charged Mark"]={["enDescription"]="Supports Mark Skills, causing them to Trigger Charged Mark when they are Activated. Charged Mark creates Shocked Ground at the target's location.",["description"]="Усиливает умения меток. Метки от усиленных умений вызывают срабатывание Заряженной метки при активации. Заряженная метка создаёт заряженную землю на месте цели.",["name"]="Заряженная метка"}},
["SupportChargedShotsPlayer"]={["Charged Shots I"]={["enDescription"]="Supports Bow Attacks. Every third shot with Supported Skills restores a portion of its Mana cost and Gains Damage as extra Lightning Damage.",["description"]="Усиливает атаки луками. Каждый третий выстрел усиленными умениями восстанавливает часть от его расхода маны и приобретает дополнительный урон от молнии.",["name"]="Заряженные выстрелы I"}},
["SupportChargedShotsPlayerTwo"]={["Charged Shots II"]={["enDescription"]="Supports Bow Attacks. Every third shot with Supported Skills Gains Damage as extra Lightning Damage.",["description"]="Усиливает атаки луками. Каждый третий выстрел усиленными умениями приобретает дополнительный урон от молнии.",["name"]="Заряженные выстрелы II"}},
["SupportCharmBountyPlayer"]={["Charm Bounty"]={["enDescription"]="Supports any Skill that Hits Enemies, causing Enemies it kills to grant more Charm charges.",["description"]="Усиливает любое умение, наносящее удары по врагам. Убитые усиленным умением враги даруют больше зарядов оберега.",["name"]="Щедрый оберег"}},
["SupportChillingIcePlayer"]={["Frost Nexus"]={["enDescription"]="Supports any skill that Hits enemies, causing it to create patches of Chilled Ground around Frozen enemies.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения создают участки замёрзшей земли вокруг замороженных врагов.",["name"]="Очаг холода"}},
["SupportCirelsCultivationPlayer"]={["Cirel's Cultivation"]={["enDescription"]="Supports Skills which create Totems, preventing you from having more than one of that Totem but granting significant benefits for Supported Totems based how many allied Totems are near them. Does not Support Skills used by Minions.",["description"]="Усиливает умения, создающие тотемы, не позволяя иметь более одного тотема от усиленного умения, но даруя существенные прибавки к его эффектам в зависимости от числа союзных тотемов поблизости. Не усиливает умения, используемые приспешниками.",["name"]="Культивация Сирэл"}},
["SupportClarityPlayer"]={["Clarity I"]={["enDescription"]="Supports Persistent Buff Skills, causing you to gain increased Mana Regeneration while the Skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами. Пока активно, усиленное умение даёт вам увеличенную регенерацию маны.",["name"]="Ясность ума I"}},
["SupportClarityPlayerTwo"]={["Clarity II"]={["enDescription"]="Supports Persistent Buff Skills, causing you to gain increased Mana Regeneration while the Skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами. Пока активно, усиленное умение даёт вам увеличенную регенерацию маны.",["name"]="Ясность ума II"}},
["SupportClashPlayer"]={["Clash"]={["enDescription"]="Supports Melee Attack Skills. Supported Skills deal more Damage while you have a lower percentage of your Life remaining than the target struck, but less Damage when the reverse is true.",["description"]="Усиливает умения атак ближнего боя. Усиленные умения наносят больше урона, пока у вас меньший процент здоровья, чем у поражаемой цели, но меньше урона, если наоборот.",["name"]="Стычка"}},
["SupportCloseCombatPlayer"]={["Close Combat I"]={["enDescription"]="Supports Attacks, causing them to deal more damage to enemies based on how close they are to you.",["description"]="Усиливает атаки. Усиленные умения наносят больше урона врагам в зависимости от их близости к герою.",["name"]="Бой вплотную I"}},
["SupportCloseCombatPlayerTwo"]={["Close Combat II"]={["enDescription"]="Supports Attacks, causing them to deal more damage to enemies based on how close they are to you.",["description"]="Усиливает атаки. Усиленные умения наносят больше урона врагам в зависимости от их близости к герою.",["name"]="Бой вплотную II"}},
["SupportColdExposurePlayer"]={["Cold Exposure"]={["enDescription"]="Supports any skill that Hits enemies, causing it to inflict Exposure when it inflicts Freeze.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения накладывают восприимчивость при заморозке.",["screenshot"]="Screenshot_24.png",["pobDescription"]="Supports any skill that Hits enemies, causing it to inflict Exposure when it Critically Hits an enemy.",["comparisonNote"]="В игре описание указывает заморозку. Строка свойства и данные PoB 0.23.1 указывают критический удар уроном от холода.",["name"]="Восприимчивость к холоду"}},
["SupportColdMasteryPlayer"]={["Cold Mastery"]={["enDescription"]="Supports Cold skills, granting them an additional level. Does not support skills which do not have levels.",["description"]="Усиливает умения холода, даруя им дополнительный уровень. Не усиливает умения, не имеющие уровней.",["name"]="Мастерство холода"}},
["SupportColdPenetrationPlayer"]={["Cold Penetration"]={["enDescription"]="Supports any skill that Hits enemies, making those Hits Penetrate enemy Cold resistance.",["description"]="Усиливает любое умение, наносящее удары по врагам. Удары этим умением пробивают вражеское сопротивление холоду.",["name"]="Пронизывающий холод"}},
["SupportCombatReloadPlayer"]={["Ratha's Assault"]={["enDescription"]="Supports Crossbow Ammunition Skills, causing them to load multiple extra bolts and attack faster. Supported Skills cannot reload normally, instead loading bolts when you Dodge.",["description"]="Усиливает умения боезапаса самострелов. Усиленные умения заряжают несколько дополнительных болтов и атакуют быстрее, но не могут перезаряжаться как обычно, вместо этого заряжая болты при увороте кувырком.",["name"]="Нападение Раты"}},
["SupportComboFinisherPlayer"]={["Combo Finisher I"]={["enDescription"]="Supports Melee Attacks you use yourself. Supported Skills cannot be used until enough Combo has been built up, but deal more damage. Cannot support skills which already Combo.",["description"]="Усиливает атаки ближнего боя, которые вы используете самостоятельно. Усиленные умения нельзя использовать, пока не будет накоплено достаточное Комбо, но они наносят больше урона. Не может усиливать умения, уже накапливающие Комбо.",["name"]="Финальный удар I"}},
["SupportComboFinisherPlayerTwo"]={["Combo Finisher II"]={["enDescription"]="Supports Melee Attacks you use yourself. Supported Skills cannot be used until enough Combo has been built up, but deal massively more damage. Cannot support skills which already Combo.",["description"]="Усиливает атаки ближнего боя, которые вы используете самостоятельно. Усиленные умения нельзя использовать, пока не будет накоплено достаточное Комбо, но они наносят гораздо больше урона. Не может усиливать умения, уже накапливающие Комбо.",["name"]="Финальный удар II"}},
["SupportCommandment"]={["Commandment"]={["enDescription"]="Supports Minions which have Command Skills. Supported Minions have massively increased cooldown recovery speed for Command Skills they use, but deal no damage with non-Command Skills.",["description"]="Усиливает приспешников с умениями приказов. Усиленные приспешники имеют резко повышенную скорость перезарядки умений приказов, но не наносят урона умениями не-приказов.",["name"]="Повеление"}},
["SupportCommiseratePlayer"]={["Commiserate"]={["enDescription"]="Supports Skills you use or Trigger yourself, which can cause Damaging Hits. Supported Skills inflict more powerful Ailments if you are afflicted with those Ailments when you inflict them, while also removing from you any Ailment that they inflict.",["description"]="Усиливает умения, которые вы используете самостоятельно или сами вызываете их срабатывание, способные наносить урон ударами. Усиленные умения накладывают более сильные состояния, если вы сами находитесь под действием этих состояний в момент их наложения, и при этом снимают с вас любые состояния, которые накладывают.",["name"]="Сострадание"}},
["SupportConcentratedAreaPlayer"]={["Concentrated Area"]={["enDescription"]="Supports any skill with an area of effect, causing that area to be smaller but any area damage it deals to be higher.",["description"]="Усиливает любое умение с областью действия, уменьшая эту область, но повышая любой наносимый умением урон по области.",["name"]="Средоточие"}},
["SupportConcoctPlayer"]={["Concoct I"]={["enDescription"]="Supports Skills you use yourself which Damage enemies with Hits. Supported Skills consume a percentage of your maximum Life Flask charges, inflicting more powerful Bleeding based on Life Flask charges consumed.",["description"]="Усиливает самостоятельно используемые вами умения, которые наносят урон врагам ударами. Усиленные умения поглощают часть вашего максимума зарядов флакона здоровья, накладывая более сильное кровотечение в зависимости от количества поглощённых зарядов флаконов здоровья.",["name"]="Варево I"}},
["SupportConcoctPlayerTwo"]={["Concoct II"]={["enDescription"]="Supports Skills you use yourself which Damage enemies with Hits. Supported Skills consume a percentage of your maximum Life Flask charges, inflicting more powerful Bleeding based on Life Flask charges consumed.",["description"]="Усиливает самостоятельно используемые вами умения, которые наносят урон врагам ударами. Усиленные умения поглощают часть вашего максимума зарядов флакона здоровья, накладывая более сильное кровотечение в зависимости от количества поглощённых зарядов флаконов здоровья.",["name"]="Варево II"}},
["SupportConcussiveRunesPlayer"]={["Concussive Runes"]={["enDescription"]="Supports Attacks, causing a Runic Shockwave to erupt under enemies they Heavy Stun. The Shockwave costs Runic Ward, and will not Trigger if you do not have enough Runic Ward.",["description"]="Усиливает атаки, вызывая руническую ударную волну под врагами, которых они сильно оглушают. Ударная волна тратит рунический барьер и не срабатывает, если у вас недостаточно рунического барьера.",["name"]="Сотрясающие руны"}},
["SupportConcussiveSpellsPlayer"]={["Concussive Spells"]={["enDescription"]="Supports Spells which Hit enemies. Supported Skills Daze on Critically Hitting enemies with Physical damage.",["description"]="Усиливает чары, наносящие удары по врагам. Усиленные умения накладывают оцепенение на врагов при критическом попадании по ним физическим уроном.",["name"]="Сотрясающие чары"}},
["SupportConsideredCastingPlayer"]={["Considered Casting"]={["enDescription"]="Supports Spell Skills that Hit Enemies and you cast yourself, boosting Damage at the cost of Cast Speed.",["description"]="Усиливает умения чар, которые наносят удары по врагам и которые вы сотворяете самостоятельно. Урон усиленных чар увеличивается ценой скорости сотворения.",["name"]="Вдумчивое сотворение"}},
["SupportControlledDestructionPlayer"]={["Controlled Destruction"]={["enDescription"]="Supports Spells that Hit enemies, boosting their damage but preventing them from dealing Critical Hits.",["description"]="Усиливает чары, которые наносят удары по врагам, повышая их урон, но не позволяя этим чарам наносить критические попадания.",["name"]="Контролируемое разрушение"}},
["SupportControlledHazardPlayer"]={["Controlled Hazard"]={["enDescription"]="Supports Skills which create Hazards, causing those Hazards to be unable to be triggered for 3 seconds after being created.",["description"]="Усиливает умения, создающие помехи, не позволяя этим помехам срабатывать в течение 3 секунд после создания.",["name"]="Управляемые помехи"}},
["SupportCooldownRecoveryPlayer"]={["Cooldown Recovery I"]={["enDescription"]="Supports skills with Cooldowns, increasing the rate at which those Cooldowns Recover. Cannot modify the skills of minions.",["description"]="Усиливает умения с перезарядкой, ускоряя перезарядку. Не усиливает умения приспешников.",["name"]="Ускорение перезарядки I"}},
["SupportCooldownRecoveryPlayerTwo"]={["Cooldown Recovery II"]={["enDescription"]="Supports skills with Cooldowns, increasing the rate at which those Cooldowns Recover. Cannot modify the skills of minions.",["description"]="Усиливает умения с перезарядкой, ускоряя перезарядку. Не усиливает умения приспешников.",["name"]="Ускорение перезарядки II"}},
["SupportCoolheadedPlayer"]={["Cool Headed"]={["enDescription"]="Supports Persistent Buff Skills, causing Ignite applied to you to last for a shorter duration while the Supported Skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами. Пока усиленное умение активно, наложенные на вас поджоги длятся меньше.",["name"]="Хладнокровие"}},
["SupportCorpseConservationPlayer"]={["Corpse Conservation"]={["enDescription"]="Supports skills that consume Corpses, giving them a chance to take effect without destroying the Corpse.",["description"]="Усиливает умения, поглощающие трупы, давая им шанс подействовать без уничтожения трупа.",["name"]="Сохранение трупов"}},
["SupportCorrosionPlayer"]={["Corrosion"]={["enDescription"]="Supports any skill that Hits enemies, causing Poison it applies to also Break enemy Armour. Cannot support skills that Consume Fully Broken Armour.",["description"]="Усиливает любое умение, наносящее удары по врагам. Накладываемый усиленными умениями яд также разрушает вражескую броню. Не может усиливать умения, поглощающие полностью разрушенную броню.",["name"]="Коррозия"}},
["SupportCorruptingCryPlayer"]={["Corrupting Cry I"]={["enDescription"]="Supports Warcries, Triggering Corrupted Cry to inflict Corrupted Blood on enemies in their area of effect.",["description"]="Усиливает боевые кличи, вызывая срабатывание Осквернённого клича, накладывающего Осквернённую кровь на врагов в области их действия.",["name"]="Оскверняющий клич I"}},
["SupportCorruptingCryPlayerThree"]={["Paquate's Pact"]={["enDescription"]="Supports Warcries, Triggering Twisted Pact  to inflict Corrupted Blood on enemies in their area of effect., at the cost of your Life.",["description"]="Усиливает боевые кличи, вызывая срабатывание Порочного договора, накладывающего Осквернённую кровь на врагов в области их действия ценой вашего здоровья.",["name"]="Пакт Паквате"}},
["SupportCorruptingCryPlayerTwo"]={["Corrupting Cry II"]={["enDescription"]="Supports Warcries, Triggering Corrupted Cry to inflict Corrupted Blood on enemies in their area of effect.",["description"]="Усиливает боевые кличи, вызывая срабатывание Осквернённого клича, накладывающего Осквернённую кровь на врагов в области их действия.",["name"]="Оскверняющий клич II"}},
["SupportCracklingBarrierPlayer"]={["Crackling Barrier"]={["enDescription"]="Supports Channelling Skills. While Channelling Supported Skills, you gain Lightning Thorns based off of your maximum Mana.",["description"]="Усиливает поддерживаемые умения. Во время поддержания усиленных умений вы получаете шипы молний на основе максимума маны.",["name"]="Искрящий барьер"}},
["SupportCraterPlayer"]={["Crater"]={["enDescription"]="Supports Melee Skills that leap into the air, causing them to create Fissures when you land. Cannot Support Totem Skills, and does not modify Skills used by Minions.",["description"]="Усиливает умения ближнего боя с прыжком в воздух. Усиленные умения создают расселины в месте приземления. Не может усиливать умения тотемов и умения, используемые приспешниками.",["name"]="Кратер"}},
["SupportCrazedMinionsPlayer"]={["Crazed Minions"]={["enDescription"]="Supports Minion Skills which summon Reviving Minions. Supported Minions deal significantly more Damage if they have Revived Recently.",["description"]="Усиливает умения приспешников, призывающие возрождающихся приспешников. Усиленные приспешники наносят значительно больше урона, если недавно возродились.",["name"]="Шальные приспешники"}},
["SupportCreepingChillPlayer"]={["Creeping Chill"]={["enDescription"]="Supports any Skill that creates Ice Crystals, causing that Skill to Consume a Power Charge if possible to create Chilled Ground around the Crystal.",["description"]="Усиливает любое умение, создающее ледяные кристаллы. Усиленное умение поглощает заряд энергии, если возможно, чтобы создать замёрзшую землю вокруг кристалла.",["name"]="Ползучий хлад"}},
["SupportCrescendoPlayer"]={["Crescendo I"]={["enDescription"]="Supports Strikes that perform a Final Strike at the end of a combination of attacks, allowing you to use the Final Strike twice in succession.",["description"]="Усиливает удары, наносящие завершающий удар в конце комбинации атак, позволяя последовательно совершить завершающий удар дважды.",["name"]="Крещендо I"}},
["SupportCrescendoPlayerThree"]={["Crescendo III"]={["enDescription"]="Supports Strikes that perform a Final Strike at the end of a combination of attacks, causing the Final Strike to be Ancestrally Boosted.",["description"]="Усиливает удары, наносящие завершающий удар в конце комбинации атак, даруя завершающему удару усиление предками.",["name"]="Крещендо III"}},
["SupportCrescendoPlayerTwo"]={["Crescendo II"]={["enDescription"]="Supports Strikes that perform a Final Strike at the end of a combination of attacks, allowing you to use the Final Strike twice in succession, and causing Non-Final Strike Attacks to be faster.",["description"]="Усиливает удары, наносящие завершающий удар в конце комбинации атак, позволяя последовательно совершить завершающий удар дважды и ускоряя атаки не завершающими ударами.",["name"]="Крещендо II"}},
["SupportCrystallineShardsPlayer"]={["Crystalline Shards"]={["enDescription"]="Supports Skills which create Ice Crystals. Damaging Explosions caused by Ice Crystals from Supported Skills will Impale Enemies.",["description"]="Усиливает умения, создающие ледяные кристаллы. Наносящие урон взрывы, вызванные ледяными кристаллами от усиленных умений, прокалывают врагов.",["name"]="Кристальные осколки"}},
["SupportCullingStrikePlayer"]={["Culling Strike I"]={["enDescription"]="Supports Attack Skills, causing them to Cull Rare and Unique Enemies on Hit.",["description"]="Усиливает умения атак. Усиленные умения добивают редких и уникальных врагов при нанесении удара.",["name"]="Добивание I"}},
["SupportCullingStrikePlayerTwo"]={["Culling Strike II"]={["enDescription"]="Supports Attack Skills, causing them to Cull Rare and Unique Enemies on Hit, and increasing the threshold at which they will Cull Enemies.",["description"]="Усиливает умения атак. Усиленные умения добивают редких и уникальных врагов при нанесении удара, при этом порог добивания увеличивается.",["name"]="Добивание II"}},
["SupportCulminationPlayer"]={["Culmination I"]={["enDescription"]="Supports Melee Attack Skills. Supported Skills gain Combo when you successfully Strike Enemies with other Melee Attacks. Supported Skills reset their Combo on use, dealing more Damage the higher Combo you had on use. Cannot support skills which already gain Combo. Cannot modify the Skills of Minions.",["description"]="Усиливает умения атак ближнего боя. Усиленные умения накапливают Комбо при успешных ударах по врагам другими атаками ближнего боя. Усиленные умения сбрасывают Комбо при  использовании и наносят тем больше урона, чем выше был счётчик Комбо в момент использования. Не может усиливать умения, уже накапливающие Комбо. Не усиливает умения приспешников.",["name"]="Кульминация I"}},
["SupportCulminationPlayerTwo"]={["Culmination II"]={["enDescription"]="Supports Melee Attack Skills. Supported Skills gain Combo when you successfully Strike Enemies with other Melee Attacks. Supported Skills reset their Combo on use, dealing more Damage the higher Combo you had on use. Cannot support skills which already gain Combo. Cannot modify the Skills of Minions.",["description"]="Усиливает умения атак ближнего боя. Усиленные умения накапливают Комбо при успешных ударах по врагам другими атаками ближнего боя. Усиленные умения сбрасывают Комбо при  использовании и наносят тем больше урона, чем выше был счётчик Комбо в момент использования. Не может усиливать умения, уже накапливающие Комбо. Не усиливает умения приспешников.",["name"]="Кульминация II"}},
["SupportCurseEffectPlayer"]={["Heightened Curse"]={["enDescription"]="Supports Curse Skills, magnifying their power.",["description"]="Усиливает умения проклятий, увеличивая их мощь.",["name"]="Возвышенное проклятие"}},
["SupportCursedGroundPlayer"]={["Cursed Ground"]={["enDescription"]="Supports Curse Skills. Supported Curse Skills create areas which Curse Enemies so long as they are within them.",["description"]="Усиливает умения проклятий. Усиленные умения проклятий создают области, которые проклинают врагов, покуда те остаются в них.",["name"]="Проклятая земля"}},
["SupportDanseMacabrePlayer"]={["Danse Macabre"]={["enDescription"]="Supports Offering Skills. Supported Skills have increased Buff effect and deal more damage, but will target an additional skeletal Minion when cast. If there is not an additional skeletal Minion to target, no damage or Buff effect will be granted.",["description"]="Усиливает умения подношений. Усиленные умения дают более сильные положительные эффекты и наносят больше урона, но при сотворении выбирают целью дополнительного скелета-приспешника. Если такового нет, умение не получит прибавок к урону или усиления положительных эффектов.",["name"]="Пляска смерти"}},
["SupportDaressosPassionPlayer"]={["Daresso's Passion"]={["enDescription"]="Supports Banner Skills, causing them to require significantly less Glory to use.",["description"]="Усиливает умения знамён. Усиленные умения требуют значительно меньше славы для использования.",["name"]="Страсть Дарессо"}},
["SupportDauntlessPlayer"]={["Dauntless"]={["enDescription"]="Supports Skills you use yourself which can cause Damaging Hits. Supported Skills cannot be used unless you have been stationary for a certain duration, but deal increasingly more damage the longer you are stationary. Cannot support Skills which have a cooldown or another usage Condition.",["description"]="Усиливает самостоятельно используемые вами умения, способные наносить урон ударами. Усиленные умения можно использовать только после того, как вы некоторое время простоите на одном месте, но они наносят тем больше урона, чем дольше вы остаётесь на месте. Не может усиливать умения, обладающие перезарядкой или иным условием использования.",["name"]="Бесстрашие"}},
["SupportDazePlayer"]={["Daze"]={["enDescription"]="Supports Attacks, causing them to build up Daze based on a portion of Physical Damage dealt.",["description"]="Усиливает атаки. Усиленные умения накапливают оцепенение на основе части нанесённого физического урона.",["name"]="Оцепенение"}},
["SupportDazedBreakPlayer"]={["Break Posture"]={["enDescription"]="Supports Attacks, causing them to Daze Enemies when they fully Break Armour.",["description"]="Усиливает атаки. Усиленные умения накладывают оцепенение на врагов при полном разрушении брони.",["name"]="Вышибание"}},
["SupportDazingCryPlayer"]={["Dazing Cry"]={["enDescription"]="Supports Warcries, causing them to Daze Enemies on use.",["description"]="Усиливает боевые кличи. Усиленные кличи накладывают оцепенение на врагов при использовании.",["name"]="Оцепеняющий клич"}},
["SupportDazzlePlayer"]={["Dazzle"]={["enDescription"]="Supports Attack Skills. Supported Skills always hit Dazed Enemies, but Consume Daze on Hit, and cannot themselves inflict Daze. Cannot Support Skills which Consume Daze.",["description"]="Усиливает умения атак. Усиленные умения всегда попадают по оцепеневшим врагам, но поглощают оцепенение при нанесении удара и не могут сами накладывать оцепенение. Не может усиливать умения,  поглощающие оцепенение.",["name"]="Вспышка"}},
["SupportDeadlyCurrentPlayer"]={["Coursing Current"]={["enDescription"]="Supports Skills which Hit enemies. Shocking an enemy with Supported Skills Triggers Coursing Current, which sends Chaining Lightning Projectiles to nearby Drenched enemies.",["description"]="Усиливает умения, наносящие удары по врагам. Наложение шока на врага усиленными умениями вызывает срабатывание Скачущего напряжения, которое отправляет бьющие по цепи снаряды молнии в ближайших промокших врагов.",["name"]="Скачущее напряжение"}},
["SupportDeadlyHeraldsPlayer"]={["Deadly Herald"]={["enDescription"]="Supports Herald Skills, making their triggered effects deal more damage at the expense of higher Spirit cost.",["description"]="Усиливает умения вестников. Активируемые ими эффекты наносят больше урона, но при этом увеличивается количестно удерживаемого духа.",["name"]="Смертоносный вестник"}},
["SupportDeadlyIgnitesPlayer"]={["Searing Flame I"]={["enDescription"]="Supports any skill that Hits enemies, causing inflicted Ignites to deal more damage but its Hits to deal less damage.",["description"]="Усиливает любое умение, наносящее удары по врагам. Поджоги усиленных умений наносят больше урона, но их удары наносят меньше урона.",["name"]="Обжигающее пламя I"}},
["SupportDeadlyIgnitesPlayerTwo"]={["Searing Flame II"]={["enDescription"]="Supports any skill that Hits enemies, causing inflicted Ignites to deal more damage but its Hits to deal less damage.",["description"]="Усиливает любое умение, наносящее удары по врагам. Поджоги усиленных умений наносят больше урона, но их удары наносят меньше урона.",["name"]="Обжигающее пламя II"}},
["SupportDeadlyPoisonPlayer"]={["Deadly Poison I"]={["enDescription"]="Supports any skill that Hits enemies, causing it to deal less damage but inflict more potent Poison.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения наносят меньше урона, но накладывают более сильное отравление.",["name"]="Смертельный яд I"}},
["SupportDeadlyPoisonPlayerTwo"]={["Deadly Poison II"]={["enDescription"]="Supports any skill that Hits enemies, causing it to deal less damage but inflict more potent Poison.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения наносят меньше урона, но накладывают более сильное отравление.",["name"]="Смертельный яд II"}},
["SupportDeadlyResolvePlayer"]={["Deadly Resolve"]={["enDescription"]="Supports Channelling Skills you use yourself. While Channelling Supported Skills, periodically gain stages of Deadly Resolve. Expend a stage of Deadly Resolve when an enemy Hits you to Trigger a deadly slash towards that enemy, dealing more damage based on your Armour.",["description"]="Усиливает поддерживаемые умения, которые вы используете самостоятельно. Во время поддержания усиленных умений периодически дарует стадии Смертоносной решимости. Тратит стадию Смертоносной решимости, когда противник наносит удар по вам, вызывая срабатывание смертоносного удара в сторону этого противника. Смертоносная решимость наносит больше урона на основе вашей брони.",["name"]="Смертоносная решимость"}},
["SupportDeathmarchPlayer"]={["Deathmarch"]={["enDescription"]="Supports Skills which create Persistent Minions. Supported Minions will restore Life to nearby Allied Minions on death, as well as removing Ailments from those Minions.",["description"]="Усиливает умения, создающие постоянных приспешников. Усиленные приспешники восстановят часть здоровья ближайшим союзным приспешникам при смерти, а также снимут состояния с этих приспешников.",["name"]="Марш смерти"}},
["SupportDecayingHexPlayer"]={["Decaying Hex"]={["enDescription"]="Supports Curse skills. Supported skill Trigger Profane Decay on each target they curse to inflict a damaging Debuff.",["description"]="Усиливает умения проклятий. Усиленные умения вызывают срабатывание Нечестивого разложения на каждой проклятой ими цели, накладывая наносящий урон отрицательный эффект.",["name"]="Разлагающая порча"}},
["SupportDeepCutsPlayer"]={["Deep Cuts I"]={["enDescription"]="Supports any skill that Hits enemies, causing it to deal less damage but inflict more potent Bleeding.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения наносят меньше урона, но накладывают более сильное кровотечение.",["name"]="Глубокие порезы I"}},
["SupportDeepCutsPlayerTwo"]={["Deep Cuts II"]={["enDescription"]="Supports any skill that Hits enemies, causing it to deal less damage but inflict more potent Bleeding.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения наносят меньше урона, но накладывают более сильное кровотечение.",["name"]="Глубокие порезы II"}},
["SupportDefyPlayer"]={["Defy I"]={["enDescription"]="Supports Attack Skills you use yourself. Hit Damage from Supported Skills is Lucky if you are Surrounded.",["description"]="Усиливает умения атак, которые вы используете самостоятельно. Урон от ударов от усиленных умений удачлив, если вы окружены.",["name"]="Неповиновение I"}},
["SupportDefyPlayerTwo"]={["Defy II"]={["enDescription"]="Supports Attack Skills you use yourself. Hit Damage from Supported Skills is Lucky and Insufficient Mana doesn't prevent Supported Skills from being used if you are Surrounded.",["description"]="Усиливает умения атак, которые вы используете самостоятельно. Урон от ударов от усиленных умений удачлив, а нехватка маны не мешает их использовать, если вы окружены.",["name"]="Неповиновение II"}},
["SupportDelayedGratificationPlayer"]={["Delayed Gratification"]={["enDescription"]="Supports Skills which require some Condition to be met for use. Supported Skills can be used an additional time after their Condition has been met, but meeting that Condition is harder.",["description"]="Усиливает умения, требующие соблюдения некоторого условия для использования. Усиленные умения можно использовать ещё один раз при выполнении требуемого условия, но выполнить это условие становится сложнее.",["name"]="Отложенная награда"}},
["SupportDelayedReactionPlayer"]={["Delayed Reaction"]={["enDescription"]="Supports Skills which create Hazards, causing those Hazards to only be able to trigger immediately after creation or at the end of their duration. Created Hazards have significantly lowered duration, and deal more damage.",["description"]="Усиливает умения, создающие помехи, заставляя эти помехи срабатывать только либо сразу же после создания, либо в конце времени действия. Создаваемые помехи имеют существенно сниженную длительность и наносят больше урона.",["name"]="Задержка срабатывания"}},
["SupportDeliberationPlayer"]={["Deliberation"]={["enDescription"]="Supports skills that can be used while moving, causing you to move slower while using them, but granting more damage in exchange.",["description"]="Усиливает умения, которые можно использовать во время передвижения. При их использовании вы передвигаетесь медленнее, но взамен наносите больше урона.",["name"]="Целеустремлённость"}},
["SupportDerangePlayer"]={["Derange"]={["enDescription"]="Supports Skills which you use yourself which can deal damage. Supported Skills gain an Energy Shield cost equal to your Intelligence, while also dealing more non-Ailment Damage over time based off of your Intelligence. Cannot support Channelling Skills.",["description"]="Усиливает самостоятельно используемые вами умения, которые могут наносить урон. Усиленные умения расходуют энергетический щит в размере, равном вашему интеллекту, нанося при этом больше постепенного урона не от состояний в зависимости от вашего интеллекта. Не может усиливать поддерживаемые умения.",["name"]="Разлад"}},
["SupportDesperationPlayer"]={["Desperation"]={["enDescription"]="Supports Melee Attack Skills you use yourself. Insufficient Mana doesn't prevent Supported Skills from being used while Surrounded.",["description"]="Усиливает умения атак ближнего боя, которые вы используете самостоятельно. Усиленные умения можно использовать даже при нехватке маны, если вы окружены.",["name"]="Безысходность"}},
["SupportDevastatePlayer"]={["Devastate"]={["enDescription"]="Supports any skill that Hits enemies, causing them to apply Broken Armour to enemies when causing a Heavy Stun to enemies.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения разрушают броню врагов при наложении сильного оглушения.",["name"]="Разгром"}},
["SupportDiallasDesirePlayer"]={["Dialla's Desire"]={["enDescription"]="Supports any Skill which has levels, increasing the level and Quality, while reducing the cost and Reservation.",["description"]="Усиливает любое умение с уровнем, повышая уровень и качество, при этом сокращая расход и удержание.",["name"]="Желание Диаллы"}},
["SupportDirestrikePlayer"]={["Direstrike I"]={["enDescription"]="Supports Persistent Buff Skills, causing you to deal increased Attack Damage while on Low Life while the Supported Skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами. Пока усиленное умение активно, вы наносите увеличенный урон от атак при малом количестве здоровья.",["name"]="Отчаянный удар I"}},
["SupportDirestrikePlayerTwo"]={["Direstrike II"]={["enDescription"]="Supports Persistent Buff Skills, causing you to deal increased Attack Damage while on Low Life while the Supported Skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами. Пока усиленное умение активно, вы наносите увеличенный урон от атак при малом количестве здоровья.",["name"]="Отчаянный удар II"}},
["SupportDoedresUndoingPlayer"]={["Doedre's Undoing"]={["enDescription"]="Supports Curse Skills. Supported Skills create an area which Curses Enemies within it, and spawns Witchtoads in that area. Witchtoads leap at enemies that get close, and seek out Cursed enemies with higher aggression. Dark Consequences will be Triggered when they hit enemies with their leap, violently exploding the Witchtoad.",["description"]="Усиливает умения проклятий. Усиленные умения создают область, проклинающую врагов в них, и порождают ведьминых жаб в этой области. Ведьмины жабы прыгают на приблизившихся врагов и более агрессивно выискивают проклятых врагов. После прыжка, попавшего во врага, срабатывают Тёмные последствия, взрывая жабу.",["name"]="Пагуба Доэдре"}},
["SupportDoubleBarrelPlayer"]={["Double Barrel I"]={["enDescription"]="Supports Crossbow Ammunition Skills, causing them to load an extra bolt at the cost of reload speed.",["description"]="Усиливает умения боезапаса самострелов. Усиленные умения заряжают дополнительный болт ценой скорости перезарядки.",["name"]="Два ствола I"}},
["SupportDoubleBarrelPlayerThree"]={["Double Barrel III"]={["enDescription"]="Supports Crossbow Ammunition Skills, causing them to load an extra bolt at the cost of reload speed. Supported Skills will also automatically reload when they Heavy Stun an enemy.",["description"]="Усиливает умения боезапаса самострелов. Усиленные умения заряжают дополнительный болт ценой скорости перезарядки, а также автоматически перезаряжаются при сильном оглушении ими врага.",["name"]="Два ствола III"}},
["SupportDoubleBarrelPlayerTwo"]={["Double Barrel II"]={["enDescription"]="Supports Crossbow Ammunition Skills, causing them to load an extra bolt at the cost of reload speed.",["description"]="Усиливает умения боезапаса самострелов. Усиленные умения заряжают дополнительный болт ценой скорости перезарядки.",["name"]="Два ствола II"}},
["SupportDrainedAilmentPlayer"]={["Drain Ailments"]={["enDescription"]="Supports Spells that deal non-Ailment damage over time, causing them to consume Ailments on enemies it applies damage over time Debuffs to in order to deal substantially more damage over time.",["description"]="Усиливает чары, наносящие постепенный урон не от состояний. Усиленные умения поглощают состояния на врагах, на которых накладывают отрицательные эффекты постепенного урона, нанося при этом значительно больше постепенного урона.",["name"]="Поглощение состояний"}},
["SupportDreamersKnellPlayer"]={["Dreamer's Knell"]={["enDescription"]="DNT-UNUSED Ezomyte Four",["description"]="DNT-UNUSED Ezomyte Four",["name"]="Набат Спящего"}},
["SupportDurabilityPlayer"]={["Durability"]={["enDescription"]="Supports Skills which create objects that are destroyed after being Hit a number of times, allowing for them to last for additional Hits. Does not modify Skills used by Minions.",["description"]="Усиливает умения, создающие объекты, которые уничтожаются после нескольких ударов по ним. Объекты от усиленных умений выдерживают дополнительные удары. Не может усиливать умения, используемые приспешниками.",["name"]="Прочность"}},
["SupportEchoingCryPlayer"]={["Echoing Cry"]={["enDescription"]="Supports Warcries. Supported Skills Echo twice, and their area grows larger each time, but are less effective and require you to have travelled a certain distance before use.",["description"]="Усиливает боевые кличи. Усиленные умения отражаются эхом дважды, каждый раз увеличиваясь в размере, но менее эффективны и требуют от вас пройти определённое расстояние перед использованием.",["name"]="Отдающийся крик"}},
["SupportEfficiencyPlayer"]={["Efficiency I"]={["enDescription"]="Supports any skill, making it cost less to use. Cannot support skills which reserve Spirit.",["description"]="Усиливает любое умение. Усиленные умения затрачивают меньше ресурсов на использование. Не может усиливать умения, удерживающие дух.",["name"]="Эффективность I"}},
["SupportEfficiencyPlayerTwo"]={["Efficiency II"]={["enDescription"]="Supports any skill, making it cost less to use. Cannot support skills which reserve Spirit.",["description"]="Усиливает любое умение. Усиленные умения затрачивают меньше ресурсов на использование. Не может усиливать умения, удерживающие дух.",["name"]="Эффективность II"}},
["SupportEinharsBeastritePlayer"]={["Einhar's Beastrite"]={["enDescription"]="Supports Melee Strike skills, causing them to steal a Modifier from Rare monsters they kill for a lengthy duration, while being unable to damage enemies not on low Life. Does not modify skills used by Minions.",["description"]="Усиливает умения ударов ближнего боя. Усиленные умения похищают свойство убитых ими редких монстров на длительное время, но не могут наносить урон врагам не с малым количеством здоровья. Не может усиливать умения, используемые приспешниками.",["name"]="Ритуал Эйнара"}},
["SupportElectrocutePlayer"]={["Electrocute"]={["enDescription"]="Supports any Skill which can deal Damage. Lightning Damage from Supported Skills can inflict Electrocute, but Supported Skills cannot inflict Shock.",["description"]="Усиливает любое умение, которое может наносить урон. Урон от молнии от усиленных умений может накладывать электризацию, но усиленные умения не могут накладывать шок.",["name"]="Электризация"}},
["SupportElementalArmamentPlayer"]={["Elemental Armament I"]={["enDescription"]="Supports Attacks, causing them to deal more Elemental damage.",["description"]="Усиливает атаки, заставляя их наносить больше урона от стихий.",["name"]="Стихийное оружие I"}},
["SupportElementalArmamentPlayerThree"]={["Elemental Armament III"]={["enDescription"]="Supports Attacks, causing them to deal more Damage for each Elemental Ailment on Enemies they Hit. Supported Skills cannot themselves inflict Elemental Ailments.",["description"]="Усиливает атаки, заставляя их наносить больше урона за каждое стихийное состояние на поражённых ими врагах. Усиленные умения сами не могут накладывать стихийные состояния.",["name"]="Стихийное оружие III"}},
["SupportElementalArmamentPlayerTwo"]={["Elemental Armament II"]={["enDescription"]="Supports Attacks, causing them to deal more Elemental damage.",["description"]="Усиливает атаки, заставляя их наносить больше урона от стихий.",["name"]="Стихийное оружие II"}},
["SupportElementalArmyPlayer"]={["Elemental Army"]={["enDescription"]="Supports skills which create Minions, bolstering the Elemental Resistances of those Minions. Cannot support skills which create undamageable Minions.",["description"]="Усиливает умения, создающие приспешников, повышая сопротивления стихиям этих приспешников. Не может усиливать умения, создающие приспешников, которым нельзя нанести урон.",["name"]="Стихийное войско"}},
["SupportElementalDischargePlayer"]={["Elemental Discharge"]={["enDescription"]="Supports any Spell that Hits enemies, causing it to Consume Elemental Ailments on hit to trigger an Elemental Discharge. Cannot support the skills of Minions or skills which already Consume Elemental Ailments.",["description"]="Усиливает любые чары, наносящие удары по врагам. Усиленные умения поглощают стихийные состояния при нанесении удара и вызывают срабатывание Стихийного разряда. Не может усиливать умения приспешников или умения, уже поглощающие стихийные состояния.",["name"]="Разряд стихий"}},
["SupportElementalFocusPlayer"]={["Elemental Focus"]={["enDescription"]="Supports any skill that Hits enemies, causing it to deal more Elemental Damage but be unable to inflict Elemental Ailments.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения наносят больше урона от стихий, но не могут накладывать стихийные состояния.",["name"]="Концентрация стихий"}},
["SupportEmbitterPlayer"]={["Embitter"]={["enDescription"]="Supports Skills which can Damage Enemies with Hits, causing all sources of Damage Gained to instead be treated as Damage Gained as extra Cold for Supported Skills.",["description"]="Усиливает умения, которые могут наносить урон врагам ударами, заставляя все источники дополнительного урона вместо этого считаться дополнительным уроном от холода для усиленных умений.",["name"]="Охлаждение"}},
["SupportEmpoweredCullPlayer"]={["Murderous Intent"]={["enDescription"]="Supports skills that can Empower skills other than themselves, causing skills they Empower to Cull enemies.",["description"]="Усиливает умения, способные улучшать другие умения, при этом улучшаемые умения добивают врагов.",["name"]="Умышленное убийство"}},
["SupportEmpoweredDamagePlayer"]={["Premeditation"]={["enDescription"]="Supports skills that can Empower skills other than themselves, causing skills they Empower to deal more damage.",["description"]="Усиливает умения, способные улучшать другие умения, при этом улучшаемые умения наносят больше урона.",["name"]="Предумышленность"}},
["SupportEmpoweredSparksPlayer"]={["Empowered Sparks I"]={["enDescription"]="Supports Skills which generate Charges. When generating Power Charge with Supported Skills, Empower some of your Attacks to Trigger Spark Projectiles on use.",["description"]="Усиливает умения, вырабатывающие заряды. При получении заряда энергии от усиленных умений улучшает некоторые ваши атаки так, что они вызывают снаряды Искры при использовании.",["name"]="Заряженные искры I"},["Empowered Sparks II"]={["enDescription"]="Supports Skills which generate Charges. When generating Power Charge with Supported Skills, Empower some of your Attacks to Trigger Spark Projectiles on use.",["description"]="Усиливает умения, вырабатывающие заряды. При получении заряда энергии от усиленных умений улучшает некоторые ваши атаки так, что они вызывают снаряды Искры при использовании.",["name"]="Заряженные искры II"}},
["SupportEncroachingGroundPlayer"]={["Encroaching Ground"]={["enDescription"]="Supports Skills that create Ground Surfaces, causing those Surfaces to grow over time, up to a limit.",["description"]="Усиливает умения, создающие наземные эффекты, заставляя эти эффекты постепенно расти, вплоть до ограничения.",["name"]="Охватывающая земля"}},
["SupportEnduranceChargeOnArmourBreak"]={["Break Endurance"]={["enDescription"]="Supports any skill that Hits enemies, giving it a chance to gain an Endurance Charge when it Fully Breaks an enemy's Armour.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения имеют шанс даровать заряд выносливости при полном разрушении вражеской брони.",["name"]="Разрушительная выносливость"}},
["SupportEnergyBarrierPlayer"]={["Energy Barrier"]={["enDescription"]="Supports any skill that you can use, causing Energy Shield recharge to begin immediately if you are Stunned while using it.",["description"]="Усиливает любое умение, которое вы можете использовать. Если при использовании усиленного умения вы получаете оглушение, перезарядка энергетического щита начинается немедленно.",["name"]="Энергетический барьер"}},
["SupportEnergyCapacitorPlayer"]={["Energy Capacitor"]={["enDescription"]="Supports Invocation Skills which Trigger other Skills. Supported Skills have significantly higher Maximum Energy.",["description"]="Усиливает умения вызова, которые вызывают срабатывание других умений. Усиленные умения приобретают существенно более высокий максимум энергии.",["name"]="Накопитель энергии"}},
["SupportEnergyRetentionPlayer"]={["Energy Retention"]={["enDescription"]="Supports Meta Skills. Supported Skills gain a chance to partially Refund a portion of Energy cost when Triggering or Invoking other Skills.",["description"]="Усиливает мета-умения. Усиленные умения приобретают шанс возвратить часть потраченной энергии при активации или вызове других умений.",["name"]="Сохранение энергии"}},
["SupportEnergyShieldOnShockKillPlayer"]={["Shock Siphon"]={["enDescription"]="Supports any skill that Hits enemies, causing you to recover Energy Shield when it kills a Shocked enemy.",["description"]="Усиливает любое умение, наносящее удары по врагам, восстанавливая ваш энергетический щит при убийстве врага под действием шока.",["name"]="Вбирание шока"}},
["SupportEnragedWarcryPlayer"]={["Enraged Warcry I"]={["enDescription"]="Supports Warcries, causing them to spend Rage to bypass their usual Cooldown.",["description"]="Усиливает боевые кличи. Усиленные кличи тратят свирепость на мгновенную перезарядку.",["name"]="Яростный крик I"}},
["SupportEnragedWarcryPlayerTwo"]={["Enraged Warcry II"]={["enDescription"]="Supports Warcries, causing them to spend Rage to bypass their usual Cooldown.",["description"]="Усиливает боевые кличи. Усиленные кличи тратят свирепость на мгновенную перезарядку.",["name"]="Яростный крик II"}},
["SupportEonyrsThunderPlayer"]={["Eonyr's Thunder"]={["enDescription"]="Supports any Skill which can deal damage. Lightning damage from Supported Skills can inflict Electrocute, but Supported Skills cannot inflict Shock. Enemies slain while Electrocuted by Supported Skills explode, dealing a percentage of their maximum Life as Lightning damage.",["description"]="Усиливает любое умение, которое может наносить урон. Урон от молнии от усиленных умений может накладывать электризацию, но усиленные умения не могут накладывать шок. Враги, убитые, будучи наэлектризованными усиленными умениями, взрываются, нанося часть своего максимума здоровья в виде урона от молнии.",["name"]="Гром Эонира"}},
["SupportEscalatingPoisonPlayer"]={["Escalating Poison"]={["enDescription"]="Supports any skill that Hits enemies, allowing it to inflict an extra Poison on enemies but shortening the duration of those Poisons.",["description"]="Усиливает любое умение, наносящее удары по врагам, позволяя ему накладывать на врагов дополнительное отравление, но сокращая длительность этих отравлений.",["name"]="Нарастающий яд"}},
["SupportEshsProwess"]={["Esh's Prowess"]={["enDescription"]="Supports Lightning Skills that Hit, granting them an additional level and causing them to only roll the minimum or maximum value for Lightning damage. Does not Support Skills which do not have levels.",["description"]="Усиливает умения молнии, наносящие удары, даруя им дополнительный уровень. Усиленные умения наносят только минимальный или максимальный урон от молнии. Не усиливает умения, не имеющие уровней.",["screenshot"]="Screenshot_27.png",["pobDescription"]="Supports Lightning skills that Hit targets, granting them an additional level and causing them to only roll the minimum or maximum value for Lightning damage. Does not support skills which do not have levels.",["flavour"]="Безграничное знание превзошло физическую форму.\nЕё умы мельтешили по металлической решётке, когда\nсливающаяся плоть потянулась вместить её.",["name"]="Умение Иш"}},
["SupportEshsRadiancePlayer"]={["Esh's Radiance"]={["enDescription"]="Supports Skills that can cause Damaging Hits, granting extra Chaos damage and causing Chaos damage to Contribute to Shock.",["description"]="Усиливает умения, которые могут наносить урон ударами, даруя дополнительный урон хаосом и позволяя урону хаосом влиять на наложение шока.",["name"]="Сияние Иш"}},
["SupportEssenceHarvestPlayer"]={["Essence Harvest"]={["enDescription"]="Supports Skills which create Reviving Persistent Minions. When those Minions die, you Recoup a percentage of your maximum Mana.",["description"]="Усиливает умения, создающие возрождающихся постоянных приспешников. Когда эти приспешники умирают, вы восполняете часть маны.",["name"]="Жатва сущности"}},
["SupportEternalMarkPlayer"]={["Eternal Mark"]={["enDescription"]="Supports Mark Skills, causing them to not be Consumed the first time they are Activated.",["description"]="Усиливает умения меток. Метки от усиленных умений не поглощаются при первой активации.",["name"]="Вечная метка"}},
["SupportExcisePlayer"]={["Excise"]={["enDescription"]="Supports any damaging Skill that you use yourself, granting it significantly higher chance to Critically Hit, but causing it to gain a long cooldown. Cannot support Skills which already have a cooldown.",["description"]="Усиливает любое наносящее урон умение, которое вы используете самостоятельно. Усиленное умение получает существенно более высокий шанс критического попадания, но приобретает длительную перезарядку. Не может усиливать умения, уже обладающие перезарядкой.",["name"]="Рассечение"}},
["SupportExcoriatePlayer"]={["Excoriate"]={["enDescription"]="Supports Melee Attack Skills. Supported Skills deal more Melee Damage for each Elemental Ailment on Enemies they hit, but cannot themselves inflict Elemental Ailments.",["description"]="Усиливает умения атак ближнего боя. Усиленные умения наносят больше урона в ближнем бою за каждое стихийное состояние на поражённых врагах, но сами не могут накладывать стихийные состояния.",["name"]="Содранная кожа"}},
["SupportExecratePlayer"]={["Execrate"]={["enDescription"]="Supports any damaging Skill that you use yourself, granting it significantly higher chance to inflict Ailments on hit, but causing it to gain a long cooldown. Cannot support Skills which already have a cooldown.",["description"]="Усиливает любое наносящее урон умение, которое вы используете самостоятельно. Усиленное умение получает существенно более высокий шанс наложения состояний при попадании, но приобретает длительную перезарядку. Не может усиливать умения, уже обладающие перезарядкой.",["name"]="Расправа"}},
["SupportExecutePlayer"]={["Execute I"]={["enDescription"]="Supports any skill that Hits enemies, causing it to deal more damage against enemies on Low Life.",["description"]="Усиливает любое умение, наносящее удары Усиленные умения наносят больше урона по врагам с малым количеством здоровья.",["name"]="Казнь I"}},
["SupportExecutePlayerThree"]={["Execute III"]={["enDescription"]="Supports any skill that Hits enemies, causing it to deal more damage against enemies on Low Life, as well as dealing more damage while you are on Low Life.",["description"]="Усиливает любое умение, наносящее удары Усиленные умения наносят больше урона по врагам с малым количеством здоровья и больше урона, когда у вас малое количество здоровья.",["name"]="Казнь III"}},
["SupportExecutePlayerTwo"]={["Execute II"]={["enDescription"]="Supports any skill that Hits enemies, causing it to deal more damage against enemies on Low Life.",["description"]="Усиливает любое умение, наносящее удары Усиленные умения наносят больше урона по врагам с малым количеством здоровья.",["name"]="Казнь II"}},
["SupportExpandPlayer"]={["Expand"]={["enDescription"]="Supports Spells you cast yourself, Sealing them over time. The Seals are broken when cast, increasing area of effect. Cannot support Channelling Skills or Skills with a Cooldown or which already gain Seals.",["description"]="Усиливает чары, которые вы сотворяете самостоятельно, постепенно запечатывая их. При сотворении печати разбиваются, увеличивая область действия. Не может усиливать поддерживаемые умения, умения с перезарядкой и умения, уже накапливающие печати.",["name"]="Расширение"}},
["SupportExpansePlayer"]={["Expanse"]={["enDescription"]="Supports any Skill that you use yourself, granting it significantly higher Area of Effect but causing it to gain a long cooldown. Cannot support Skills which already have a cooldown.",["description"]="Усиливает любое умение, которое вы используете самостоятельно. Усиленное умение приобретает существенно большую область действия, но также длительную перезарядку. Не может усиливать умения, уже обладающие перезарядкой.",["name"]="Широкий охват"}},
["SupportExploitWeaknessPlayer"]={["Exploit Weakness"]={["enDescription"]="Supports any skill that Hits enemies, causing them to deal more Damage against enemies with Broken Armour but preventing them from Breaking Armour themselves. Cannot support skills that Consume Broken Armour.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения наносят больше урона по врагам с разрушенной бронёй, но сами не могут разрушать броню. Не может усиливать умения, поглощающие разрушенную броню.",["name"]="Брешь"}},
["SupportExplosiveGrowthPlayer"]={["Accelerated Growth"]={["enDescription"]="Supports Plant Skills, causing them to Trigger an explosion after they have been Overgrown.",["description"]="Усиливает умения растений. Усиленные умения вызывают срабатывание взрыва после разрастания.",["name"]="Ускоренный рост"}},
["SupportExplosiveGrowthPlayerTwo"]={["Accelerated Growth II"]={["enDescription"]="Supports Plant Skills, causing them to Trigger an explosion after they have been Overgrown, Blinding enemies Hit.",["description"]="Усиливает умения растений. После разрастания усиленные умения вызывают срабатывание взрыва, ослепляющего поражённых врагов.",["name"]="Ускоренный рост II"}},
["SupportExposingCryPlayer"]={["Exposing Cry"]={["enDescription"]="Supports Warcries. Supported Skills apply Exposure on Hitting enemies.",["description"]="Усиливает боевые кличи. Усиленные умения накладывают восприимчивость на поражённых врагов.",["name"]="Клич восприимчивости"}},
["SupportExtractionPlayer"]={["Extraction"]={["enDescription"]="Supports Spell Skills which cause Damaging Hits. Using supported Spells will cause you to Sacrifice a portion of your Life on use, gaining extra Chaos Damage in exchange. Does not support Persistent Skills, Minion Skills, or Triggered Skills.",["description"]="Усиливает умения чар, наносящие урон ударами. Использование усиленных чар заставляет вас жертвовать частью здоровья, взамен приобретая урон хаосом. Не может усиливать постоянные умения, умения приспешников или срабатывающие умения.",["name"]="Извлечение"}},
["SupportFanTheFlamesPlayer"]={["Fan The Flames"]={["enDescription"]="Supports Wind Skills which Hit enemies. Hits with Supported Skills against Ignited enemies Trigger a fiery explosion, dealing damage to that enemy and enemies in a cone behind them.",["description"]="Усиливает умения ветра, наносящие удары по врагам. Удары усиленными умениями по подожжённому врагу вызывают срабатывание огненного взрыва, наносящего урон этому врагу и врагам в конусе позади него.",["name"]="Раздувшееся пламя"}},
["SupportFanTheFlamesPlayerTwo"]={["Fan The Flames II"]={["enDescription"]="Supports Wind Skills which Hit enemies. Hits with Supported Skills against Ignited enemies Trigger a fiery explosion, dealing damage to that enemy and enemies in a cone behind them. The explosion Spreads the initial enemy's Ignite to other enemies Hit.",["description"]="Усиливает умения ветра, наносящие удары по врагам. Удары усиленными умениями по подожжённому врагу вызывают срабатывание огненного взрыва, наносящего урон этому врагу и врагам в конусе позади него. Взрыв распространяет поджог от изначального врага на других поражённых противников.",["name"]="Раздувшееся пламя II"}},
["SupportFarCombatPlayer"]={["Longshot I"]={["enDescription"]="Supports Attacks, causing them to deal more damage from farther away.",["description"]="Усиливает атаки. Усиленные умения наносят больше урона с более дальнего расстояния.",["name"]="Дальний выстрел I"}},
["SupportFarCombatPlayerTwo"]={["Longshot II"]={["enDescription"]="Supports Attacks, causing them to deal more damage from farther away.",["description"]="Усиливает атаки. Усиленные умения наносят больше урона с более дальнего расстояния.",["name"]="Дальний выстрел II"}},
["SupportFeedingFrenzyPlayer"]={["Feeding Frenzy I"]={["enDescription"]="Supports skills which create Minions, making them deal and take more damage. Cannot support skills which create undamageable Minions.",["description"]="Усиливает умения, создающие приспешников. Приспешники наносят и получают больше урона. Не может усиливать умения, создающие приспешников, которым нельзя нанести урон.",["name"]="Голодное остервенение I"}},
["SupportFerocityPlayer"]={["Ferocity"]={["enDescription"]="Supports Skills that you use yourself. Supported Skills will consume a Frenzy Charge on use if possible, and will gain significant Skill Speed if they do, but cannot generate Frenzy Charges. Cannot Support Skills which consume Frenzy Charges.",["description"]="Усиливает умения, которые вы используете самостоятельно. Усиленные умения поглотят заряд ярости при использовании, если возможно, и в этом случае приобретут существенно повышенную [SkillSpeed|скорость умений. Усиленные умения не могут вырабатывать заряды ярости. Не может усиливать умения, поглощающие заряды ярости.",["name"]="Дикость"}},
["SupportFieryDeathPlayer"]={["Fiery Death"]={["enDescription"]="Supports any skill that Hits enemies, causing enemies it Ignites to have a chance to explode on death.",["description"]="Усиливает любое умение, наносящее удары по врагам. Подожжённые усиленным умением враги имеют шанс взорваться при смерти.",["name"]="Пламенная смерть"}},
["SupportFireExposurePlayer"]={["Fire Exposure"]={["enDescription"]="Supports any skill that Hits enemies, causing it to inflict Exposure when Igniting.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения накладывают восприимчивость при поджоге.",["name"]="Восприимчивость к огню"}},
["SupportFireMasteryPlayer"]={["Fire Mastery"]={["enDescription"]="Supports Fire skills, granting them an additional level. Does not support skills which do not have levels.",["description"]="Усиливает умения огня, даруя им дополнительный уровень. Не усиливает умения, не имеющие уровней.",["name"]="Мастерство огня"}},
["SupportFirePenetrationPlayer"]={["Fire Penetration I"]={["enDescription"]="Supports any skill that Hits enemies, making those Hits Penetrate enemy Fire resistance.",["description"]="Усиливает любое умение, наносящее удары по врагам. Удары этим умением пробивают вражеское сопротивление огню.",["name"]="Пронизывающий жар I"}},
["SupportFirePenetrationPlayerTwo"]={["Fire Penetration II"]={["enDescription"]="Supports any skill that Hits enemies, making those Hits ignore enemy Fire resistance.",["description"]="Усиливает любое умение, наносящее удары по врагам. Удары этим умением игнорируют вражеское сопротивление огню.",["name"]="Пронизывающий жар II"}},
["SupportFirstBloodPlayer"]={["First Blood"]={["enDescription"]="Supports Attacks. Supported Skills are far more likely to inflict Bleeding on Hitting full Life Enemies.",["description"]="Усиливает атаки. Усиленные умения с гораздо большей вероятностью накладывают кровотечение при нанесении удара по врагам с полным здоровьем.",["name"]="Первая кровь"}},
["SupportFistOfKalguurPlayer"]={["Fist Of Kalguur"]={["enDescription"]="Supports Slams you use yourself, allowing them to spend large amounts of Runic Ward to become Runically Boosted. Runically Boosted Slams are Empowered with extra Physical damage and create a rune the first time they hit an enemy. The rune erupts in an Aftershock after a duration. Cannot support Channelling Skills.",["description"]="Усиливает мощные удары, которые вы используете самостоятельно, позволяя им тратить большие объёмы рунического барьера ради получения рунического усиления. Рунически усиленные мощные удары улучшаются дополнительным физическим уроном и создают руну при первом попадании по врагу. Через некоторое время руна извергается остаточной волной. Не может усиливать поддерживаемые умения.",["name"]="Кулак Калгуура"}},
["SupportFlamePillarPlayer"]={["Flame Pillar"]={["enDescription"]="Supports any Skill you use yourself which can cause Damaging Hits. Supported Skills Consume Ignite on Hit to create pillars of flame, but cannot themselves inflict Ignite. Cannot Support Skills which already Consume Ignite, and does not modify the Skills of Minions.",["description"]="Усиливает самостоятельно используемые вами умения, которые могут наносить урон ударами. Усиленные умения поглощают поджог при нанесении удара и создают столпы огня, но сами не могут накладывать поджог. Не может усиливать умения, уже поглощающие поджог, и умения приспешников.",["name"]="Столп огня"}},
["SupportFlamepiercePlayer"]={["Flamepierce"]={["enDescription"]="Supports Skills which can fire Projectiles. Initial Projectile created by Supported Skills will always Pierce Ignited Enemies, but Supported Skills cannot inflict Ignite themselves.",["description"]="Усиливает умения, которые могут выпускать снаряды. Изначальный снаряд, выпущенный усиленными умениями, всегда будет пронзать подожжённых врагов, но усиленные умения не могут сами накладывать поджог.",["name"]="Пронзание пламени"}},
["SupportFleetingRemnantsPlayer"]={["Harmonic Remnants I"]={["enDescription"]="Supports Skills which create Remnants, allowing those Remnants to be collected from further away.",["description"]="Усиливает умения, создающие сгустки, позволяя собирать созданные сгустки с большего расстояния.",["name"]="Бренные останки I"}},
["SupportFleetingRemnantsPlayerTwo"]={["Harmonic Remnants II"]={["enDescription"]="Supports Skills which create Remnants, allowing those Remnants to be collected from further away, with a chance to create an additional Remnant.",["description"]="Усиливает умения, создающие сгустки, позволяя собирать созданные сгустки с большего расстояния, с шансом создать дополнительный сгусток.",["name"]="Бренные останки II"}},
["SupportFlowPlayer"]={["Flow"]={["enDescription"]="Supports Skills which require Combo to use. Supported Skills lose their Combo stacks after a longer delay spent not gaining any Combo.",["description"]="Усиливает умения, для использования которых требуется Комбо. Усиленные умения теряют накопленное Комбо после более долгой задержки, если перестать накапливать Комбо.",["name"]="Поток"}},
["SupportFlukePlayer"]={["Fluke"]={["enDescription"]="Supports Skills which Trigger other Skills. Skills Triggered by Supported Skills have their Damage randomly raised or lowered when Triggered, as well as recovering a random amount of their cost when Triggered.",["description"]="Усиливает умения, вызывающие срабатывание других умений. Урон умений, активированных усиленными умениями, случайным образом повышается или снижается при срабатывании, и они восстанавливают случайную часть от своего расхода.",["name"]="Разброс"}},
["SupportFlukePlayerTwo"]={["Ixchel's Torment"]={["enDescription"]="Supports Skills which Trigger other Skills. Skills Triggered by Supported Skills have their Damage, Area of Effect, and Projectile Speed randomly raised or lowered when Triggered, as well as recovering a random amount of their cost when Triggered.",["description"]="Усиливает умения, вызывающие срабатывание других умений. Урон умений, активированных усиленными умениями, а также их область действия и скорость снарядов, случайным образом повышаются или снижаются при срабатывании, и они восстанавливают случайную часть от своего расхода.",["name"]="Мука Ишчейла"}},
["SupportFocusedCursePlayer"]={["Focused Curse"]={["enDescription"]="Supports Curse skills, causing them to Curse enemies more quickly after being cast.",["description"]="Усиливает умения проклятий. После сотворения усиленные умения проклинают врагов быстрее.",["name"]="Наведённое проклятие"}},
["SupportForkPlayer"]={["Fork"]={["enDescription"]="Supports Projectile skills, making their Projectiles Fork.",["description"]="Усиливает умения снарядов. Снаряды усиленных умений разветвляются.",["name"]="Разветвление"}},
["SupportFreezePlayer"]={["Freeze"]={["enDescription"]="Supports any skill that Hits enemies, making it more effective at Freezing enemies.",["description"]="Усиливает любое умение, наносящее удары по врагам, и повышает его эффективность в замораживании врагов.",["name"]="Заморозка"}},
["SupportFreezeforkPlayer"]={["Freezefork"]={["enDescription"]="Supports Skills which can fire Projectiles. Projectiles from Supported Skills always Fork when the initial Projectile Hits Frozen Enemies, but Supported Skills cannot build up Freeze themselves.",["description"]="Усиливает умения, которые могут выпускать снаряды. Снаряды от усиленных умений всегда разветвляются, когда изначальный снаряд наносит удар по замороженным врагам, но усиленные умения не могут сами накапливать заморозку.",["name"]="Морозное разветвление"}},
["SupportFrenziedRipostePlayer"]={["Frenzied Riposte"]={["enDescription"]="Supports Attacks you use or Trigger yourself, causing them to Consume the Parried Debuff on Hit to grant you a Frenzy Charge. Cannot support Skills which already Consume the Parried Debuff.",["description"]="Усиливает атаки, которые вы используете самостоятельно или сами вызываете их срабатывание. Усиленные умения поглощают отрицательный эффект парирования при нанесении удара, тем самым даруя вам заряд ярости. Не может усиливать умения, уже поглощающие отрицательный эффект парирования.",["name"]="Яростное парирование"}},
["SupportFreshClipPlayer"]={["Fresh Clip I"]={["enDescription"]="Supports Crossbow Skills, granting them more damage for each bolt reloaded by that Skill in the last 6 seconds.",["description"]="Усиливает самострелов. Усиленные умения наносят больше урона за каждый болт, перезаряженный этим умением за последние 6 секунд.",["name"]="Сменный магазин I"}},
["SupportFreshClipPlayerTwo"]={["Fresh Clip II"]={["enDescription"]="Supports Crossbow Skills, granting them more damage for each bolt reloaded by that Skill in the last 8 seconds.",["description"]="Усиливает самострелов. Усиленные умения наносят больше урона за каждый болт, перезаряженный этим умением за последние 8 секунд.",["name"]="Сменный магазин II"}},
["SupportFromTheGravePlayer"]={["DNT From the Grave"]={["enDescription"]="DNT From the Grave Support",["description"]="DNT-UNUSED From the Grave Support",["name"]="DNT From the Grave"}},
["SupportFrostfirePlayer"]={["Frostfire"]={["enDescription"]="Supports any skill that Hits enemies, causing it to Consume Freeze on Igniting a Frozen enemy to boost the effect of the Ignite. Cannot support skills that Consume Freeze or Ignite.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения поглощают заморозку при поджоге замороженного врага для усиления эффекта поджога. Не может усиливать умения, поглощающие заморозку или поджог.",["name"]="Из холода в жар"}},
["SupportFrozenSpitePlayer"]={["Frozen Spite"]={["enDescription"]="Supports Skills that Hit enemies, causing them to create Ice Fragments on killing Frozen Enemies. Cannot Support Totem Skills and does not modify Skills used by Minions.",["description"]="Усиливает умения, наносящие удары по врагам, заставляя их создавать куски льда при убийстве замороженных врагов. Не может усиливать умения тотемов и умения, используемые приспешниками.",["screenshot"]="Screenshot_26.png",["pobDescription"]="Supports Attack Skills, causing them to create Ice Fragments on killing Frozen Enemies. Cannot Support Totem Skills and does not modify Skills used by Minions.",["comparisonNote"]="В PoB 0.23.1 этот камень подходит только умениям атак.",["name"]="Замёрзший гнев"}},
["SupportFrozenVortexPlayer"]={["Frozen Vortex"]={["enDescription"]="Supports any skill that Hits enemies, causing it to create an icy vortex on Shattering an enemy.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения создают ледяную пургу при разбивании врага.",["name"]="Морозная пурга"}},
["SupportFusilladePlayer"]={["Fusillade"]={["enDescription"]="DNT-UNUSED Supports Bow Attacks you use yourself. Supported Attacks fire multiple projectiles into the air,",["description"]="DNT-UNUSED Supports Bow Attacks you use yourself. Supported Attacks fire multiple projectiles into the air,",["name"]="Обстрел"}},
["SupportGambleshotPlayer"]={["Gambleshot"]={["enDescription"]="Supports Skills which fire Projectiles that are not ground targeted. Projectiles from Supported Skills randomly Fork, Chain or Pierce.",["description"]="Усиливает умения, выпускающие снаряды, которые не нацелены в землю. Снаряды от усиленных умений случайным образом разветвляются, бьют по цепи или пронзают.",["name"]="Выстрел наудачу"}},
["SupportGarukhansResolvePlayer"]={["Garukhan's Resolve"]={["enDescription"]="Supports Attack Skills you use yourself which do not already have some Condition for use. Supported Skills have a maximum Critical Hit chance, but will Bifurcate Critical Hit Chance.",["description"]="Усиливает умения атак, которые вы используете самостоятельно, не обладающие какими-либо условиями использования. Усиленные умения обладают максимальным шансом критического попадания, но их шанс критических попаданий разветвляется.",["name"]="Решимость Гарухан"}},
["SupportGlacierPlayer"]={["Glacier"]={["enDescription"]="Supports any Skill which creates Ice Crystals, causing them to be created with higher Life.",["description"]="Усиливает любое умение, создающее ледяные кристаллы. Созданные кристаллы становятся более прочными.",["name"]="Ледник"}},
["SupportGorgePlayer"]={["Gorge"]={["enDescription"]="Supports skills that consume Corpses. Consuming Corpses with supported skills grants Flask charges.",["description"]="Усиливает умения, поглощающие трупы. Поглощение трупов усиленными умениями дарует заряды флакона.",["name"]="Пресыщение"}},
["SupportGreatwoodPlayerTwo"]={["Greatwood II"]={["enDescription"]="DNT Supports Skills which create Totems, limiting their active Totem count to one but granting significant benefits for supported Totems based how many allied Totems are near them. Does not support Skills used by Minions.",["description"]="Усиливает умения, создающие тотемы, ограничивая максимальное число активных тотемов до одного, но даруя значительные прибавки усиленным тотемам в зависимости от того, каким был бы лимит тотемов без данного ограничения. Не может усиливать умения, используемые приспешниками.",["name"]="Могучее дерево II"}},
["SupportGreybeardsFuse"]={["DNT Greybeard's Fuse"]={["enDescription"]="DNT Description",["description"]="DNT Description",["name"]="DNT Greybeard's Fuse"}},
["SupportGuatelitzisAblationPlayer"]={["Guatelitzi's Ablation"]={["enDescription"]="Supports Offering Skills. Supported Skills Sacrifice a portion of your life on use. While Offering spikes from Supported Skills persist, you are periodically granted a Power Charge. When spikes from Supported Skills die, Regenerate a percentage of your maximum Life and Mana per second based on the duration the Offering persisted.",["description"]="Усиливает умения подношений. Усиленные умения жертвуют частью вашего здоровья при использовании. Пока шипы подношений от усиленных умений существуют, вы периодически получаете заряд энергии. Когда шипы от усиленных умений умирают, регенерирует часть от вашего максимума здоровья и маны в секунду в зависимости от времени, в течение которого просуществовало подношение.",["name"]="Отсечение Гвателитзи"}},
["SupportHaemocrystalsPlayer"]={["Haemocrystals"]={["enDescription"]="Supports Attack Skills you use yourself which can cause Damaging Hits. Supported Skills Consume Bleeding on Hit to create explosive blood-filled crystals, but cannot themselves inflict Bleeding. Cannot Support Skills which already Consume Bleeding.",["description"]="Усиливает самостоятельно используемые вами умения атак, которые могут наносить урон ударами. Усиленные умения поглощают кровотечение при нанесении удара и создают взрывчатые заполненные кровью кристаллы, но сами не могут накладывать кровотечение. Не может усиливать умения, уже поглощающие кровотечение.",["name"]="Гемокристаллы"}},
["SupportHardyTotemsPlayer"]={["Hardy Totems I"]={["enDescription"]="Supports Skills which create Totems, causing those Totems to have more Life.",["description"]="Усиливает умения, создающие тотемы, даруя этим тотемам больше здоровья.",["name"]="Прочные тотемы I"}},
["SupportHardyTotemsPlayerThree"]={["Tawhoa's Tending"]={["enDescription"]="Supports Skills which create Totems, causing those Totems to have more Life. Totems created by Supported Skills explode on death, dealing Physical damage based on their Life.",["description"]="Усиливает умения, создающие тотемы, даруя этим тотемам больше здоровья. Тотемы, созданные усиленными умениями, при смерти взрываются, нанося физический урон на основе их здоровья.",["name"]="Забота Тахоа"}},
["SupportHardyTotemsPlayerTwo"]={["Hardy Totems II"]={["enDescription"]="Supports Skills which create Totems, causing those Totems to have more Life.",["description"]="Усиливает умения, создающие тотемы, даруя этим тотемам больше здоровья.",["name"]="Прочные тотемы II"}},
["SupportHayoxisBindingPlayer"]={["Hayoxi's Fulmination"]={["enDescription"]="Supports Curse Skills, giving them a short cooldown but causing them to create areas which Curse enemies so long as they are within them. Cursed areas from Supported Skills gather power before erupting in a column of annihilating light after a moderate delay.",["description"]="Усиливает умения проклятий. Усиленные умения приобретают короткую перезарядку, но создают области, которые проклинают врагов, покуда те остаются в них. Проклятые области от усиленных умений накапливают энергию, а затем извергают столп уничтожающего света после средней задержки.",["name"]="Взрыв Хайоши"}},
["SupportHealingRunesPlayer"]={["Healing Runes"]={["enDescription"]="Supports Persistent Buff Skills, causing you to lose Runic Ward and heal nearby allies based on the Ward lost. Healing done is split between allies who are not on full Life.",["description"]="Усиливает умения с постоянными положительными эффектами, заставляя вас терять рунический барьер и исцелять союзников поблизости на основе потерянного барьера. Исцеление разделяется между союзниками, у которых неполное здоровье.",["name"]="Исцеляющие руны"}},
["SupportHeavyStunEndurancePlayerOne"]={["Enduring Impact I"]={["enDescription"]="Supports any skill that Hits enemies, giving it a chance to gain an Endurance Charge when causing a Heavy Stun.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения имеют шанс даровать заряд выносливости при вызове сильного оглушения.",["name"]="Выносливый удар I"}},
["SupportHeavyStunEndurancePlayerTwo"]={["Enduring Impact II"]={["enDescription"]="Supports any skill that Hits enemies, giving it a chance to gain an Endurance Charge when causing a Heavy Stun.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения имеют шанс даровать заряд выносливости при вызове сильного оглушения.",["name"]="Выносливый удар II"}},
["SupportHeftPlayer"]={["Heft"]={["enDescription"]="Supports Skills which deal Damage, increasing the maximum Physical Damage of their Hits.",["description"]="Усиливает умения, наносящие урон, увеличивая максимальный физический урон от их ударов.",["name"]="Тяжесть"}},
["SupportHeightenedAccuracyPlayer"]={["Heightened Accuracy I"]={["enDescription"]="Supports Attacks, causing them to gain Accuracy.",["description"]="Усиливает атаки, повышая их меткость.",["name"]="Повышенная меткость I"}},
["SupportHeightenedAccuracyPlayerTwo"]={["Heightened Accuracy II"]={["enDescription"]="Supports Attacks, causing them to gain Accuracy, and never miss against Enemies on full Life.",["description"]="Усиливает атаки, повышая их меткость. Усиленные умения не промахиваются по врагам с полным здоровьем.",["name"]="Повышенная меткость II"}},
["SupportHeightenedChargesPlayer"]={["Heightened Charges"]={["enDescription"]="Supports any Skill that Consumes Charges, granting a chance for benefits of that Consumption to be doubled.",["description"]="Усиливает любое умение, поглощающее заряды, даруя шанс удвоить положительное действие такого поглощения.",["name"]="Возвышенные заряды"}},
["SupportHelbrymsHidePlayer"]={["Helbrym's Hide"]={["enDescription"]="Supports Shapeshifting Skills, causing them to grant Helbrym's Composure for a brief duration when they cause you to Shapeshift. Shapeshifting into a different form before the Buff expires causes it to be removed without effect.",["description"]="Усиливает умения превращения. Усиленные умения на короткое время даруют Самообладание Хельбрима, когда вызывают ваше превращение. Превращение в другую форму до истечения времени действия положительного эффекта снимает эффект с вас.",["name"]="Шкура Хельбрима"}},
["SupportHerDeclarationPlayer"]={["Her Declaration"]={["enDescription"]="Supports Persistent Buff Skills, causing enemies that enter your Presence to become Intimidated while the Skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами, устрашая врагов в вашем присутствии, пока умение активно.",["name"]="Её заявление"}},
["SupportHerbalismPlayer"]={["Herbalism I"]={["enDescription"]="Supports Persistent Buff Skills, causing you to gain increased Life recovery from Flasks while the Skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами. Пока активно, усиленное умение даёт вам увеличенное восстановление здоровья от флаконов.",["name"]="Травничество I"}},
["SupportHerbalismPlayerTwo"]={["Herbalism II"]={["enDescription"]="Supports Persistent Buff Skills, causing you to gain increased Life recovery from Flasks while the Skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами. Пока активно, усиленное умение даёт вам увеличенное восстановление здоровья от флаконов.",["name"]="Травничество II"}},
["SupportHexBloomPlayer"]={["Hex Bloom"]={["enDescription"]="Supports Curses, spreading their effects when a Cursed enemy dies.",["description"]="Усиливает проклятия, распространяя их эффекты при смерти проклятого врага.",["name"]="Расцвет порчи"}},
["SupportHinderPlayer"]={["Hinder"]={["enDescription"]="Supports Spells that deal non-Ailment Chaos damage over time, causing damage over time they inflict to also Hinder enemies. Does not Support Skills used by Minions.",["description"]="Усиливает чары, наносящие постепенный урон хаосом не от состояний. Накладываемый усиленными умениями постепенный урон также сковывает врагов. Не может усиливать умения, используемые приспешниками.",["name"]="Скованность"}},
["SupportHitAndRunPlayer"]={["Hit and Run"]={["enDescription"]="Supports Attack Skills you use yourself which do not already have some Condition for use. Supported Skills can only be used after you have moved a certain distance, but have massively increased Skill Speed. Cannot support Skills which have a cooldown.",["description"]="Усиливает умения атак, которые вы используете самостоятельно, не обладающие какими-либо условиями использования. Усиленные умения можно использовать только после передвижения на определённое расстояние, но их скорость резко увеличивается. Не может усиливать умения, обладающие перезарядкой.",["name"]="Удар с разбега"}},
["SupportHoarfrostPlayer"]={["Hoarfrost"]={["enDescription"]="Supports Skills which create Ice Crystals. Supported Skills create chilling areas which deal Cold Damage over time instead of creating Ice Crystals.",["description"]="Усиливает умения, создающие ледяные кристаллы. Усиленные умения вместо ледяных кристаллов создают охлаждающие области, которые наносят постепенный урон от холода.",["name"]="Изморозь"}},
["SupportHobblePlayer"]={["Hobble"]={["enDescription"]="Supports Skills that Hit Enemies, causing those Hits to Hobble Bleeding Enemies based on a portion of Physical Damage dealt.",["description"]="Усиливает умения, наносящие удары по врагам. Удары усиленными умениями стреноживают истекающих кровью врагов на основе части нанесённого физического урона.",["name"]="Стреноживание"}},
["SupportHolyDescentPlayer"]={["Holy Descent"]={["enDescription"]="Supports Skills that leap into the air, causing them to create Consecrated Ground when you land.",["description"]="Усиливает умения с прыжком в воздух. Усиленные умения создают освящённую землю в месте приземления.",["name"]="Священное сошествие"}},
["SupportHourglassPlayer"]={["Hourglass"]={["enDescription"]="Supports any damaging skill that you use yourself, causing it to deal significantly more damage but gain a long cooldown. Cannot support Skills which already have a cooldown.",["description"]="Усиливает любое наносящее урон умение, которое вы используете самостоятельно. Усиленное умение наносит значительно больше урона, но приобретает длительную перезарядку. Не может усиливать умения, уже обладающие перезарядкой.",["name"]="Песочные часы"}},
["SupportHulkingMinionsPlayer"]={["Hulking Minions"]={["enDescription"]="Supports Skills which summon Persistent Minions. Supported Minions are larger, have more Life, and deal more Damage, but cost significantly more Spirit.",["description"]="Усиливает умения, призывающие постоянных приспешников. Усиленные приспешники становятся больше, имеют больше здоровья и наносят больше урона, но требуют значительно больше духа.",["name"]="Громадные приспешники"}},
["SupportIceBitePlayer"]={["Ice Bite I"]={["enDescription"]="Supports damaging skills and Warcries you use yourself. Freezing an enemy with supported skills infuses your damage with Cold damage for a short time.",["description"]="Усиливает наносящие урон умения и боевые кличи, которые вы используете самостоятельно. Замораживание врага усиленными умениями на короткое время наделяет вас уроном от холода.",["name"]="Укус льда I"}},
["SupportIceBitePlayerTwo"]={["Ice Bite II"]={["enDescription"]="Supports damaging skills and Warcries you use yourself. Freezing an enemy with supported skills infuses your damage with Cold damage for a short time.",["description"]="Усиливает наносящие урон умения и боевые кличи, которые вы используете самостоятельно. Замораживание врага усиленными умениями на короткое время наделяет вас уроном от холода.",["name"]="Укус льда II"}},
["SupportIciclePlayer"]={["Icicle"]={["enDescription"]="Supports any Skill which creates Ice Crystals, causing them to be created with lower Life.",["description"]="Усиливает любое умение, создающее ледяные кристаллы. Созданные кристаллы становятся менее прочными.",["name"]="Сосулька"}},
["SupportIgniteDurationPlayer"]={["Eternal Flame I"]={["enDescription"]="Supports any skill that Hits enemies, causing its Ignites to be inflicted less often but last longer.",["description"]="Усиливает любое умение, наносящее удары по врагам. Поджоги усиленных умений накладываются реже, но действуют дольше.",["name"]="Вечное пламя I"}},
["SupportIgniteDurationPlayerThree"]={["Eternal Flame III"]={["enDescription"]="Supports any skill that Hits enemies, causing it to refresh Ignites on Critical Hit.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения обновляют поджоги при критическом попадании.",["name"]="Вечное пламя III"}},
["SupportIgniteDurationPlayerTwo"]={["Eternal Flame II"]={["enDescription"]="Supports any skill that Hits enemies, causing its Ignites to last longer.",["description"]="Усиливает любое умение, наносящее удары по врагам. Поджоги усиленных умений действуют дольше.",["name"]="Вечное пламя II"}},
["SupportIgnitePlayer"]={["Ignite I"]={["enDescription"]="Supports any skill that Hits enemies, making it more likely to Ignite.",["description"]="Усиливает любое умение, наносящее удары по врагам, увеличивая вероятность поджечь им врага.",["name"]="Поджог I"}},
["SupportIgnitePlayerThree"]={["Ignite III"]={["enDescription"]="Supports any skill that Hits enemies, making it more likely to Ignite and causing inflicted Ignites to deal their damage more quickly.",["description"]="Усиливает любое умение, наносящее удары по врагам, увеличивая вероятность поджечь им врага и заставляя наложенные поджоги наносить урон быстрее.",["name"]="Поджог III"}},
["SupportIgnitePlayerTwo"]={["Ignite II"]={["enDescription"]="Supports any skill that Hits enemies, making it more likely to Ignite.",["description"]="Усиливает любое умение, наносящее удары по врагам, увеличивая вероятность поджечь им врага.",["name"]="Поджог II"}},
["SupportImmolatePlayer"]={["Immolate"]={["enDescription"]="Supports Attacks, granting them extra Fire damage against Ignited enemies but making them unable to Ignite enemies themselves.",["description"]="Усиливает атаки. Усиленные умения наносят дополнительный урон от огня подожжённым врагам, но сами не могут поджигать врагов.",["name"]="Жертвенность"}},
["SupportImpalePlayer"]={["Impale"]={["enDescription"]="Supports Attacks, causing them to Impale on Hit but making them unable to Extract Impale themselves.",["description"]="Усиливает атаки, даруя им шанс наложить Прокол при нанесении удара, но усиленные умения не могут сами извлекать Проколы.",["name"]="Прокол"}},
["SupportIncisionPlayer"]={["Incision"]={["enDescription"]="Supports Attack Skills. Supported Skills inflict Incision on Hit, which causes Enemies to be increasingly more likely to be inflicted with Bleeding. All Incision is removed from a target on inflicting it with Bleeding.",["description"]="Усиливает умения атак. Усиленные умения накладывают Разрез при нанесении удара, что постепенно увеличивает вероятность наложить на врага кровотечение. Все Разрезы снимаются с цели при наложении на неё кровотечения.",["name"]="Разрез"}},
["SupportIncreaseLimitPlayer"]={["Overabundance I"]={["enDescription"]="Supports Skills which have a Limit, increasing that Limit at the cost of their duration. Only applies to restrictions that use the word \"Limit\".",["description"]="Усиливает умения, имеющие лимит, увеличивая этот лимит ценой их длительности. Действует только на ограничения, обозначенные словом «‎лимит».",["name"]="Переизбыток I"}},
["SupportIncreaseLimitPlayerThree"]={["Overabundance III"]={["enDescription"]="Supports Skills which have a Limit, doubling that Limit, but Cursing yourself on Supported Skill use. Only applies to restrictions that use the word \"Limit\". Cannot support Persistent Skills.",["description"]="Усиливает умения, имеющие лимит, удваивая этот лимит ценой наложения проклятия на вас при использовании усиленного умения. Действует только на ограничения, обозначенные словом «‎лимит». Не может усиливать постоянные умения.",["name"]="Переизбыток III"}},
["SupportIncreaseLimitPlayerTwo"]={["Overabundance II"]={["enDescription"]="Supports Skills which have a Limit, increasing that Limit at the cost of their duration. Only applies to restrictions that use the word \"Limit\".",["description"]="Усиливает умения, имеющие лимит, увеличивая этот лимит ценой их длительности. Действует только на ограничения, обозначенные словом «‎лимит».",["name"]="Переизбыток II"}},
["SupportIncreasedCriticalDamagePlayer"]={["Supercritical"]={["enDescription"]="Supports any skill that Hits enemies, causing it to deal more damage with Critical Hits but have less Critical Hit chance.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленное умение наносит больше урона при критических попаданиях, но имеет меньший шанс критического попадания.",["name"]="Сверхкритический удар"}},
["SupportInevitableCriticalsPlayer"]={["Inexorable Critical I"]={["enDescription"]="Supports any skill you use yourself that Hits enemies, causing it to accumulate Critical Hit chance over time.",["description"]="Усиливает любое умение, наносящее удары по врагам, которое вы используете самостоятельно. Усиленные умения постепенно накапливают шанс критического попадания.",["name"]="Неотвратимые критические удары I"}},
["SupportInevitableCriticalsPlayerTwo"]={["Inexorable Critical II"]={["enDescription"]="Supports any skill you use yourself that Hits enemies, causing it to accumulate Critical Hit chance over time, but also reduce your Critical Damage Bonus.",["description"]="Усиливает любое умение, наносящее удары по врагам, которое вы используете самостоятельно. Усиленные умения постепенно накапливают шанс критического попадания, но также уменьшают ваш бонус к критическому урону.",["name"]="Неотвратимые критические удары II"}},
["SupportInfernalLegionPlayer"]={["Infernal Legion I"]={["enDescription"]="Supports skills which create Minions which can be damaged, causing them and enemies near them to Ignite. The damage of the Ignite is based on the Life of the supported Minion.",["description"]="Усиливает умения, создающие приспешников, которым можно нанести урон. Приспешники и враги рядом с ними поджигаются. Урон, наносимый поджогом, основывается на здоровье усиленного Minion|приспешника].",["name"]="Пылающий легион I"}},
["SupportInfernalLegionPlayerThree"]={["Infernal Legion III"]={["enDescription"]="Supports skills which create Minions which can be damaged, causing them and enemies near them to Ignite. The damage of the Ignite is based on the Life of the supported Minion.",["description"]="Усиливает умения, создающие приспешников, которым можно нанести урон. Приспешники и враги рядом с ними поджигаются. Урон, наносимый поджогом, основывается на здоровье усиленного Minion|приспешника].",["name"]="Пылающий легион III"}},
["SupportInfernalLegionPlayerTwo"]={["Infernal Legion II"]={["enDescription"]="Supports skills which create Minions which can be damaged, causing them and enemies near them to Ignite. The damage of the Ignite is based on the Life of the supported Minion.",["description"]="Усиливает умения, создающие приспешников, которым можно нанести урон. Приспешники и враги рядом с ними поджигаются. Урон, наносимый поджогом, основывается на здоровье усиленного Minion|приспешника].",["name"]="Пылающий легион II"}},
["SupportInnervatePlayer"]={["Innervate"]={["enDescription"]="Supports damaging skills you use yourself. Killing a Shocked enemy with supported skills imbues your damage with Lightning damage for a short time.",["description"]="Усиливает наносящие урон умения, которые вы используете самостоятельно. Убийство врага под действием шока усиленными умениями кратковременно наделяет вас уроном от молнии.",["name"]="Возбуждение"}},
["SupportIntenseAgonyPlayer"]={["Intense Agony"]={["enDescription"]="Supports Spells that deal non-Ailment damage over time, causing them to have a shorter duration but deal substantially more damage over time with Debuffs inflicted against enemies on full life.",["description"]="Усиливает чары, наносящие постепенный урон не от состояний. Длительность усиленные умений сокращается, но они наносят значительно больше постепенного урона отрицательными эффектами, наложенными на врагов с полным здоровьем.",["name"]="Интенсивная агония"}},
["SupportInterludePlayer"]={["Remnant Potency I"]={["enDescription"]="Supports Skills which create Remnants, making those Remnants more powerful.",["description"]="Усиливает умения, создающие сгустки, делая эти сгустки более сильными.",["name"]="Сила сгустков I"}},
["SupportInterludePlayerThree"]={["Remnant Potency III"]={["enDescription"]="Supports Skills which create Remnants, making those Remnants more powerful, but delaying their effect.",["description"]="Усиливает умения, создающие сгустки, делая эти сгустки более сильными, но задерживая их эффект.",["name"]="Сила сгустков III"}},
["SupportInterludePlayerTwo"]={["Remnant Potency II"]={["enDescription"]="Supports Skills which create Remnants, making those Remnants more powerful, but delaying their effect.",["description"]="Усиливает умения, создающие сгустки, делая эти сгустки более сильными, но задерживая их эффект.",["name"]="Сила сгустков II"}},
["SupportInvocationPlayer"]={["Invocation"]={["enDescription"]="Supports Spell skills, causing them to reduce the cast time of other skills when used. Cannot support Totem skills, Channelling skills, Triggering skills, instant skills, or skills with a Reservation.",["description"]="Усиливает умения чар. Усиленные умения сокращают время сотворения других умений при использовании. Не может усиливать умения тотемов, поддерживаемые умения, срабатывающие умения, мгновенные умения или умения с удержанием.",["name"]="Воззвание"}},
["SupportIronGripPlayer"]={["DNT-UNUSED Iron Grip"]={["enDescription"]="DNT-UNUSED Modifiers to Melee damage also apply to Projectile damage for supported skill",["description"]="DNT-UNUSED Modifiers to Melee damage also apply to Projectile damage for supported skill",["name"]="Железная хватка"}},
["SupportIronWillPlayer"]={["DNT-UNUSED Iron Will"]={["enDescription"]="DNT-UNUSED Modifiers to Melee damage also apply to Spell damage for supported skill",["description"]="DNT-UNUSED Modifiers to Melee damage also apply to Spell damage for supported skill",["name"]="Железная воля"}},
["SupportJaggedGroundPlayer"]={["Jagged Ground I"]={["enDescription"]="Supports Slam skills. Supported Skills will consume Endurance Charges on use to create Jagged Ground. Cannot Support Skills which consume Endurance Charges.",["description"]="Усиливает умения мощных ударов. Усиленные умения поглощают заряды выносливости при использовании и создают вздыбленную землю. Не может усиливать умения, поглощающие заряды выносливости.",["name"]="Вздыбленная земля I"}},
["SupportJaggedGroundPlayerTwo"]={["Jagged Ground II"]={["enDescription"]="Supports Slam skills. Aftershocks caused by Supported Slam Skills always create patches of Jagged Ground.",["description"]="Усиливает умения мощных ударов. Вызванные усиленными умениями остаточные волны всегда создают участки вздыбленной земли.",["name"]="Вздыбленная земля II"}},
["SupportKalisasCrescendoPlayer"]={["Kalisa's Crescendo"]={["enDescription"]="Supports Curse Skills. Enemies Cursed by Supported Skills are Pacified for the final portion of the Supported Curse's duration.",["description"]="Усиливает умения проклятий. Проклятые усиленными умениями враги усмиряются к концу времени действия проклятия.",["name"]="Крещендо Калисы"}},
["SupportKaomsMadnessPlayer"]={["Kaom's Madness"]={["enDescription"]="Supports Skills which create fissures in the ground, causing them to create many additional fissures at the cost of damage, speed, and area of effect.",["description"]="Усиливает умения, создающие расселины в земле. Усиленные умения создают много дополнительных расселин ценой снижения урона, скорости и области действия.",["name"]="Безумие Каома"}},
["SupportKhatalsRejuvenationPlayer"]={["Khatal's Rejuvenation"]={["enDescription"]="Supports Skills that generate Remnants. Picking up Remnants from Supported Skills grants Khatal's Rejuvenation.",["description"]="Усиливает умения, создающие сгустки. Подбор сгустков от усиленных умений дарует Оживление Хаталя.",["name"]="Оживление Хаталя"}},
["SupportKnightsAnthem"]={["Styrn's Anthem"]={["enDescription"]="DNT Description",["description"]="DNT Description",["name"]="Гимн Стирна"}},
["SupportKnockbackPlayer"]={["Knockback"]={["enDescription"]="Supports any skill that Hits enemies, causing it to Knock Back enemies.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленное умение отбрасывает врагов.",["name"]="Отбрасывание"}},
["SupportKnockbackWavePlayer"]={["Wind Wave"]={["enDescription"]="Supports any skill that you can use, triggering a blast of wind that Knocks Back enemies if you are Stunned while using it.",["description"]="Усиливает любое умение, которое вы можете использовать. Если при использовании усиленного умения вы получаете оглушение, вызывает порыв ветра, отбрасывающий врагов.",["name"]="Воздушная волна"}},
["SupportKulemaksDominionPlayer"]={["Kulemak's Dominion"]={["enDescription"]="Supports Offering Skills, causing your Cascadable Spells to Cascade to the locations of Supported Offerings.",["description"]="Усиливает умения подношений, заставляя ваши каскадные чары каскадно поражать области усиленных подношений.",["name"]="Господство Кулемака"}},
["SupportKurgalsLeashPlayer"]={["Kurgal's Leash"]={["enDescription"]="Supports Commandable Minions causing you and the Supported Minion to gain Unholy Might when you Command them.",["description"]="Усиливает приспешников с умениями приказов, даруя вам и усиленному приспешнику Нечестивое могущество, когда вы отдаёте ему приказ.",["name"]="Поводок Каргала"}},
["SupportLastGaspPlayer"]={["Last Gasp"]={["enDescription"]="Supports Skills that create Persistent Minions, causing those Minions to fight on when they are fatally wounded, dying after a short duration.",["description"]="Усиливает умения, создающие постоянных приспешников. Получив смертельное ранение, приспешники усиленных умений продолжают короткое время сражаться.",["name"]="Последний вздох"}},
["SupportLastingFrostPlayer"]={["Deep Freeze"]={["enDescription"]="Supports any skill that Hits enemies, causing Freeze it inflicts to last longer.",["description"]="Усиливает любое умение, наносящее удары по врагам, увеличивая длительность накладываемой им заморозки.",["name"]="Глубокая заморозка"}},
["SupportLastingGroundPlayer"]={["Lasting Ground"]={["enDescription"]="Supports Skills that create Ground Surfaces, causing those surfaces to last longer.",["description"]="Усиливает умения, создающие наземные эффекты, и продлевает действие таких эффектов.",["name"]="Долговременная земля"}},
["SupportLastingShockPlayer"]={["Lasting Shock"]={["enDescription"]="Supports any skill that Hits enemies or inflicts Shock, causing its Shocks to be inflicted less often but last longer.",["description"]="Усиливает любое умение, наносящее удары по врагам или накладывающее шок. Шок усиленных умений накладывается реже, но действует дольше.",["name"]="Длительный шок"}},
["SupportLeveragePlayer"]={["Leverage"]={["enDescription"]="Supports Skills which Hit Enemies. Supported Skills gain increased chance to Critically Hit against Immobilised Enemies.",["description"]="Усиливает умения, наносящие удары по врагам. Усиленные умения приобретают повышенный шанс критического попадания по обездвиженным врагам.",["name"]="Перевес"}},
["SupportLifeFlaskPlayer"]={["Life Bounty"]={["enDescription"]="Supports any skill that Hits enemies, causing enemies it kills to grant more Life Flask charges.",["description"]="Усиливает любое умение, наносящее удары по врагам. Убитые усиленным умением враги даруют больше зарядов флакона жизни.",["name"]="Дар жизни"}},
["SupportLifeLeechPlayer"]={["Life Leech I"]={["enDescription"]="Supports Attacks, causing their Physical damage to Leech Life.",["description"]="Усиливает атаки. Физический урон усиленных умений похищает здоровье.",["name"]="Похищение здоровья I"}},
["SupportLifeLeechPlayerThree"]={["Life Leech III"]={["enDescription"]="Supports Attacks, causing their Physical damage to Leech Life and preventing Leech gained this way from being removed at full Life.",["description"]="Усиливает атаки. Физический урон усиленных умений похищает здоровье. Похищение, действующее таким образом, не удаляется при полном здоровье.",["name"]="Похищение здоровья III"}},
["SupportLifeLeechPlayerTwo"]={["Life Leech II"]={["enDescription"]="Supports Attacks, causing their Physical damage to Leech Life.",["description"]="Усиливает атаки. Физический урон усиленных умений похищает здоровье.",["name"]="Похищение здоровья II"}},
["SupportLifeOnCullPlayer"]={["Life Drain"]={["enDescription"]="Supports any skill that Hits enemies, causing you to recover Life when it Culls an enemy.",["description"]="Усиливает любое умение, наносящее удары по врагам. При добивании врага усиленным умением вы восстанавливаете здоровье.",["name"]="Вытягивание жизни"}},
["SupportLightningExposurePlayer"]={["Lightning Exposure"]={["enDescription"]="Supports any skill that Hits enemies, causing it to inflict Exposure when inflicting Shock.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения накладывают восприимчивость при наложении шока.",["name"]="Восприимчивость к молнии"}},
["SupportLightningMasteryPlayer"]={["Lightning Mastery"]={["enDescription"]="Supports Lightning skills, granting them an additional level. Does not support skills which do not have levels.",["description"]="Усиливает умения молнии, даруя им дополнительный уровень. Не усиливает умения, не имеющие уровней.",["name"]="Мастерство молнии"}},
["SupportLightningPenetrationPlayer"]={["Lightning Penetration"]={["enDescription"]="Supports any skill that Hits enemies, making those Hits Penetrate enemy Lightning resistance.",["description"]="Усиливает любое умение, наносящее удары по врагам. Удары этим умением пробивают вражеское сопротивление молнии.",["name"]="Пронизывающие молнии"}},
["SupportLivingLightningPlayer"]={["Living Lightning"]={["enDescription"]="Supports Skills which cause Damaging Hits. Living Lightning Minions are created when dealing Lightning damage with Supported Skills - bundles of living electricity that target nearby enemies with Chaining Attacks. Enemies will not directly engage these Minions, and can pass through them. Does not modify skills used by Minions.",["description"]="Усиливает умения, наносящие урон ударами. При нанесении урона от молнии усиленными умениями создаются приспешники живой молнии – сгустки живого электричества, которые выбирают целью ближайших врагов, совершая атаки по цепи. Враги не будут атаковать этих приспешников напрямую и могут проходить сквозь них. Не может усиливать умения, используемые приспешниками.",["name"]="Живая молния"}},
["SupportLivingLightningPlayerTwo"]={["Living Lightning II"]={["enDescription"]="Supports Skills which cause Damaging Hits. Living Lightning Minions are created when dealing Lightning damage with Supported Skills - bundles of living electricity that target nearby enemies with Chaining Attacks. Enemies will not directly engage these Minions, and can pass through them. Does not modify skills used by Minions.",["description"]="Усиливает умения, наносящие урон ударами. При нанесении урона от молнии усиленными умениями создаются приспешники живой молнии – сгустки живого электричества, которые выбирают целью ближайших врагов, совершая атаки по цепи. Враги не будут атаковать этих приспешников напрямую и могут проходить сквозь них. Не может усиливать умения, используемые приспешниками.",["name"]="Живая молния II"}},
["SupportLockdownPlayer"]={["Lockdown"]={["enDescription"]="Supports any skill that Hits enemies, causing any Pin buildup it inflicts to be stronger the closer the enemy is to you.",["description"]="Усиливает любое умение, наносящее удары по врагам. Любое накапливаемое усиленными умениями пригвождение становится тем сильнее, чем ближе противник к вам.",["name"]="Обездвиживание"}},
["SupportLongFusePlayer"]={["Long Fuse I"]={["enDescription"]="Supports Skills which have a Detonation Time, causing those Skills to have much higher Detonation Time and detonation damage.",["description"]="Усиливает умения, обладающие временем детонации. Усиленные умения имеют гораздо большие время детонации и урон детонации.",["name"]="Длинный запал I"}},
["SupportLongFusePlayerTwo"]={["Long Fuse II"]={["enDescription"]="Supports Skills which have a Detonation Time, causing those Skills to have much higher Detonation Time and detonation damage.",["description"]="Усиливает умения, обладающие временем детонации. Усиленные умения имеют гораздо большие время детонации и урон детонации.",["name"]="Длинный запал II"}},
["SupportLoyaltyPlayer"]={["Loyalty"]={["enDescription"]="Supports Skills that create Companions which can be damaged. Minions created by Supported Skills take a portion of Hit Damage you would otherwise have taken, but have lowered maximum Life.",["description"]="Усиливает умения, создающие компаньонов, которым можно нанести урон. Приспешники, созданные усиленными умениями, получают часть урона от ударов вместо вас, но имеют сниженный максимум здоровья.",["name"]="Преданность"}},
["SupportMagneticRemnantsPlayer"]={["Magnetic Remnants"]={["enDescription"]="Supports Skills which create Remnants, allowing those Remnants to be collected from further away.",["description"]="Усиливает умения, создающие сгустки, позволяя собирать созданные сгустки с большего расстояния.",["name"]="Магнитные останки"}},
["SupportMagnifiedAreaPlayer"]={["Magnified Area I"]={["enDescription"]="Supports any skill with an area of effect, making it larger.",["description"]="Усиливает мощные атаки с областью действия, увеличивая её.",["name"]="Увеличенная область I"}},
["SupportMagnifiedAreaPlayerTwo"]={["Magnified Area II"]={["enDescription"]="Supports any skill with an area of effect, making it larger.",["description"]="Усиливает мощные атаки с областью действия, увеличивая её.",["name"]="Увеличенная область II"}},
["SupportMaimPlayer"]={["Maim"]={["enDescription"]="Supports Attacks, causing them to Maim enemies.",["description"]="Усиливает атаки. Усиленные умения изувечивают врагов.",["name"]="Увечье"}},
["SupportMaladyPlayer"]={["Malady"]={["enDescription"]="Supports Skills which can cause Damaging Hits, causing base chance to inflict Bleeding with Supported Skills to instead apply to base chance to Poison, and causing base chance to Poison to instead apply to Bleeding.",["description"]="Усиливает умения, которые могут наносить урон ударами. Базовый шанс наложить кровотечение усиленными умениями вместо этого применяется к отравлению, а базовый шанс отравить вместо этого применяется к кровотечению.",["name"]="Хворь"}},
["SupportManaFlarePlayer"]={["Mana Flare"]={["enDescription"]="Supports any Spell that Hits enemies, causing it to trigger a Mana Flare on Critical Hit. The Mana Flare consumes your Mana to deal Fire damage. Cannot support the skills of Minions.",["description"]="Усиливает любые чары, наносящие удары по врагам. Усиленные умения вызывают срабатывание Вспышки маны при критическом попадании. Вспышка маны поглощает вашу ману и наносит урон от огня. Не может усиливать умения приспешников.",["name"]="Вспышка маны"}},
["SupportManaFlaskPlayer"]={["Mana Bounty"]={["enDescription"]="Supports any skill that Hits enemies, causing enemies it kills to grant more Mana Flask charges.",["description"]="Усиливает любое умение, наносящее удары по врагам. Убитые усиленным умением враги даруют больше зарядов флакона маны.",["name"]="Дар маны"}},
["SupportManaFountainPlayer"]={["Font of Mana"]={["enDescription"]="Supports Skills which create Totems. Totems created by supported Skills generate a Font of Mana which will Leech Mana to Allies within it.",["description"]="Усиливает умения, создающие тотемы. Тотемы, созданные усиленными умениями, создают купель маны, которая восстанавливает ману от похищения союзникам в ней.",["name"]="Купель маны"}},
["SupportManaLeechPlayer"]={["Mana Leech"]={["enDescription"]="Supports Attacks, causing their Physical damage to Leech Mana.",["description"]="Усиливает атаки. Физический урон усиленных умений похищает ману.",["name"]="Похищение маны"}},
["SupportManaOnCullPlayer"]={["Soul Drain"]={["enDescription"]="Supports any skill that Hits enemies, causing you to recover Mana when it Culls an enemy.",["description"]="Усиливает любое умение, наносящее удары по врагам. При добивании врага усиленным умением вы восстанавливаете ману.",["name"]="Вытягивание души"}},
["SupportMarkForDeathPlayer"]={["Mark for Death"]={["enDescription"]="Supports Mark Skills. Enemies affected by Supported Marks will have their Armour Broken by Physical Damage they take.",["description"]="Усиливает умения меток. Броня врагов под действием усиленных меток будет разрушаться при получении ими физического урона.",["name"]="Метка смерти"}},
["SupportMarkForDeathPlayerTwo"]={["Mark for Death II"]={["enDescription"]="Supports Mark Skills. Enemies affected by Supported Marks will have their Armour Broken by Physical Damage they take.",["description"]="Усиливает умения меток. Броня врагов под действием усиленных меток будет разрушаться при получении ими физического урона.",["name"]="Метка смерти II"}},
["SupportMarkOfSiphoningPlayer"]={["Mark of Siphoning"]={["enDescription"]="Supports Mark Skills, causing enemies they Mark to Leech Mana to you when you Hit them with Attacks.",["description"]="Усиливает умения меток. Удары атаками по отмеченным усиленными умениями врагам похищают ману.",["name"]="Метка вытягивания"}},
["SupportMarkOfSiphoningPlayerTwo"]={["Mark of Siphoning II"]={["enDescription"]="Supports Mark Skills, causing enemies they Mark to Leech Life and Mana to you when you Hit them with Attacks.",["description"]="Усиливает умения меток. Удары атаками по отмеченным усиленными умениями врагам похищают здоровье и ману.",["name"]="Метка вытягивания II"}},
["SupportMeatShieldPlayer"]={["Meat Shield I"]={["enDescription"]="Supports skills which create Minions, granting them less damage taken but making them deal less damage. Cannot support skills which create undamageable Minions.",["description"]="Усиливает умения, создающие приспешников. Приспешники получают меньше урона, но и наносят меньше урона. Не может усиливать умения, создающие приспешников, которым нельзя нанести урон.",["name"]="Живой щит I"}},
["SupportMeatShieldPlayerTwo"]={["Meat Shield II"]={["enDescription"]="Supports skills which create Minions, granting them less damage taken but making them deal less damage.",["description"]="Усиливает умения, создающие приспешников. Приспешники получают меньше урона, но и наносят меньше урона.",["name"]="Живой щит II"}},
["SupportMedvedsFelling"]={["Medved's Felling"]={["enDescription"]="Supports Melee Attacks you use yourself, causing them to attack faster the more Rage you have and grant Rage on Hit, but also making you lose Life based on your Rage when using them.",["description"]="Усиливает атаки ближнего боя, которые вы используете самостоятельно, повышая их скорость тем сильнее, чем больше у вас свирепости. Усиленные атаки также даруют свирепость при нанесении удара, но при их использовании вы теряете здоровье на основе вашей свирепости.",["name"]="Неистовство Медведя"}},
["SupportMeleePhysicalDamagePlayer"]={["Heavy Swing"]={["enDescription"]="Supports Melee Attacks, boosting their Physical damage at the cost of Attack Speed.",["description"]="Усиливает атаки ближнего боя, повышая их физический урон ценой скорости атаки.",["name"]="Тяжёлый замах"}},
["SupportMhachasGuidance"]={["DNT Mhacha's Guidance"]={["enDescription"]="DNT Description",["description"]="DNT Description",["name"]="DNT Mhacha's Guidance"}},
["SupportMinionInstabilityPlayer"]={["Minion Instability"]={["enDescription"]="Supports skills which create Minions, causing them to violently explode when reduced to Low Life.",["description"]="Усиливает умения, создающие приспешников. Приспешники усиленных умений взрываются при малом количестве здоровья.",["name"]="Нестабильность приспешников"}},
["SupportMinionMasteryPlayer"]={["Minion Mastery"]={["enDescription"]="Supports Minion skills, granting them an additional level. Does not support skills which do not have levels.",["description"]="Усиливает умения приспешников, даруя им дополнительный уровень. Не усиливает умения, не имеющие уровней.",["name"]="Мастерство приспешников"}},
["SupportMinionMeleeSplashPlayer"]={["Minion Splash I"]={["enDescription"]="Supports Skills which create Minions which Strike, causing those Minions' Strikes to have Melee Splash.",["description"]="Усиливает умения, создающие приспешников, которые наносят удары. Удары этих приспешников наносят урон по площади.",["name"]="Удар по площади приспешников I"}},
["SupportMinionMeleeSplashPlayerTwo"]={["Minion Splash II"]={["enDescription"]="Supports Skills which create Minions which Strike, increasing their Area of Effect and causing those Minions' Strikes to have Melee Splash.",["description"]="Усиливает умения, создающие приспешников, которые наносят удары, и увеличивает их область действия. Удары этих приспешников наносят урон по площади.",["name"]="Удар по площади приспешников II"}},
["SupportMinionPactPlayer"]={["Minion Pact I"]={["enDescription"]="Supports damaging skills you use yourself, draining the life from one of your Minions on use in order to boost the skill's damage. Only takes effect if you have a Minion with enough life to drain the full amount.",["description"]="Усиливает наносящие урон умения, которые вы используете самостоятельно, при использовании вытягивая здоровье одного из ваших приспешников для повышения урона умения. Срабатывает только если у вас есть приспешник с достаточным количеством здоровья.",["name"]="Договор служения I"}},
["SupportMinionPactPlayerTwo"]={["Minion Pact II"]={["enDescription"]="Supports damaging skills you use yourself, draining the life from one of your Minions on use in order to boost the skill's damage. Only takes effect if you have a Minion with enough life to drain the full amount.",["description"]="Усиливает наносящие урон умения, которые вы используете самостоятельно, при использовании вытягивая здоровье одного из ваших приспешников для повышения урона умения. Срабатывает только если у вас есть приспешник с достаточным количеством здоровья.",["name"]="Договор служения II"}},
["SupportMobilityPlayer"]={["Mobility"]={["enDescription"]="Supports skills that can be used while moving, allowing you to move faster while using them.",["description"]="Усиливает умения, которые можно использовать во время передвижения, позволяя вам передвигаться быстрее во время их использования.",["name"]="Мобильность"}},
["SupportMomentumPlayer"]={["Momentum"]={["enDescription"]="Supports any damaging skill that you use yourself, causing it to deal more damage if you move a sufficient distance while using the skill. Teleportation does not count towards the distance travelled.",["description"]="Усиливает любое наносящее урон умение, которое вы используете самостоятельно. Усиленное умение наносит больше урона, если во время его использования герой переместится на достаточное расстояние. Телепортация не учитывается за пройденное расстояние.",["name"]="Разбег"}},
["SupportMorganasTempestPlayer"]={["Morgana's Tempest"]={["enDescription"]="Supports Storm skills, increasing their Limit and causing them to move quickly from the user to the target location, but become less effective. Cannot Support Triggered Skills.",["description"]="Усиливает умения бурь, увеличивая их лимит и заставляя быстро двигаться от сотворившего умение к указанной точке. Но при этом усиленные умения становятся менее эффективны. Не может усиливать срабатывающие умения.",["name"]="Буря Морганы"}},
["SupportMorrigansInsight"]={["Mórrigan's Insight"]={["enDescription"]="Supports any skill that Hits enemies, causing them to deal more damage and trigger Nature's Exchange when consuming Freeze on enemies. Cannot support skills that Consume Freeze.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения наносят больше урона и вызывают срабатывание Природного обмена при поглощении заморозки на врагах. Не может усиливать умения, поглощающие заморозку.",["name"]="Проницательность Морриган"},["Morrigan's Insight"]={["enDescription"]="Supports any skill that Hits enemies, causing them to deal more damage and trigger Nature's Exchange when consuming Freeze on enemies. Cannot support skills that Consume Freeze.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения наносят больше урона и вызывают срабатывание Природного обмена при поглощении заморозки на врагах. Не может усиливать умения, поглощающие заморозку.",["name"]="Проницательность Морриган"}},
["SupportMultishotPlayer"]={["Multishot I"]={["enDescription"]="Supports Projectile skills, making them fire extra Projectiles. Also lowers Attack and Cast speed of supported skills, as well as lessening their damage.",["description"]="Усиливает умения снарядов. Усиленные умения выпускают дополнительные снаряды. Также снижает скорость атаки и сотворения чар усиленных умений, и уменьшает их урон.",["name"]="Залповый огонь I"}},
["SupportMultishotPlayerTwo"]={["Multishot II"]={["enDescription"]="Supports Projectile skills, making them fire extra Projectiles. Also lowers Attack and Cast speed of supported skills, as well as lessening their damage.",["description"]="Усиливает умения снарядов. Усиленные умения выпускают дополнительные снаряды. Также снижает скорость атаки и сотворения чар усиленных умений, и уменьшает их урон.",["name"]="Залповый огонь II"}},
["SupportMusterPlayer"]={["Muster"]={["enDescription"]="Supports Skills which summon Minions. Supported Minions deal more Damage the more different kinds of Reviving Minions you have summoned.",["description"]="Усиливает умения, призывающие приспешников. Усиленные приспешники наносят тем больше урона, чем больше разных видов возрождающихся приспешников у вас призвано.",["name"]="Сборище"}},
["SupportMysticismPlayer"]={["Mysticism I"]={["enDescription"]="Supports Persistent Buff Skills, causing you to deal increased Spell Damage while on full Energy Shield while the Supported Skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами. Пока усиленное умение активно, вы наносите увеличенный урон от чар при полном энергетическом щите.",["name"]="Мистицизм I"}},
["SupportMysticismPlayerTwo"]={["Mysticism II"]={["enDescription"]="Supports Persistent Buff Skills, causing you to deal increased Spell Damage while on full Energy Shield while the Supported Skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами. Пока усиленное умение активно, вы наносите увеличенный урон от чар при полном энергетическом щите.",["name"]="Мистицизм II"}},
["SupportNadirPlayer"]={["Nadir"]={["enDescription"]="DNT-UNUSED Supports Skills which gain Stages or Seals. Supported Skills have lower Maximum Stage or Seal count, but have a Minimum Stage or Seal count they cannot fall below.",["description"]="DNT-UNUSED Усиливает умения, получающие стадии или печати. У усиленных умений снижен максимум стадий или печатей, но есть минимум стадий и печатей, ниже которого они не могут опуститься.",["name"]="Надир"}},
["SupportNeuralOverloadPlayer"]={["Neural Overload"]={["enDescription"]="Supports any skill that Hits enemies. Nearby enemies are marked when they are Primed for Electrocution, and hitting a marked enemy with a supported skill will Electrocute them.",["description"]="Усиливает любое умение, наносящее удары по врагам. Ближайшие враги отмечаются, когда они готовы к электризации, и попадание по отмеченному врагу усиленным умением накладывает на них электризацию.",["name"]="Нейронная перегрузка"}},
["SupportNimbleReloadPlayer"]={["Nimble Reload"]={["enDescription"]="Supports Crossbow Ammunition Skills, causing them to Reload bolts significantly faster.",["description"]="Усиливает умения боезапаса самострелов. Усиленные умения перезаряжают болты значительно быстрее.",["name"]="Ловкая перезарядка"}},
["SupportNovaProjectilesPlayer"]={["Nova Projectiles I"]={["enDescription"]="Supports Projectile Skills, making them fire Projectiles in a circle. Does not Support Skills which rain down Projectiles from above.",["description"]="Усиливает умения снарядов. Усиленные умения выпускают дополнительные снаряды по кругу. Не усиливает умения, выпускающие снаряды дождём.",["name"]="Кольцо снарядов I"}},
["SupportNovaProjectilesTwoPlayer"]={["Nova Projectiles II"]={["enDescription"]="Supports Projectile Skills, making them fire extra Projectiles in a circle, at the cost of Damage and gaining a cooldown. Does not Support Skills which rain down Projectiles from above. Cannot Support Skills which already have a cooldown.",["description"]="Усиливает умения снарядов. Усиленные умения выпускают дополнительные снаряды по кругу ценой сниженного урона и появления перезарядки. Не может усиливать умения, выпускающие снаряды дождём. Не может усиливать умения, уже обладающие перезарядкой.",["name"]="Кольцо снарядов II"}},
["SupportOisinsOathPlayer"]={["Oisín's Oath"]={["enDescription"]="Supports Skills which Hit enemies, causing their Mana Leech to recover based on Elemental damage instead of Physical damage.",["description"]="Усиливает умения, наносящие удары по врагам. Восстановление от похищения маны усиленных умений основывается на уроне от стихий вместо физического урона.",["name"]="Клятва Исина"},["Oisin's Oath"]={["enDescription"]="Supports Skills which Hit enemies, causing their Mana Leech to recover based on Elemental damage instead of Physical damage.",["description"]="Усиливает умения, наносящие удары по врагам. Восстановление от похищения маны усиленных умений основывается на уроне от стихий вместо физического урона.",["name"]="Клятва Исина"}},
["SupportOlrothsConvictionPlayer"]={["Olroth's Conviction"]={["enDescription"]="Supports skills that can Empower a specific number of other skills, causing them to apply to more skill uses.",["description"]="Усиливает умения, способные улучшать определённое число других умений. Усиленные умения действуют на большее количество использований умений.",["name"]="Убеждённость Олрота"}},
["SupportOlrothsHubrisPlayer"]={["Olroth's Hubris"]={["enDescription"]="Supports Attacks you use or Trigger yourself, causing them to cost Runic Ward to use but deal additional Physical and Cold damage based on their Runic Ward cost, in addition to causing Physical damage to Contribute to Freeze buildup. Cannot Support Channelling Skills, Sustained Skills, or Skills without a cost.",["description"]="Усиливает атаки, которые вы используете самостоятельно или сами вызываете их срабатывание. Усиленные умения при использовании расходуют рунический барьер, но наносят дополнительный физический урон и урон от холода на основе расходуемого ими рунического барьера, а также их физический урон влияет на накопление заморозки. Не может усиливать поддерживаемые умения, непрерывные умения и умения, не имеющие расхода.",["name"]="Гордыня Олрота"}},
["SupportOpeningMovePlayer"]={["Opening Move"]={["enDescription"]="Supports Travel Skills which Hit enemies. Hits with Supported Skills against enemies on full life will Daze.",["description"]="Усиливает умения смещения, наносящие удары по врагам. Удары усиленными уениями по врагам с полным здоровьем накладывают оцепенение.",["name"]="Первый ход"}},
["SupportOutmaneuverPlayer"]={["Outmaneuver"]={["enDescription"]="Supports Skills you use yourself which can cause Damaging Hits. Supported Skills Break Armour against Parried Enemies.",["description"]="Усиливает самостоятельно используемые вами умения, которые могут наносить урон ударами. Усиленные умения разрушают броню у парированных врагов.",["name"]="Обходной манёвр"}},
["SupportOverchargePlayer"]={["Overcharge"]={["enDescription"]="Supports any skill that Hits enemies, making its Shocks more effective but reflecting them back to you as well.",["description"]="Усиливает любое умение, наносящее удары по врагам. Шок усиленных умений становится более эффективным, но также отражается в вас.",["name"]="Перегрузка"}},
["SupportOverextendPlayer"]={["Overextend"]={["enDescription"]="Supports Attack Skills you use yourself. Supported Skills deal more Damage with Critical Hits, but Critically Hitting an Enemy with them will Daze you for a short time.",["description"]="Усиливает умения атак, которые вы используете самостоятельно. Усиленные умения наносят больше урона критическими попаданиями, но критическое попадание ими по врагу кратковременно накладывает на вас оцепенение.",["name"]="Перенапряжение"}},
["SupportOverreachPlayer"]={["Overreach"]={["enDescription"]="Supports Attack Skills which deal Damage in an Area. Supported Skills have significantly increased Area of Effect, but are less Accurate against nearby targets.",["description"]="Усиливает умения атак, наносящие урон по области. Область действия усиленных умений значительно увеличивается, но их меткость против ближайших целей падает.",["name"]="Охват"}},
["SupportPayloadPlayer"]={["Payload"]={["enDescription"]="Supports Skills which fire Grenades, giving fired Grenades a chance to activate again, but lengthening their cooldowns.",["description"]="Усиливает умения, выстреливающие гранатами. Гранаты усиленных умений имеют шанс сработать повторно, но время их перезарядки увеличивается.",["name"]="Боезаряд"}},
["SupportPerfectEndurancePlayer"]={["Perfected Endurance"]={["enDescription"]="Supports skills which have a benefit for Perfect Timing. Supported Skills grant at least one Endurance Charge when Hitting an enemy with Perfect Timing.",["description"]="Усиливает умения, которые дают преимущества при использовании в идеальный момент. Усиленные умения даруют как минимум один заряд выносливости при нанесении удара во врагу в идеальный момент.",["name"]="Исключительная выносливость"}},
["SupportPerfectionPlayer"]={["Perfection"]={["enDescription"]="Supports skills which have a benefit for Perfectly Timing their use. On successfully executing Perfect Timing with Supported Skills, gain Perfection, which is a powerful damage buff. However, failing to execute any Perfect Timing (even with skills not supported by Perfection) will remove all Perfection on you.",["description"]="Усиливает умения, которые дают преимущества при использовании в идеальный момент. При успешном использовании идеального момента с усиленными умениями дарует Совершенство, являющееся мощным положительным эффектом увеличения урона. Однако неудачная попытка использовать идеальный момент (даже в случае умений, не усиленных Совершенством) снимет с вас все стадии Совершенства.",["name"]="Совершенство"}},
["SupportPerpetualChargePlayer"]={["Perpetual Charge"]={["enDescription"]="Supports skills that consume Power, Frenzy or Endurance Charges on use, giving them a chance not to remove each Charge while still gaining the benefits of consuming them.",["description"]="Усиливает умения, поглощающие заряды энергии, ярости или выносливости при использовании, даруя им шанс не потратить каждый заряд при сохранении всех преимуществ поглощения зарядов.",["name"]="Постоянный заряд"}},
["SupportPersistentGroundPlayer"]={["Persistent Ground I"]={["enDescription"]="Supports Skills which create Ground Surfaces, causing created Surfaces to last much longer.",["description"]="Усиливает умения, создающие наземные эффекты. Созданные эффекты длятся гораздо дольше.",["name"]="Постоянная земля I"}},
["SupportPersistentGroundPlayerThree"]={["Persistent Ground III"]={["enDescription"]="Supports Skills which create Ground Surfaces, causing created Surfaces to last much longer as well as lowering the Cooldown Recovery Speed of affected Enemies. Ground Surfaces from Supported Skills only end when their duration expires.",["description"]="Усиливает умения, создающие наземные эффекты. Созданные эффекты длятся гораздо дольше, пропадают только по окончании времени их действия, а также снижают скорость перезарядки попавших под их действие врагов.",["name"]="Постоянная земля III"}},
["SupportPersistentGroundPlayerTwo"]={["Persistent Ground II"]={["enDescription"]="Supports Skills which create Ground Surfaces, causing created Surfaces to last much longer and only end when their duration expires.",["description"]="Усиливает умения, создающие наземные эффекты. Созданные эффекты длятся гораздо дольше и пропадут только по окончании времени их действия.",["name"]="Постоянная земля II"}},
["SupportPhysicalMasteryPlayer"]={["Physical Mastery"]={["enDescription"]="Supports Physical skills, granting them an additional level. Does not support skills which do not have levels.",["description"]="Усиливает физические умения, даруя им дополнительный уровень. Не усиливает умения, не имеющие уровней.",["name"]="Мастерство физического урона"}},
["SupportPiercePlayer"]={["Pierce I"]={["enDescription"]="Supports Projectile skills, making their Projectiles Pierce an enemy but deal less damage after doing so.",["description"]="Усиливает умения снарядов. Снаряды усиленных умений пронзают врага, но после этого наносят меньше урона.",["name"]="Пронзание I"}},
["SupportPiercePlayerThree"]={["Pierce III"]={["enDescription"]="Supports Projectile skills, making their Projectiles Pierce an unlimited number of enemies, losing damage as they do so.",["description"]="Усиливает умения снарядов. Снаряды усиленных умений пронзают неограниченное число врагов, при этом теряя урон.",["name"]="Пронзание III"}},
["SupportPiercePlayerTwo"]={["Pierce II"]={["enDescription"]="Supports Projectile skills, making their Projectiles Pierce an enemy.",["description"]="Усиливает умения снарядов. Снаряды усиленных умений пронзают врага.",["name"]="Пронзание II"}},
["SupportPietysMercyPlayer"]={["Dominus' Grasp"]={["enDescription"]="Supports Projectile skills and any other skills that Chain, causing them to Chain more times.",["description"]="Усиливает умения снарядов и любые другие умения, наносящие удары по цепи. Усиленные умения наносят больше ударов по цепи.",["name"]="Хватка Владыки"}},
["SupportPinPlayer"]={["Pin I"]={["enDescription"]="Supports any skill that Hits enemies, allowing its Physical damage to Pin enemies but making it unable to Stun.",["description"]="Усиливает любое умение, наносящее удары по врагам. Физический урон усиленного умения может пригвождать врагов, но умение не может оглушать.",["name"]="Пригвождение I"}},
["SupportPinPlayerThree"]={["Pin III"]={["enDescription"]="Supports any skill that Hits enemies, allowing its Physical damage to Pin enemies but making it unable to Stun. Pin buildup caused by Supported Skill is lessened, but Pin duration is significantly longer.",["description"]="Усиливает любое умение, наносящее удары по врагам. Физический урон усиленного умения может пригвождать врагов, но умение не может оглушать. Усиленные умения накапливают меньше пригвождения, но оно длится значительно дольше.",["name"]="Пригвождение III"}},
["SupportPinPlayerTwo"]={["Pin II"]={["enDescription"]="Supports any skill that Hits enemies, allowing its Physical damage to Pin enemies but making it unable to Stun, as well as granting Critial Hit Chance against Immobilised enemies.",["description"]="Усиливает любое умение, наносящее удары по врагам. Физический урон усиленного умения может пригвождать врагов, но умение не может оглушать. Также повышает шанс критического попадания по обездвиженным врагам.",["name"]="Пригвождение II"}},
["SupportPinpointCriticalPlayer"]={["Pinpoint Critical"]={["enDescription"]="Supports any skill that Hits Enemies, causing it to Critically Hit more often but deal less damage with Critical Hits.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения совершают критические попадания чаще, но наносят меньше урона критическими попаданиями.",["name"]="Точечные критические удары"}},
["SupportPoisonPlayer"]={["Poison I"]={["enDescription"]="Supports any skill that Hits enemies, giving it a chance to Poison enemies.",["description"]="Усиливает любое умение, наносящее удары по врагам, добавляя ему шанс отравления врагов.",["name"]="Отравление I"}},
["SupportPoisonPlayerThree"]={["Poison III"]={["enDescription"]="Supports any skill that Hits enemies, giving it a chance to Poison enemies and causing it to inflict more powerful Poisons against Bleeding Enemies.",["description"]="Усиливает любое умение, наносящее удары по врагам, добавляя ему шанс отравления и заставляя накладывать более сильные отравления на истекающих кровью врагов.",["name"]="Отравление III"}},
["SupportPoisonPlayerTwo"]={["Poison II"]={["enDescription"]="Supports any skill that Hits enemies, giving it a chance to Poison enemies.",["description"]="Усиливает любое умение, наносящее удары по врагам, добавляя ему шанс отравления врагов.",["name"]="Отравление II"}},
["SupportPoisonSpores"]={["Poison Spores"]={["enDescription"]="Supports Plant Skills which Hit enemies. Supported Skills Trigger Toxic Pustule on Hitting an enemy.",["description"]="Усиливает умения растений, наносящие удары по врагам. Усиленные умения вызывают срабатывание Токсичной пустулы при нанесении удара по врагу.",["name"]="Ядовитые споры"}},
["SupportPotentExposurePlayer"]={["Potent Exposure"]={["enDescription"]="Supports Skills which apply Exposure to Enemies, increasing the effect of applied Exposure.",["description"]="Усиливает умения, накладывающие восприимчивость на врагов, усиливая эффект наложенной восприимчивости.",["name"]="Сильная восприимчивость"}},
["SupportPotentialPlayer"]={["Potential"]={["enDescription"]="Supports Skills that you use yourself. Supported Skills will consume a Power Charge on use if possible, and will be much more likely to Critically Hit if they do. Supported Skills cannot generate Power Charges. Cannot Support Skills which consume Power Charges.",["description"]="Усиливает умения, которые вы используете самостоятельно. Усиленные умения поглотят заряд энергии при использовании, если возможно, и в этом случае будут иметь гораздо более высокий шанс критического попадания. Усиленные умения не могут вырабатывать заряды энергии. Не может усиливать умения, поглощающие заряды энергии.",["name"]="Потенциал"}},
["SupportPracticalMagicPlayer"]={["Practical Magic I"]={["enDescription"]="Supports Skills which Hit enemies. Heavy Stunning an enemy with Supported Skills increases your Spell damage for a duration.",["description"]="Усиливает умения, наносящие удары по врагам. Сильное оглушение врага усиленными умениями временно увеличивает ваш урон от чар.",["name"]="Практическая магия I"}},
["SupportPracticalMagicPlayerTwo"]={["Practical Magic II"]={["enDescription"]="Supports Skills which Hit enemies. Heavy Stunning an enemy with Supported Skills increases your Spell damage for a duration.",["description"]="Усиливает умения, наносящие удары по врагам. Сильное оглушение врага усиленными умениями временно увеличивает ваш урон от чар.",["name"]="Практическая магия II"}},
["SupportPracticedComboPlayer"]={["Practiced Combo"]={["enDescription"]="Supports Strike Skills. Supported Skills have a chance to build additional Combo on Hit. Cannot support Skills used by Minions.",["description"]="Усиливает умения ударов. Усиленные умения имеют шанс накопить дополнительное Комбо при попадании. Не может усиливать умения, используемые приспешниками.",["name"]="Отработанный приём"}},
["SupportPrecisionPlayer"]={["Precision I"]={["enDescription"]="Supports Persistent Buff Skills, causing you to gain increased Accuracy while the Skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами. Пока активно, усиленное умение даёт вам повышенную меткость.",["name"]="Точность I"}},
["SupportPrecisionPlayerTwo"]={["Precision II"]={["enDescription"]="Supports Persistent Buff Skills, causing you to gain increased Accuracy while the Skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами. Пока активно, усиленные умения дают вам повышенную меткость.",["name"]="Точность II"}},
["SupportProfanityPlayer"]={["Profanity I"]={["enDescription"]="Supports Skills you use yourself. Supported Skills consume a Corpse on use, dealing more Chaos Damage if they do.",["description"]="Усиливает умения, которые вы используете самостоятельно. Усиленные умения поглощают труп при использовании, нанося при этом больше урона хаосом.",["name"]="Нечестивость I"}},
["SupportProfanityPlayerTwo"]={["Profanity II"]={["enDescription"]="Supports Skills you use yourself. Supported Skills consume many Corpses on use, dealing more Chaos Damage per Corpse consumed.",["description"]="Усиливает умения, которые вы используете самостоятельно. Усиленные умения поглощают много трупов при использовании, нанося больше урона хаосом за каждый поглощённый труп.",["name"]="Нечестивость II"}},
["SupportProjectileAccelerationPlayer"]={["Projectile Acceleration I"]={["enDescription"]="Supports Projectile skills, making those Projectiles travel faster.",["description"]="Усиливает умения снарядов. Снаряды усиленных умений летят быстрее.",["name"]="Ускорение cнарядов I"}},
["SupportProjectileAccelerationPlayerThree"]={["Projectile Acceleration III"]={["enDescription"]="Supports Projectile skills, making those Projectiles travel faster, and causing increases and reductions to Projectile speed to also apply to Damage.",["description"]="Усиливает умения снарядов. Снаряды усиленных умений летят быстрее. Увеличения и уменьшения скорости снарядов также влияют на урон.",["name"]="Ускорение cнарядов III"}},
["SupportProjectileAccelerationPlayerTwo"]={["Projectile Acceleration II"]={["enDescription"]="Supports Projectile skills, making those Projectiles travel faster, and granting them a chance to Pierce Enemies.",["description"]="Усиливает умения снарядов. Снаряды усиленных умений летят быстрее и с некоторым шансом могут пронзить врагов.",["name"]="Ускорение cнарядов II"}},
["SupportProjectileDecelerationPlayer"]={["Projectile Deceleration I"]={["enDescription"]="Supports Projectile skills, making those Projectiles travel more slowly.",["description"]="Усиливает умения снарядов. Снаряды усиленных умений летят медленнее.",["name"]="Замедление снарядов I"}},
["SupportProjectileDecelerationPlayerTwo"]={["Projectile Deceleration II"]={["enDescription"]="Supports Projectile skills, making those Projectiles travel more slowly.",["description"]="Усиливает умения снарядов. Снаряды усиленных умений летят медленнее.",["name"]="Замедление снарядов II"}},
["SupportPrototypeSeventeenPlayer"]={["Prototype Seventeen"]={["enDescription"]="Supports non-Channelling skill you use yourself that Hits enemies, causing it to gain Critical Hit chance based on Rage, but also remove all Rage upon Critically Hitting.",["description"]="Усиливает не поддерживаемые наносящие удары умения, которые вы используете самостоятельно. Усиленные умения получают шанс критического попадания на основе свирепости, но удаляют всю свирепость при критическом попадании.",["name"]="Прототип семнадцать"}},
["SupportPunchThroughPlayer"]={["Punch Through"]={["enDescription"]="Supports Melee Attack Skills. Supported Skills apply Easy Target when Knocking Back Enemies, causing the next Projectile Attack Hit they take to deal increased Damage.",["description"]="Усиливает умения атак ближнего боя. Усиленные умения накладывают Лёгкую мишень при отбрасывании врагов, вследствие чего следующий полученный ими удар атакой снарядами нанесёт увеличенный урон.",["name"]="Прорыв"}},
["SupportPursuitPlayer"]={["Pursuit I"]={["enDescription"]="Supports Melee Attacks. Supported Skills deal more Melee damage if you have struck with a Projectile Attack Hit in the last eight seconds, but cannot themselves deal Projectile Damage.",["description"]="Усиливает атаки ближнего боя. Усиленные умения наносят больше урона в ближнем бою, если за последние 8 секунд вы наносили удар атакой снарядами, но сами не могут наносить урон снарядами.",["name"]="Погоня I"}},
["SupportPursuitPlayerThree"]={["Pursuit III"]={["enDescription"]="Supports Melee Attacks. Supported Skills deal more Melee damage if you have struck with a Projectile Attack Hit in the last two seconds, but cannot themselves deal Projectile Damage.",["description"]="Усиливает атаки ближнего боя. Усиленные умения наносят больше урона в ближнем бою, если за последние 2 секунды вы наносили удар атакой снарядами, но сами не могут наносить урон снарядами.",["name"]="Погоня III"}},
["SupportPursuitPlayerTwo"]={["Pursuit II"]={["enDescription"]="Supports Melee Attacks. Supported Skills deal more Melee damage if you have struck with a Projectile Attack Hit in the last eight seconds, but cannot themselves deal Projectile Damage.",["description"]="Усиливает атаки ближнего боя. Усиленные умения наносят больше урона в ближнем бою, если за последние 8 секунд вы наносили удар атакой снарядами, но сами не могут наносить урон снарядами.",["name"]="Погоня II"}},
["SupportQuillburstPlayer"]={["Quill Burst"]={["enDescription"]="Supports Melee Attack Skills. Supported Skills trigger Quill Burst, which deals your Thorns Damage in an Area around the target struck. Quill Burst can only be triggered on Hit after you've\nRetaliated with Thorns Damage.",["description"]="Усиливает умения атак ближнего боя. Усиленные умения вызывают срабатывание Взрыва игл, который наносит ваш урон от шипов по области вокруг поражённой цели. Взрыв игл может сработать\nтолько при нанесении удара после того, как вы нанесли ответный урон шипами.",["name"]="Взрыв игл"}},
["SupportRageFountainPlayer"]={["Font of Rage"]={["enDescription"]="Supports Skills which create Totems. Totems created by supported Skills generate a Font of Rage which will Leech Rage to Allies within it.",["description"]="Усиливает умения, создающие тотемы. Тотемы, созданные усиленными умениями, создают купель свирепости, которая восстанавливает свирепость от похищения союзникам в ней.",["name"]="Купель свирепости"}},
["SupportRagePlayer"]={["Rage I"]={["enDescription"]="Supports Melee Attacks, causing them to grant Rage on Hit.",["description"]="Усиливает атаки ближнего боя. Усиленные умения даруют свирепость при нанесении удара.",["name"]="Свирепость I"}},
["SupportRagePlayerThree"]={["Rage III"]={["enDescription"]="Supports Melee Attacks, causing them to grant Rage on Hit. Supported Skills have signficantly higher Attack speed while you or supported minion are not at maximum Rage.",["description"]="Усиливает атаки ближнего боя. Усиленные умения даруют свирепость при нанесении удара. Усиленные умения имеют существенно более высокую скорость атаки, пока у вас или усиленного приспешника не максимум свирепости.",["name"]="Свирепость III"}},
["SupportRagePlayerTwo"]={["Rage II"]={["enDescription"]="Supports Melee Attacks, causing them to grant Rage on Hit.",["description"]="Усиливает атаки ближнего боя. Усиленные умения даруют свирепость при нанесении удара.",["name"]="Свирепость II"}},
["SupportRageforgedPlayer"]={["Rageforged I"]={["enDescription"]="Supports any damaging skill that you use or Trigger yourself, causing it to spend Rage to deal more damage. If you don't have enough Rage to spend, the damage bonus will not apply.",["description"]="Усиливает любое наносящее урон умение, которое вы используете самостоятельно или сами вызываете его срабатывание. Усиленное умение расходует свирепость и наносит больше урона. Если у вас недостаточно свирепости для расхода, прибавка к урону не действует.",["name"]="Разъярение I"}},
["SupportRageforgedPlayerTwo"]={["Rageforged II"]={["enDescription"]="Supports any damaging skill that you use or Trigger yourself, causing it to spend Rage to deal more damage, with a chance to skip spending Rage while still benefitting as though it had. If you don't have enough Rage to spend, the damage bonus will not apply.",["description"]="Усиливает любое наносящее урон умение, которое вы используете самостоятельно или сами вызываете его срабатывание. Усиленное умение расходует свирепость и наносит больше урона, имея при этом шанс не израсходовать свирепость при сохранении всех преимуществ её расхода. Если у вас недостаточно свирепости для расхода, прибавка к урону не действует.",["name"]="Разъярение II"}},
["SupportRagingCryPlayer"]={["Raging Cry"]={["enDescription"]="Supports Warcry skills, causing them to grant you Rage on use depending on counted monster Power.",["description"]="Усиливает умения боевых кличей. Усиленные умения при использовании даруют вам свирепость в зависимости от подсчитанного уровня угрозы монстров.",["name"]="Свирепый клич"}},
["SupportRakiatasFlowPlayer"]={["Rakiata's Flow"]={["enDescription"]="Supports Skills that can cause Damaging Hits, causing those Hits to treat Enemy Elemental Resistances as inverted.",["description"]="Усиливает умения, которые могут наносить урон ударами. Удары усиленных умений учитывают сопротивления стихиям врагов как противоположные.",["name"]="Поток Ракиаты"}},
["SupportRallyPlayer"]={["Rally"]={["enDescription"]="Supports Melee Attacks you use yourself. Supported Skills Consume all Endurance Charge on use, causing you to restore a percentage of your maximum Life for each Charge Consumed. Cannot Support Skills which consume Endurance Charges.",["description"]="Усиливает атаки ближнего боя, которые вы используете самостоятельно. Усиленные умения при использовании поглощают все заряды выносливости, восстанавливая вам часть здоровья за каждый поглощённый заряд. Не может усиливать умения, поглощающие заряды выносливости.",["name"]="Ободрение"}},
["SupportRapidAttacksPlayer"]={["Rapid Attacks I"]={["enDescription"]="Supports Attacks, causing them to Attack faster.",["description"]="Усиливает атаки. Усиленные умения атакуют быстрее.",["name"]="Быстрые атаки I"}},
["SupportRapidAttacksPlayerThree"]={["Rapid Attacks III"]={["enDescription"]="Supports Attacks, causing them to Attack faster at the cost of Damage.",["description"]="Усиливает атаки. Усиленные умения атакуют быстрее ценой сниженного урона.",["name"]="Быстрые атаки III"}},
["SupportRapidAttacksPlayerTwo"]={["Rapid Attacks II"]={["enDescription"]="Supports Attacks, causing them to Attack faster.",["description"]="Усиливает атаки. Усиленные умения атакуют быстрее.",["name"]="Быстрые атаки II"}},
["SupportRapidCastingPlayer"]={["Rapid Casting I"]={["enDescription"]="Supports Spells, causing them to cast faster.",["description"]="Усиливает чары. Усиленные умения сотворяют чары быстрее.",["name"]="Быстрое сотворение I"}},
["SupportRapidCastingPlayerThree"]={["Rapid Casting III"]={["enDescription"]="Supports Spells, causing them to cast faster for each different Spell you've cast in the last eight seconds.",["description"]="Усиливает чары. Усиленные умения сотворяют чары быстрее за каждые отличные от других недавно сотворённые вами чары.",["name"]="Быстрое сотворение III"}},
["SupportRapidCastingPlayerTwo"]={["Rapid Casting II"]={["enDescription"]="Supports Spells, causing them to cast faster.",["description"]="Усиливает чары. Усиленные умения сотворяют чары быстрее.",["name"]="Быстрое сотворение II"}},
["SupportRearmPlayer"]={["Rearm I"]={["enDescription"]="Supports Skills which create Hazards. Hazards created by Supported Skills have a chance to be rearmed a short duration after triggering.",["description"]="Усиливает умения, создающие помехи. Помехи, созданные усиленными умениями, с некоторым шансом могут стать активными вновь спустя короткое время после срабатывания.",["name"]="Повторное взведение I"}},
["SupportRearmPlayerTwo"]={["Rearm II"]={["enDescription"]="Supports Skills which create Hazards. Hazards created by Supported Skills have a chance to be rearmed a short duration after triggering.",["description"]="Усиливает умения, создающие помехи. Помехи, созданные усиленными умениями, с некоторым шансом могут стать активными вновь спустя короткое время после срабатывания.",["name"]="Повторное взведение II"}},
["SupportRefractionPlayer"]={["Refraction I"]={["enDescription"]="Supports Banner Skills, causing those affected by Auras they create to gain Refractive Plating, a Buff which grants Deflection Rating and causes Armour to partially apply to Elemental Hit Damage.",["description"]="Усиливает умения знамён, даруя тем, на кого действуют созданные ими ауры, Преломляющие пластины – положительный эффект, дарующий отклонение и заставляющий броню частично действовать на урон от стихийных ударов.",["name"]="Преломление I"}},
["SupportRefractionPlayerThree"]={["Refraction III"]={["enDescription"]="Supports Banner Skills, causing Enemies within their area to gain Refractive Dissolution, a Debuff which lowers Elemental Resistances.",["description"]="Усиливает умения знамён, даруя врагам в области их действия Преломляющий распад – отрицательный эффект, снижающий сопротивления стихиям.",["name"]="Преломление III"}},
["SupportRefractionPlayerTwo"]={["Refraction II"]={["enDescription"]="Supports Banner Skills, causing those affected by Auras they create to gain Refractive Plating, a Buff which grants Deflection Rating and causes Armour to partially apply to Elemental Hit Damage.",["description"]="Усиливает умения знамён, даруя тем, на кого действуют созданные ими ауры, Преломляющие пластины – положительный эффект, дарующий отклонение и заставляющий броню частично действовать на урон от стихийных ударов.",["name"]="Преломление II"}},
["SupportReinforcedTotemsPlayer"]={["Reinforced Totems I"]={["enDescription"]="Supports Skills which create Totems. Totems created by Supported Skills have additional Elemental Resistances.",["description"]="Усиливает умения, создающие тотемы. Тотемы, созданные усиленными умениями, получают дополнительные сопротивления стихиям.",["name"]="Укреплённые тотемы I"}},
["SupportReinforcedTotemsPlayerTwo"]={["Reinforced Totems II"]={["enDescription"]="Supports Skills which create Totems. Totems created by Supported Skills have additional Elemental Resistances.",["description"]="Усиливает умения, создающие тотемы. Тотемы, созданные усиленными умениями, получают дополнительные сопротивления стихиям.",["name"]="Укреплённые тотемы II"}},
["SupportRelentlessRagePlayer"]={["Relentless Rage"]={["enDescription"]="Supports Skills you use yourself. On spending Rage with any skill you will gain a Buff. Using Supported Skills consumes this Buff to grant you Rage.",["description"]="Усиливает умения, которые вы используете самостоятельно. При трате свирепости любым умением вы получите положительный эффект. Использование усиленных умений поглощает этот положительный эффект и дарует вам свирепость.",["name"]="Неослабная свирепость"}},
["SupportRendingApexPlayer"]={["Rending Apex"]={["enDescription"]="Supports Strikes that perform a Final Strike at the end of a combination of attacks, causing the Final Strike to Break Armour based on a portion of Attack damage dealt.",["description"]="Усиливает удары, наносящие завершающий удар в конце комбинации атак, позволяя завершающему удару разрушать броню на основе части нанесённого урона от атак.",["name"]="Разрушительный финал"}},
["SupportRetaliatePlayer"]={["Retaliate I"]={["enDescription"]="Supports Melee Attack Skills you use yourself. Supported Skills gain much more damage the closer you are to being Heavily Stunned.",["description"]="Усиливает умения атак ближнего боя, которые вы используете самостоятельно. Чем ближе вы находитесь к сильному оглушению, тем больше урона наносят усиленные умения.",["name"]="Отмщение I"}},
["SupportRetaliatePlayerTwo"]={["Retaliate II"]={["enDescription"]="Supports Melee Attack Skills you use yourself. Supported Skills gain much more damage and are more capable of Stunning Enemies the closer you are to being Heavily Stunned.",["description"]="Усиливает умения атак ближнего боя, которые вы используете самостоятельно. Чем ближе вы находитесь к сильному оглушению, тем больше урона наносят усиленные умения и тем лучше они оглушают.",["name"]="Отмщение II"}},
["SupportRetreatPlayer"]={["Retreat I"]={["enDescription"]="Supports Skills which create Projectiles. Supported Skills deal more damage with Projectiles if you have struck with a Melee Hit in the last eight seconds, but cannot themselves deal Melee Damage.",["description"]="Усиливает умения, создающие снаряды. Усиленные умения наносят больше урона снарядами, если за последние 8 секунд вы наносили удар в ближнем бою, но сами не могут наносить урон ближнего боя.",["name"]="Отступление I"}},
["SupportRetreatPlayerThree"]={["Retreat III"]={["enDescription"]="Supports Skills which create Projectiles. Supported Skills deal more damage with Projectiles if you have struck with a Melee Hit in the last two seconds, but cannot themselves deal Melee Damage.",["description"]="Усиливает умения, создающие снаряды. Усиленные умения наносят больше урона снарядами, если за последние 2 секунды вы наносили удар в ближнем бою, но сами не могут наносить урон ближнего боя.",["name"]="Отступление III"}},
["SupportRetreatPlayerTwo"]={["Retreat II"]={["enDescription"]="Supports Skills which create Projectiles. Supported Skills deal more damage with Projectiles if you have struck with a Melee Hit in the last eight seconds, but cannot themselves deal Melee Damage.",["description"]="Усиливает умения, создающие снаряды. Усиленные умения наносят больше урона снарядами, если за последние 8 секунд вы наносили удар в ближнем бою, но сами не могут наносить урон ближнего боя.",["name"]="Отступление II"}},
["SupportReveberatePlayer"]={["Reverberate"]={["enDescription"]="Supports Slam Skills. Supported Skills that have a chance to Aftershock have increased chance to cause Aftershocks the longer their Attack time.",["description"]="Усиливает умения мощных ударов. Шанс вызвать остаточные волны способными на это усиленными умениями увеличивается соразмерно их времени атаки.",["name"]="Реверберация"}},
["SupportRicochetPlayer"]={["Ricochet I"]={["enDescription"]="Supports any Skill which creates Projectiles, giving those Projectiles a chance to Chain when impacting terrain.",["description"]="Усиливает любое умение, создающее снаряды. Снаряды усиленных умений имеют шанс ударить по цепи при столкновении с ландшафтом.",["name"]="Рикошет I"}},
["SupportRicochetPlayerThree"]={["Ricochet III"]={["enDescription"]="Supports any Skill which creates Projectiles, causing those Projectiles to Chain when impacting terrain, at the cost of any additional Projectiles, as well as causing them to always Pierce.",["description"]="Усиливает любое умение, создающее снаряды. Снаряды усиленных умений наносят удар по цепи при столкновении с ландшафтом, а также всегда пронзают, ценой любых дополнительных снарядов.",["name"]="Рикошет III"}},
["SupportRicochetPlayerTwo"]={["Ricochet II"]={["enDescription"]="Supports any Skill which creates Projectiles, giving those Projectiles a chance to Chain when impacting terrain.",["description"]="Усиливает любое умение, создающее снаряды. Снаряды усиленных умений имеют шанс ударить по цепи при столкновении с ландшафтом.",["name"]="Рикошет II"}},
["SupportRigwaldsFerocityPlayer"]={["Rigwald's Ferocity"]={["enDescription"]="Supports Attack skills, granting them Attack Speed at the cost of Damage or Damage at the cost of Attack Speed depending on Weapon Set they are used in. Does not modify skills used by Minions.",["description"]="Усиливает умения атак, даруя им скорость атаки ценой урона или урон ценой скорости атаки, в зависимости от набора оружия, с которым они используются. Не может усиливать умения, используемые приспешниками.",["name"]="Свирепость Ригвальда"}},
["SupportRimePlayer"]={["Rime"]={["enDescription"]="Supports Skills which create Ground Surfaces, causing Enemies Chilled by those Surfaces to be more easily Frozen, but at the cost of some Chill magnitude.",["description"]="Усиливает умения, создающие наземные эффекты. Врагов, охлаждённых этими эффектами, становится легче заморозить, но ценой некоторой величины охлаждения.",["name"]="Стужа"}},
["SupportRipPlayer"]={["Rip"]={["enDescription"]="Supports Melee Attack Skills you use or Trigger yourself. Killing Blows with Supported Skills on Bleeding enemies create a Blood Remnant. Blood Remnants increase your Life regeneration rate for a short while after being collected.",["description"]="Усиливает умения атак ближнего боя, которые вы используете самостоятельно или сами вызываете их срабатывание. Смертельные удары усиленными умениями по истекающим кровью врагам создают сгусток крови. Сгустки крови кратковременно увеличивают вашу скорость регенерации здоровья, если их подобрать.",["name"]="Вырывание"}},
["SupportRitualisticCursePlayer"]={["Ritualistic Curse"]={["enDescription"]="Supports Curse skills, causing them to cover a larger area but take longer to Curse enemies.",["description"]="Усиливает умения проклятий. Усиленные умения покрывают большую область, но проклинают врагов дольше.",["name"]="Ритуальное проклятие"}},
["SupportRomirasRequitalPlayer"]={["Romira's Requital"]={["enDescription"]="Supports Skills that create Companions which can be damaged. Minions created by Supported Skills take a portion of Hit Damage you would otherwise have taken, but have lowered maximum Life. A percentage of Damage taken this way is Recouped by you as Life.",["description"]="Усиливает умения, создающие компаньонов, которым можно нанести урон. Приспешники, созданные усиленными умениями, получают часть урона от ударов вместо вас, но имеют сниженный максимум здоровья. Часть полученного таким образом урона вы восполняете в виде здоровья.",["name"]="Расплата Ромиры"}},
["SupportRuneforgedBladesPlayer"]={["Runeforged Blades"]={["enDescription"]="Supports Attacks you use yourself, causing them to Consume Fully Broken Armour on enemies to fire a nova of runic Projectiles at the cost of Runic Ward. The Projectiles cannot Hit the enemy from which they originated. Cannot support skills that Consume Broken Armour.",["description"]="Усиливает атаки, которые вы используете самостоятельно. Усиленные умения поглощают полностью разрушенную броню на врагах, выпуская кольцо рунических снарядов ценой рунического барьера. Снаряды не могут поразить врага, из которого появились. Не может усиливать умения, поглощающие разрушенную броню.",["name"]="Руннокованые клинки"}},
["SupportRunicExtractionPlayer"]={["Runic Extraction"]={["enDescription"]="Supports any Skill that deals damage. Enemies you kill with supported Skills have a chance to drop a Verisium Infusion Remnant.",["description"]="Усиливает любое умение, наносящее урон. Враги, которых вы убиваете усиленными умениями, с некоторым шансом могут оставить насыщающий веризием сгусток.",["name"]="Рунное извлечение"}},
["SupportRunicInfusionPlayer"]={["Runic Infusion"]={["enDescription"]="Supports Attacks you use or Trigger yourself, causing them to cost Runic Ward to use but deal additional Physical damage based on their Runic Ward cost. Cannot Support Channelling Skills, Sustained Skills, or Skills without a cost.",["description"]="Усиливает атаки, которые вы используете самостоятельно или сами вызываете их срабатывание. Усиленные умения при использовании расходуют рунический барьер, но наносят дополнительный физический урон на основе расходуемого ими рунического барьера. Не может усиливать поддерживаемые умения, непрерывные умения и умения, не имеющие расхода.",["name"]="Рунное насыщение"}},
["SupportRupturePlayer"]={["Rupture"]={["enDescription"]="Supports skills that Hit Enemies. Supported skills Aggravate Bleeding on Hitting Heavily Stunned Enemies.",["description"]="Усиливает умения, наносящие удары по врагам. Усиленные умения усугубляют кровотечения при нанесении удара по сильно оглушённым врагам.",["name"]="Разрывание"}},
["SupportRustedSpikesPlayer"]={["Rusted Spikes"]={["enDescription"]="Supports Skills which deal Damage with Hits. When Supported Skills Pin an Enemy, they also Aggravate Bleeding on that Enemy.",["description"]="Усиливает умения, которые могут наносить урон ударами. Когда усиленные умения пригвождают врага, они также усугубляют кровотечение на этом враге.",["name"]="Ржавые шипы"}},
["SupportSacrificalOfferingPlayer"]={["Sacrificial Offering"]={["enDescription"]="Supports Offering Skills. Supported Skills Sacrifice a portion of your life on use, but deal much more damage and have more powerful Buffs in return.",["description"]="Усиливает умения подношений. Усиленные умения жертвуют частью вашего здоровья при использовании, но взамен наносят гораздо больше урона и дают более мощные положительные эффекты.",["name"]="Жертвенное подношение"}},
["SupportSacrificialLambPlayer"]={["Sacrificial Lamb I"]={["enDescription"]="Supports Skills which create Minions, causing your Skills which can target Minions to prioritise targeting Minions from the Supported Skill before your other Minions where possible.",["description"]="Усиливает умения, создающие приспешников. Ваши умения, способные выбирать целью приспешников, отдают приоритет приспешникам от усиленного умения вместо других ваших приспешников, если возможно.",["name"]="Агнец на заклание I"}},
["SupportSacrificialLambPlayerTwo"]={["Sacrificial Lamb II"]={["enDescription"]="Supports Skills which create Minions, causing your Skills which can target Minions to prioritise targeting Minions from the Supported Skill before your other Minions where possible, as well as causing them to always be considered Detonatable.",["description"]="Усиливает умения, создающие приспешников. Ваши умения, способные выбирать целью приспешников, отдают приоритет приспешникам от усиленного умения вместо других ваших приспешников, если возможно. Кроме того, эти приспешники всегда считаются взрываемыми.",["name"]="Агнец на заклание II"}},
["SupportSalvoPlayer"]={["Salvo"]={["enDescription"]="Supports Attack Skills you use yourself which fire Projectiles, Sealing them over time. The Seals are broken when used, causing additional Projectiles to be fired. Projectiles from Supported Skills are fired in random directions. Cannot Support Skills which require Combo, have a Cooldown or which already gain Seals.",["description"]="Усиливает самостоятельно используемые вами умения атак, выпускающие снаряды, постепенно запечатывая их. При использовании печати разбиваются, выпуская дополнительные снаряды. Cнаряды от усиленных умений выпускаются в случайных направлениях. Не может усиливать умения, требующие Комбо, имеющие время перезарядки или уже накапливающие печати.",["name"]="Шквал"}},
["SupportScouringFlamePlayer"]={["Scouring Flame"]={["enDescription"]="Supports any skill that Hits enemies, causing inflicted Ignites to deal more damage but the skill to gain a Runic Ward cost.",["description"]="Усиливает любое умение, наносящее удары по врагам, заставляя наложенные поджоги наносить больше урона, но усиленные умения начинают расходовать рунический барьер.",["name"]="Очищающее пламя"}},
["SupportSecondWindPlayer"]={["Second Wind I"]={["enDescription"]="Supports Skills which have a cooldown, giving them extra uses of that cooldown. Cannot support Meta, instant, or Triggered Skills, and cannot modify the Skills of Minions.",["description"]="Усиливает умения с перезарядкой, добавляя им дополнительные использования.\nНе может усиливать мета-умения, мгновенные и срабатывающие умения или умения приспешников.",["name"]="Второе дыхание I"}},
["SupportSecondWindPlayerThree"]={["Second Wind III"]={["enDescription"]="Supports Skills which have a cooldown, giving them extra uses of that cooldown and causing them to recover your Life when a Skill is used and goes on cooldown. Cannot support Meta, instant, or Triggered Skills, and cannot modify the Skills of Minions.",["description"]="Усиливает умения с перезарядкой, добавляя им дополнительные использования. При трате доступного использования усиленные умения восстанавливают здоровье.\nНе может усиливать мета-умения, мгновенные и срабатывающие умения или умения приспешников.",["name"]="Второе дыхание III"}},
["SupportSecondWindPlayerTwo"]={["Second Wind II"]={["enDescription"]="Supports Skills which have a cooldown, giving them extra uses of that cooldown. Cannot support Meta, instant, or Triggered Skills, and cannot modify the Skills of Minions.",["description"]="Усиливает умения с перезарядкой, добавляя им дополнительные использования.\nНе может усиливать мета-умения, мгновенные и срабатывающие умения или умения приспешников.",["name"]="Второе дыхание II"}},
["SupportSeeRedPlayer"]={["See Red"]={["enDescription"]="Supports Attack Skills. Bleeding inflicted with Supported Skills lasts significantly longer, but enemies you inflict Bleeding onto with Supported Skills will move and Attack faster.",["description"]="Усиливает умения атак. Наложенное усиленными умениями кровотечение длится значительно дольше, но враги, на которых вы наложите кровотечение усиленными умениями, будут передвигаться и атаковать быстрее.",["name"]="Красный цвет"}},
["SupportSelflessRemnantsPlayer"]={["Selfless Remnants"]={["enDescription"]="Supports Skills that generate Remnants, causing those Remnants to affect Allies in your Presence when collected instead of you.",["description"]="Усиливает умения, создающие сгустки, и заставляет эти сгустки при подборе действовать на союзников в вашем присутствии вместо вас.",["name"]="Беззаветные останки"}},
["SupportSeraphsHeartPlayer"]={["Seraph's Heart"]={["enDescription"]="Supports Persistent Buff Skills, providing a chance for enemies to calculate their Hits as though your Resistances were 90% while the skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами, давая шанс рассчитать удары врагов как если бы ваши сопротивления были равны 90%, пока умение активно.",["name"]="Сердце серафима"}},
["SupportShockConductionPlayer"]={["Shock Conduction"]={["enDescription"]="Supports any skill that Hits enemies, giving it a chance to also Shock nearby enemies when you Shock an enemy.",["description"]="Усиливает любое умение, наносящее удары по врагам, даруя ему шанс также наложить шок на ближайших врагов, когда вы накладываете шок на врага.",["name"]="Проводник шока"}},
["SupportShockConductionPlayerTwo"]={["Shock Conduction II"]={["enDescription"]="Supports any skill that Hits enemies, giving it a chance to also Shock nearby enemies when you Shock an enemy. Always Shocks enemies which are Drenched.",["description"]="Усиливает любое умение, наносящее удары по врагам, даруя ему шанс также наложить шок на ближайших врагов, когда вы накладываете шок на врага. Всегда накладывает шок на промокших врагов.",["name"]="Проводник шока II"}},
["SupportShockManaRegenerationPlayer"]={["Enervation"]={["enDescription"]="Supports any skill that Hits enemies, causing you to regenerate mana on shocking an enemy. Cannot support skills which create Minions, or skills used by Totems or Traps.",["description"]="Усиливает любое умение, наносящее удары по врагам, регенерируя вашу ману при наложении шока на врага. Не может усиливать умения, создающие приспешников, или умения, используемые тотемами или ловушками.",["name"]="Изматывание"}},
["SupportShockPlayer"]={["Shock"]={["enDescription"]="Supports any skill that Hits enemies, making it more likely to Shock.",["description"]="Усиливает любое умение, наносящее удары по врагам, и увеличивает его шанс наложения шока.",["name"]="Шок"}},
["SupportShockingLeapPlayer"]={["Shocking Leap"]={["enDescription"]="Supports Skills that leap into the air and deal damage, causing them to create Shocked Ground the first time they Critically Hit an enemy.",["description"]="Усиливает умения с прыжком в воздух, наносящие урон. Усиленные умения создают заряженную землю при первом критическом попадании по врагу.",["name"]="Шокирующий прыжок"}},
["SupportShockingRiftPlayer"]={["Electromagnetism"]={["enDescription"]="Supports Skills that Hit enemies. When Supported Skills Shock an enemy that is nearby other Shocked enemies, trigger Electromagnetism, sucking in nearby enemies, Hindering them, and dealing Lightning damage at an interval.",["description"]="Усиливает умения, наносящие удары по врагам. Когда усиленные умения накладывают шок на врага, который находится вблизи других врагов под действием шока, вызывает срабатывание Электромагнетизма, притягивая ближайших врагов, сковывая их и нанося периодический урон от молнии.",["name"]="Электромагнетизм"}},
["SupportShortFusePlayer"]={["Short Fuse I"]={["enDescription"]="Supports Skills which Detonate after some amount of time has elapsed, shortening the time before Detonation.",["description"]="Усиливает умения, детонирующие спустя некоторое время, сокращая время до детонации.",["name"]="Короткий запал I"}},
["SupportShortFusePlayerTwo"]={["Short Fuse II"]={["enDescription"]="Supports Skills which Detonate after some amount of time has elapsed, massively shortening the time before Detonation at the cost of Damage.",["description"]="Усиливает умения, детонирующие спустя некоторое время, резко сокращая время до детонации ценой урона.",["name"]="Короткий запал II"}},
["SupportSkitteringStonePlayer"]={["Skittering Stone I"]={["enDescription"]="Supports Skills which create shatterable earthen objects. After killing enough Enemies in range of these objects, they will shatter, releasing skittering stone Minions.",["description"]="Усиливает умения, создающие разбиваемые земляные объекты. После убийства достаточного числа врагов в радиусе этих объектов они разобьются, выпустив приспешников – ходячие камни.",["name"]="Ходячий камень I"}},
["SupportSkitteringStonePlayerTwo"]={["Skittering Stone II"]={["enDescription"]="Supports Skills which create shatterable earthen objects. After killing enough Enemies in range of these objects, they will shatter, releasing skittering stone Minions.",["description"]="Усиливает умения, создающие разбиваемые земляные объекты. После убийства достаточного числа врагов в радиусе этих объектов они разобьются, выпустив приспешников – ходячие камни.",["name"]="Ходячий камень II"}},
["SupportSlamAftershocksPlayer"]={["Tectonic Slams"]={["enDescription"]="Supports Slams you use yourself, causing them to create simultaneous Aftershocks behind the Slam, but lowering Aftershock damage and area of effect with Supported Skills. Cannot Support Skills which create Fissures.",["description"]="Усиливает мощные удары, которые вы используете самостоятельно, заставляя их одновременно создавать остаточные волны позади мощного удара, но урон и область действия остаточных волн от усиленных умений снижаются. Не может усиливать умения, создающие расселины.",["name"]="Тектонические удары"}},
["SupportSlowPotencyPlayer"]={["Slow Potency"]={["enDescription"]="Supports any skill, causing inflicted Slows to be more powerful.",["description"]="Усиливает любое умение, делая накладываемые им замедления эффективнее.",["name"]="Сила замедления"}},
["SupportSoulbreakerPlayer"]={["Soulbreaker"]={["enDescription"]="Supports skills you use yourself, causing them to Trigger a Chaos Damage nova when breaking Enemy Energy Shield.",["description"]="Усиливает умения, которые вы используете самостоятельно. Усиленные умения вызывают срабатывание кольца урона хаосом при уничтожении вражеского энергетического щита.",["name"]="Разрушитель душ"}},
["SupportSparPlayer"]={["Spar"]={["enDescription"]="Supports Melee Attack Skills. Supported Skills are more capable of Stunning Enemies the closer you are to being Heavily Stunned.",["description"]="Усиливает умения атак ближнего боя. Чем ближе вы находитесь к сильному оглушению, тем лучше усиленные умения оглушают врагов.",["name"]="Спарринг"}},
["SupportSpectralPalmPlayer"]={["DNT-UNUSED Spectral Palm"]={["enDescription"]="DNT-UNUSED Spectral Palm",["description"]="DNT-UNUSED Spectral Palm",["name"]="DNT-UNUSED Spectral Palm"}},
["SupportSpectralVolleyPlayer"]={["Spectral Volley"]={["enDescription"]="Supports Bow or Spear Projectile Attacks you use yourself. Supported Skills deal lower damage initially, but generate Spectral Projectiles, which deal more damage when they fire. Spectral Projectiles linger and will fire a short duration after no new Spectral Projectiles have been created. Cannot support Channelling Skills, Leaping skills, or skills which rain Projectiles from above.",["description"]="Усиливает атаки снарядами луком или копьём, которые вы используете самостоятельно. Усиленные умения наносят изначально сниженный урон, но создают призрачные снаряды, которые, будучи выпущенными, наносят больше урона. Призрачные снаряды существуют некоторое время и будут выпущены вскоре после того, как перестанут создаваться новые призрачные снаряды. Не может усиливать поддерживаемые умения, умения прыжка и умения, создающие дождь из снарядов.",["name"]="Призрачный залп"}},
["SupportSpellCascadePlayer"]={["Spell Cascade"]={["enDescription"]="Supports Cascadable Spells, causing them to Cascade to either side of the target area, along a randomly chosen axis.",["description"]="Усиливает каскадные чары, заставляя их отражаться эхом по каждую сторону от целевой области, вдоль случайно выбранной оси.",["name"]="Каскад чар"}},
["SupportSpellEchoPlayer"]={["Spell Echo"]={["enDescription"]="Supports Cascadable Spells you use yourself. Supported Spells Echo.",["description"]="Усиливает каскадные чары, которые вы используете самостоятельно. Усиленные чары отражаются эхом.",["name"]="Эхо магии"}},
["SupportSpiralProjectilesPlayer"]={["DNT-UNUSED Spiral Projectiles I"]={["enDescription"]="DNT-UNUSED Spiral Proj",["description"]="DNT-UNUSED Spiral Proj",["name"]="Спиральные снаряды I"}},
["SupportSplinteringTotemPlayer"]={["Splinter Totem I"]={["enDescription"]="Supports Skills which create Totems, preventing having more than one active Totem but causing that Totem to splinter into smaller versions of itself after it uses an Attack or Spell, with each Totem becoming less effective. Each splintered Totem can further splinter, up to a maximum. Does not Support Skills used by Minions. Only one Totem can be splintering at a time.",["description"]="Усиливает умения, создающие тотемы, не позволяя иметь более одного активного тотема, но заставляя этот тотем расщепляться на собственные копии меньшего размера после того, как он использует атаку или чары. При этом каждый тотем становится менее эффективным. Каждый отделившийся тотем может расщепиться дальше, вплоть до максимума. Не усиливает умения, используемые приспешниками. Одновременно может расщепляться только один тотем.",["name"]="Расщепляющийся тотем I"}},
["SupportSplinteringTotemPlayerTwo"]={["Splinter Totem II"]={["enDescription"]="Supports Skills which create Totems, preventing having more than one active Totem but causing that Totem to splinter into smaller versions of itself after it uses an Attack or Spell, with each Totem becoming less effective. Each splintered Totem can further splinter, up to a maximum. Does not Support Skills used by Minions. Only one Totem can be splintering at a time.",["description"]="Усиливает умения, создающие тотемы, не позволяя иметь более одного активного тотема, но заставляя этот тотем расщепляться на собственные копии меньшего размера после того, как он использует атаку или чары. При этом каждый тотем становится менее эффективным. Каждый отделившийся тотем может расщепиться дальше, вплоть до максимума. Не усиливает умения, используемые приспешниками. Одновременно может расщепляться только один тотем.",["name"]="Расщепляющийся тотем II"}},
["SupportSpreadingFrostPlayer"]={["Spreading Frost"]={["enDescription"]="Supports any skill that hits enemies, causing them to Chill enemies near enemies they Freeze.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения охлаждают врагов рядом с врагами, которых они замораживают.",["name"]="Разгул стужи"}},
["SupportStaticShocksPlayer"]={["Static Shocks"]={["enDescription"]="Supports Skills which can Hit enemies. Shocking an enemy with Hits from Supported Skills Triggers Static Shocks, causing that enemy to become a source of Lightning damage sending pulses towards nearby enemies.",["description"]="Усиливает умения, которые могут наносить удары по врагам. Наложение шока на врага ударами усиленных умений вызывает срабатывание Статического шока, делая этого противника источником урона от молнии, посылающего разряды в других ближайших врагов.",["name"]="Статический шок"}},
["SupportSteadfastPlayer"]={["Steadfast I"]={["enDescription"]="Supports Channelling Skills you use yourself, granting you higher Stun Threshold while Channelling them.",["description"]="Усиливает поддерживаемые умения, которые вы используете самостоятельно. Усиленные умения даруют вам увеличенный порог оглушения во время их поддержания.",["name"]="Устойчивость I"}},
["SupportSteadfastPlayerTwo"]={["Steadfast II"]={["enDescription"]="Supports Channelling Skills you use yourself, granting you higher Stun Threshold and Ailment Threshold  while Channelling them.",["description"]="Усиливает поддерживаемые умения, которые вы используете самостоятельно. Усиленные умения даруют вам увеличенный порог оглушения и наложения состояний во время поддержания.",["name"]="Устойчивость II"}},
["SupportStoicismPlayer"]={["Stoicism I"]={["enDescription"]="Supports Attack Skills you use yourself. Supported Skills steadily gain more Damage, up to a cap. This Damage bonus is reset if you Dodge Roll or use a Travel Skill.",["description"]="Усиливает умения атак, которые вы используете самостоятельно. Усиленные умения постепенно приобретают больше урона, до определённого предела. Эта прибавка к урону сбрасывается, если вы совершите кувырок или используете умение смещения.",["name"]="Стоицизм I"}},
["SupportStoicismPlayerTwo"]={["Stoicism II"]={["enDescription"]="Supports Attack Skills you use yourself. Supported Skills steadily gain more Damage, up to a cap. This Damage bonus is reset if you Dodge Roll or use a Travel Skill.",["description"]="Усиливает умения атак, которые вы используете самостоятельно. Усиленные умения постепенно приобретают больше урона, до определённого предела. Эта прибавка к урону сбрасывается, если вы совершите кувырок или используете умение смещения.",["name"]="Стоицизм II"}},
["SupportStompingGroundPlayer"]={["Stomping Ground"]={["enDescription"]="Supports Travel skills, causing your footsteps to crack the earth and emit damaging shockwaves while using the skill.",["description"]="Усиливает умения смещения. При использовании усиленного умения ваши шаги раскалывают землю и испускают наносящие урон ударные волны.",["name"]="Топотун"}},
["SupportStormchainPlayer"]={["Stormchain"]={["enDescription"]="Supports Projectile Skills and Skills which can Chain. Supported Skills always Chain when initially Hitting a Shocked Enemy, but cannot themselves inflict Shock. Does not support Skills which cannot Chain.",["description"]="Усиливает умения снарядов и умения, которые могут наносить удары по цепи. Усиленные умения всегда наносят удар по цепи при изначальном попадании по врагу, поражённому шоком, но сами не могут накладывать шок. Не может усиливать умения, неспособные наносить удары по цепи.",["name"]="Грозовая цепь"}},
["SupportStormfirePlayer"]={["Stormfire"]={["enDescription"]="Supports any skill that Hits enemies. Enemies Shocked by Supported Skills take a percentage of damage from Ignite as Lightning damage as well as Fire damage.",["description"]="Усиливает любое умение, наносящее удары по врагам. Враги, получившие шок от усиленных умений, получают часть урона от поджога в виде урона от молнии помимо урона от огня.",["name"]="Пламя бури"}},
["SupportStreamlinedRoundsPlayer"]={["Streamlined Rounds"]={["enDescription"]="Supports Crossbow Ammunition Skills. Supported Skills have significantly higher Attack speed and bolt capacity, but deal less damage and have longer reload time.",["description"]="Усиливает умения боезапаса самострелов. Усиленные умения имеют существенно более высокую скорость атаки и запас болтов, но наносят меньше урона и дольше перезаряжаются.",["name"]="Компактные снаряды"}},
["SupportStrongHeartedPlayer"]={["Strong Hearted"]={["enDescription"]="Supports Persistent Buff Skills, causing Shock applied to you to last for a shorter duration while the Supported Skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами. Пока усиленное умение активно, наложенный на вас шок длится меньше.",["name"]="Крепость духа"}},
["SupportStunPlayer"]={["Stun I"]={["enDescription"]="Supports any skill that Hits Enemies, causing it to build up Stun more quickly.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения накапливают оглушение быстрее.",["name"]="Оглушение I"}},
["SupportStunPlayerThree"]={["Stun III"]={["enDescription"]="Supports any skill that Hits Enemies, causing it to build up Stun significantly more quickly, at the cost of Damage.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения накапливают оглушение значительно быстрее ценой урона.",["name"]="Оглушение III"}},
["SupportStunPlayerTwo"]={["Stun II"]={["enDescription"]="Supports any skill that Hits Enemies, causing it to build up Stun more quickly.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения накапливают оглушение быстрее.",["name"]="Оглушение II"}},
["SupportStyrnsFerocity"]={["Styrn's Ferocity"]={["enDescription"]="Supports Shield Skills that Hit, causing those Hits to Crush their targets, and Physical Hits against those targets while Crushed to Break their Armour.",["description"]="Усиливает умения щитов, наносящие удары. Удары усиленных умений сокрушают цели, а удары с физическим уроном по этим целям, пока они сокрушены, разрушают броню.",["screenshot"]="Screenshot_28.png",["pobDescription"]="Supports Shield Skills that Hit enemies, causing those Hits to Crush their targets, additionally causing any Physical Damage Hits against those targets while Crushed to Break their Armour.",["flavour"]="Каждый рыцарь, встречавший Стирна, вызывал его\nна традиционный поединок. Одолевая одного за другим,\nон пробил себе дорогу через весь Мидденгард... и за его пределы.",["name"]="Свирепость Стирна"}},
["SupportStyrnsMountain"]={["Styrn's Mountain"]={["enDescription"]="Supports Skills that Raise your Shield causing your other melee skills to deal more damage if you block.",["description"]="Усиливает умения, поднимающие ваш щит, заставляя другие ваши умения ближнего боя наносить больше урона, если вы блокируете удар.",["name"]="Гора Стирна"}},
["SupportSwiftAfflictionPlayer"]={["Swift Affliction I"]={["enDescription"]="Supports any skill that deals damage, causing it to deal more non-Ailment damage over time but have a shorter duration.",["description"]="Усиливает любое умение, наносящее урон. Усиленные умения наносят больше постепенного урона не от состояний, но их длительность сокращается.",["name"]="Стремительный недуг I"}},
["SupportSwiftAfflictionPlayerThree"]={["Swift Affliction III"]={["enDescription"]="Supports any skill that deals damage, causing effects with a duration of one second or less to deal more non-Ailment damage over time.",["description"]="Усиливает любое умение, наносящее урон. Эффекты, длящиеся 1 секунду или меньше, наносят больше постепенного урона не от состояний.",["name"]="Стремительный недуг III"}},
["SupportSwiftAfflictionPlayerTwo"]={["Swift Affliction II"]={["enDescription"]="Supports any skill that deals damage, causing it to deal more non-Ailment damage over time but have a shorter duration.",["description"]="Усиливает любое умение, наносящее урон. Усиленные умения наносят больше постепенного урона не от состояний, но их длительность сокращается.",["name"]="Стремительный недуг II"}},
["SupportSyzygyPlayer"]={["Syzygy"]={["enDescription"]="Supports Slam Skills you use yourself. Hits from Supported Skills are considered Crushing Blows against Enemies which are both Ignited and Fully Armour Broken. Hits with Supported Skills that Heavily Stun Ignited and Fully Armour Broken Enemies will Intimidate them.",["description"]="Усиливает умения мощных ударов, которые вы используете самостоятельно. Удары усиленными умениями считаются сокрушительнными против врагов, которые одновременно подожжены и броня которых полностью разрушена. Удары усиленными умениями, сильно оглушающие подожжённых противников с полностью разрушенной бронёй, устрашают их.",["name"]="Сизигия"}},
["SupportTacatisIrePlayer"]={["Tacati's Ire"]={["enDescription"]="Supports Skills which can cause Damaging Hits. Poison inflicted with Supported Skills deals Damage faster the higher your Rage.",["description"]="Усиливает умения, которые могут наносить урон ударами. Наложенный усиленными умениями яд наносит урон тем быстрее, чем выше ваша свирепость.",["name"]="Гнев Такати"}},
["SupportTangMazusThuriblePlayer"]={["Tangmazu's Thurible"]={["enDescription"]="Supports Skills which summon Companions causing them to be Gigantic and gain Evasion and Deflection based on your own.",["description"]="Усиливает умения, призывающие компаньонов. Призванные усиленными умениями компаньоны становятся гигантскими и получают уклонение и отклонение на основе ваших собственных.",["name"]="Кадильница Тангмазу"}},
["SupportTangmazuLineagePlayer"]={["DNT Tangmazu Lineage"]={["enDescription"]="DNT Tangmazu Lineage",["description"]="DNT-UNUSED Tangmazu Lineage",["name"]="DNT Tangmazu Lineage"}},
["SupportTasaliosRhythmPlayer"]={["Tasalio's Rhythm"]={["enDescription"]="Supports Skills which have a benefit for Perfectly Timing their use. On successfully executing Perfect Timing with Supported Skills, gain Tasalio's Rhythm. Tasalio's Rhythm causes Supported Skills to deal more damage and have shorter Perfect Timing windows for each stack. Failing to execute any Perfect Timing (even with skills not supported by Tasalio's Rhythm) will remove all Tasalio's Rhythm on you.",["description"]="Усиливает умения, которые дают преимущества при использовании в идеальный момент. При успешном использовании идеального момента с усиленными умениями дарует Ритм Тасалио. Ритм Тасалио заставляет усиленные умения наносить больше урона и сокращает их окно идеального момента за каждую стадию. Неудачная попытка использовать идеальный момент (даже в случае умений, не усиленных Ритмом Тасалио) снимет с вас все стадии Ритма Тасалио.",["name"]="Ритм Тасалио"}},
["SupportTearPlayer"]={["Tear"]={["enDescription"]="Supports Melee Attacks you use or Trigger yourself. On-Kill effects caused by Killing Blows with Supported Skills on Bleeding enemies have a chance to occur twice.",["description"]="Усиливает атаки ближнего боя, которые вы используете самостоятельно или сами вызываете их срабатывание. Срабатывающие при убийстве эффекты, вызванные смертельными ударами усиленных умений по истекающим кровью врагам, имеют шанс сработать дважды.",["name"]="Разрыв"}},
["SupportTecrodsRevengePlayer"]={["Tecrod's Revenge"]={["enDescription"]="Supports Skills that create Persistent Minions, causing those Minions to fight on when they are fatally wounded, dying after a duration. Minions from Supported Skills gain Soul Eater and a burst of speed on entering this state.",["description"]="Усиливает умения, создающие постоянных приспешников. Получив смертельное ранение, приспешники усиленных умений продолжают некоторое время сражаться. Приспешники от усиленных умений получают эффект Пожиратель душ и прирост скорости при входе в это состояние.",["name"]="Месть Текрода"}},
["SupportTempestuousTempoPlayer"]={["Rising Tempest"]={["enDescription"]="Supports Skills which deal Damage, raising Elemental Damage dealt for each Skill used Recently of a different Elemental type. Cannot support Minion Skills.",["description"]="Усиливает умения, наносящие урон, повышая наносимый урон от стихий за каждое недавно использованное умение другой стихии. Не может усиливать умения приспешников.",["name"]="Поднимающийся шквал"}},
["SupportThornskinPlayer"]={["Thornskin I"]={["enDescription"]="Supports Persistent Buff Skills, causing you to deal increased Thorns Damage while the Supported Skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами. Пока усиленное умение активно, вы наносите увеличенный урон от шипов.",["name"]="Шипастая кожа I"}},
["SupportThornskinPlayerTwo"]={["Thornskin II"]={["enDescription"]="Supports Persistent Buff Skills, causing you to deal increased Thorns Damage while the Supported Skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами. Пока усиленное умение активно, вы наносите увеличенный урон от шипов.",["name"]="Шипастая кожа II"}},
["SupportThrillOfTheKillPlayer"]={["Thrill of the Kill"]={["enDescription"]="Supports Skills you use yourself which Hit enemies. Culling a Shocked enemy with Supported Skills infuses all of your Attacks with Lightning damage for a short time.",["description"]="Усиливает самостоятельно используемые вами умения, которые наносят удары по врагам. Добивание врага под действием шока усиленными умениями кратковременно насыщает все ваши атаки уроном от молнии.",["name"]="Азарт убийства"}},
["SupportThrillOfTheKillPlayerTwo"]={["Thrill of the Kill II"]={["enDescription"]="Supports Skills you use yourself which Hit enemies. Culling a Shocked enemy with Supported Skills infuses all of your Attacks with Lightning damage and grants an increased chance to Shock for a short time.",["description"]="Усиливает самостоятельно используемые вами умения, которые наносят удары по врагам. Добивание врага под действием шока усиленными умениями кратковременно насыщает все ваши атаки уроном от молнии и повышает шанс наложить шок.",["name"]="Азарт убийства II"}},
["SupportTimerotPlayer"]={["DNT-UNUSED Timerot"]={["enDescription"]="DNT-UNUSED Timerot",["description"]="DNT-UNUSED Timerot",["name"]="DNT-UNUSED Timerot"}},
["SupportTirelessPlayer"]={["Tireless"]={["enDescription"]="Supports Warcry Skills. Attacks Empowered by Supported Skills have a chance not to lower the Empowerment count of Supported Skills when they are used.",["description"]="Усиливает умения боевых кличей. Улучшенные усиленными умениями атаки с некоторым шансом не снижают счётчик улучшения усиленных умений при их использовании.",["name"]="Неутомимость"}},
["SupportTitanicArrowsPlayer"]={["DNT-UNUSED Titanic Arrows"]={["enDescription"]="DNT-UNUSED Supports Bow Attacks which impact the ground, triggering stunning novas when they do.",["description"]="DNT-UNUSED Supports Bow Attacks which impact the ground, triggering stunning novas when they do.",["name"]="DNT-UNUSED Titanic Arrows"}},
["SupportTotemicAegisPlayer"]={["DNT Totemic Aegis"]={["enDescription"]="DNT Totemic Aegis",["description"]="DNT-UNUSED Totemic Aegis",["name"]="DNT Totemic Aegis"}},
["SupportTremorsPlayer"]={["Tremors"]={["enDescription"]="Supports Slam Skills you use yourself. Supported Skills gain multiple independent chances to cause Aftershocks, but deal less Damage.",["description"]="Усиливает умения мощных ударов, которые вы используете самостоятельно. Усиленные умения получают несколько не зависящих друг от друга шансов вызвать остаточные волны, но наносят меньше урона.",["name"]="Дрожь"}},
["SupportTrickstersShardPlayer"]={["Trickster's Shard"]={["enDescription"]="Supports non-instant Spells you cast yourself. Supported Spells will Trigger Fragment Self, creating a Fractured Mimic which will cast that Spell if you get enough of them.",["description"]="Усиливает не мгновенные чары, которые вы сотворяете самостоятельно. Усиленные чары вызовут срабатывание Расколотого я, создавая расколотую копию, которая сотворит эти чары, если копий достаточно.",["name"]="Осколок Плута"}},
["SupportTulsAvalanche"]={["Tul's Avalanche"]={["enDescription"]="Supports Cascadable Spells you cast yourself, Sealing them when you Block, The Seals are broken when used, each making the Spell Echo. Cannot support skills with a Cooldown or which already gain Seals.",["description"]="Усиливает каскадные чары, которые вы сотворяете самостоятельно, запечатывая их при блокировании вами ударов. При использовании печати разбиваются, и за каждую чары отражаются эхом. Не может усиливать умения с перезарядкой и умения, уже накапливающие печати.",["name"]="Лавина Тул"}},
["SupportTulsStillnessPlayer"]={["Tul's Stillness"]={["enDescription"]="Supports Skills that can cause Damaging Hits, granting extra Chaos damage and causing Chaos damage to Contribute to Freeze Buildup.",["description"]="Усиливает умения, которые могут наносить урон ударами, даруя дополнительный урон хаосом и позволяя урону хаосом влиять на накопление заморозки.",["name"]="Безмолвие Тул"}},
["SupportTumultPlayer"]={["Tumult"]={["enDescription"]="Supports Skills you use yourself which can cause Damaging Hits. Supported Skills consume a Frenzy Charge on use to powerfully Break Armour.",["description"]="Усиливает самостоятельно используемые вами умения, которые могут наносить урон ударами. Усиленные умения поглощают заряд ярости при использовании, чтобы серьёзно разрушить броню.",["name"]="Смятение"}},
["SupportUhtredAuguryPlayer"]={["Uhtred's Augury"]={["enDescription"]="Supports Skills which can gain levels, granting them additional levels provided exactly two other supports are used with the supported Skill. Does not support skills which do not have levels.",["description"]="Усиливает умения, которые могут получать уровни, даруя им дополнительные уровни при условии, что с усиленным умением используются ещё ровно два камня поддержки. Не усиливает умения, не имеющие уровней.",["name"]="Предчувствие Утреда"}},
["SupportUhtredExodusPlayer"]={["Uhtred's Exodus"]={["enDescription"]="Supports Skills which can gain levels, granting them many additional levels provided no other supports are used with the supported Skill. Does not support skills which do not have levels.",["description"]="Усиливает умения, которые могут получать уровни, даруя им много дополнительных уровней при условии, что с усиленным умением не используется больше никаких камней поддержки. Не усиливает умения, не имеющие уровней.",["name"]="Исход Утреда"}},
["SupportUhtredOmenPlayer"]={["Uhtred's Omen"]={["enDescription"]="Supports Skills which can gain levels, granting them additional levels provided exactly one other support is used with the supported Skill. Does not support skills which do not have levels.",["description"]="Усиливает умения, которые могут получать уровни, даруя им дополнительные уровни при условии, что с усиленным умением используется ещё ровно один камень поддержки. Не усиливает умения, не имеющие уровней.",["name"]="Знамение Утреда"}},
["SupportUhtredsConstellation"]={["Uhtred's Constellation"]={["enDescription"]="Supports non-instant skills which have a cooldown, granting them two additional cooldown uses and more damage per different skill with a cooldown you have used recently.",["description"]="Усиливает умения с перезарядкой, добавляя им два дополнительных использования и больше урона за каждое отличное от других умение с перезарядкой, которое вы недавно использовали.",["name"]="Созвездие Утреда"}},
["SupportUhtredsRitePlayer"]={["Uhtred's Rite"]={["enDescription"]="Supports skills with Cooldowns, causing them to grant Overflowing Chalice when used. Supported skills deal more damage during the effect of your Life Flask and have increased Mana Cost Efficiency during the effect of your Mana Flask.",["description"]="Усиливает умения с перезарядкой, заставляя их при использовании даровать Переполненную чашу. Усиленные умения наносят больше урона во время эффекта вашего флакона жизни и имеют повышенную эффективность расхода маны во время эффекта вашего флакона маны.",["name"]="Ритуал Утреда"}},
["SupportUnabatingPlayer"]={["Unabating"]={["enDescription"]="Supports Attack Skills you use yourself. While using Supported Skills, you gain increased Armour, with the increase scaling higher the longer the Attack time of the supported Skill. Cannot Support Channelling Skills.",["description"]="Усиливает умения атак, которые вы используете самостоятельно. При использовании усиленных умений у вас повышается броня тем сильнее, чем дольше время атаки усиленного умения. Не может усиливать поддерживаемые умения.",["name"]="Безустанность"}},
["SupportUnbendingPlayer"]={["Unbending"]={["enDescription"]="Supports Spell Skills you use yourself. While using Supported Skills, a percentage of Damage taken is Recouped as Mana, with the percentage scaling higher the longer the Cast time of the Supported Skill. Cannot Support Channelling Skills.",["description"]="Усиливает умения чар, которые вы используете самостоятельно. При использовании усиленных умений часть получаемого урона восполняется в виде маны; чем больше время сотворения усиленных чар, тем больше восстановление. Не может усиливать поддерживаемые умения.",["name"]="Несгибаемость"}},
["SupportUnderminePlayer"]={["Undermine"]={["enDescription"]="Supports Attack Skills. Supported Skills Consume Maim on hit, Breaking a percentage of the Maimed target's Armour in doing so. Supported Skills cannot themselves inflict Maim.",["description"]="Усиливает умения атак. Усиленные умения поглощают увечье при нанесении удара, разрушая часть брони изувеченной цели. Усиленные умения не могут накладывать увечье.",["name"]="Подсечка"}},
["SupportUnerringPowerPlayer"]={["Unerring Power"]={["enDescription"]="Supports Attack Skills you use yourself. When Supported Attacks are Empowered, they have significantly lowered cost and raised Accuracy.",["description"]="Усиливает умения атак, которые вы используете самостоятельно. Когда усиленные атаки улучшаются, то расход ими ресурсов значительно снижается, а меткость повышается.",["name"]="Безошибочная мощь"}},
["SupportUnleashPlayer"]={["Unleash"]={["enDescription"]="Supports Repeatable Spells you cast yourself, Sealing them over time. The Seals are broken when cast, each causing the Spell to Repeat. Cannot support skills with a Cooldown or which already gain Seals.",["description"]="Усиливает повторяемые чары, которые вы сотворяете самостоятельно, постепенно запечатывая их. При сотворении печати разбиваются, и каждая вызывает повтор чар. Не может усиливать умения с перезарядкой и умения, уже накапливающие печати.",["name"]="Высвобождение"}},
["SupportUnsteadyTempoPlayer"]={["Unsteady Tempo"]={["enDescription"]="Supports Melee Attack Skills you use yourself. Attacking with Supported Skills will cycle through various effects, with the first Attack in sequence inflicting Hobble on you. The second and third Attacks in sequence will powerfully scale chance to Critically Hit and overall damage, respectively, at which point the cycle will reset. Cannot Support Channelling Skills.",["description"]="Усиливает умения атак ближнего боя, которые вы используете самостоятельно. Атаки усиленными умениями будут поочередно вызывать различные эффекты, при этом первая атака в очереди стреноживает вас. Вторая и третья атаки резко повышают шанс критического попадания и общий урон соответственно, после чего цикл начинается сначала. Не может усиливать поддерживаемые умения.",["name"]="Неровный темп"}},
["SupportUntouchablePlayer"]={["Untouchable"]={["enDescription"]="Supports Attack Skills you use yourself. While using Supported Skills, you gain increased Evasion Rating, with the increase scaling higher the longer the Attack time of the supported Skill. Cannot Support Channelling Skills.",["description"]="Усиливает умения атак, которые вы используете самостоятельно. При использовании усиленных умений у вас повышается уклонение тем сильнее, чем дольше время атаки усиленного умения. Не может усиливать поддерживаемые умения.",["name"]="Неприкосновенность"}},
["SupportUnyieldingPlayer"]={["Unyielding"]={["enDescription"]="Supports Melee Attack Skills you use yourself. While using Supported Skills, a percentage of Damage taken is Recouped as Life, with the percentage scaling higher the longer the Attack time of the Supported Skill. Cannot Support Channelling Skills.",["description"]="Усиливает умения атак ближнего боя, которые вы используете самостоятельно. При использовании усиленных умений часть получаемого урона восполняется в виде здоровья; чем больше время атаки усиленного умения, тем больше восстановление. Не может усиливать поддерживаемые умения.",["name"]="Непреклонность"}},
["SupportUpheavalPlayer"]={["Upheaval I"]={["enDescription"]="Supports Skills which create fissures in the ground, causing them to create an additional fissure at the cost of damage and speed.",["description"]="Усиливает умения, создающие расселины в земле. Усиленные умения создают дополнительную расселину ценой снижения урона и скорости.",["name"]="Возмущение I"}},
["SupportUpheavalPlayerTwo"]={["Upheaval II"]={["enDescription"]="Supports Skills which create fissures in the ground, causing them to create additional fissures at the cost of damage and speed.",["description"]="Усиливает умения, создающие расселины в земле. Усиленные умения создают дополнительные расселины ценой снижения урона и скорости.",["name"]="Возмущение II"}},
["SupportUpwellingPlayer"]={["Upwelling I"]={["enDescription"]="Supports Persistent Buff Skills, causing your Minions to deal increased Damage while you are not on full Mana while the Supported Skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами. Пока усиленное умение активно, ваши приспешники наносят увеличенный урон, если у вас неполная мана.",["name"]="Всплеск I"}},
["SupportUpwellingPlayerTwo"]={["Upwelling II"]={["enDescription"]="Supports Persistent Buff Skills, causing your Minions to deal increased Damage while you are not on full Mana while the Supported Skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами. Пока усиленное умение активно, ваши приспешники наносят увеличенный урон, если у вас неполная мана.",["name"]="Всплеск II"}},
["SupportUrgentTotemsPlayer"]={["Urgent Totems I"]={["enDescription"]="Supports Skills which create Totems, causing those Skills to place Totems much more quickly.",["description"]="Усиливает умения, создающие тотемы, заставляя их устанавливать тотемы гораздо быстрее.",["name"]="Спешные тотемы I"}},
["SupportUrgentTotemsPlayerThree"]={["Urgent Totems III"]={["enDescription"]="Supports Skills which create Totems, causing those Skills to place Totems much more quickly. Totems created by Supported Skills have increased Attack and Cast Speed.",["description"]="Усиливает умения, создающие тотемы, заставляя их устанавливать тотемы гораздо быстрее. Созданные усиленными умениями тотемы имеют повышенную скорость атаки и сотворения чар.",["name"]="Спешные тотемы III"}},
["SupportUrgentTotemsPlayerTwo"]={["Urgent Totems II"]={["enDescription"]="Supports Skills which create Totems, causing those Skills to place Totems much more quickly.",["description"]="Усиливает умения, создающие тотемы, заставляя их устанавливать тотемы гораздо быстрее.",["name"]="Спешные тотемы II"}},
["SupportUruksSmeltingPlayer"]={["Uruk's Smelting"]={["enDescription"]="Supports any skill, causing Armour Break it inflicts to be stronger. Fully Breaking Armour with Supported Skills permanently increases the Physical Damage taken by those affected, up to a cap.",["description"]="Усиливает любое умение, делая накладываемое им разрушение брони сильнее. Полное разрушение брони противника усиленными умениями навсегда увеличивает получаемый этим противником физический урон, до определённого предела.",["name"]="Плавильня Урука"}},
["SupportUulNetolsEmbracePlayer"]={["Uul-Netol's Embrace"]={["enDescription"]="Supports Skills that can cause Damaging Hits, granting extra Chaos damage and causing Chaos damage to Break Armour.",["description"]="Усиливает умения, которые могут наносить урон ударами, даруя дополнительный урон хаосом и позволяя урону хаосом разрушать броню.",["name"]="Объятия Уул-Нетол"}},
["SupportVanguardPlayer"]={["Vanguard I"]={["enDescription"]="Supports Shield Skills, causing you to gain Guard on Stunning Enemies with the Supported Skill.",["description"]="Усиливает умения щитов, даруя вам оборону при оглушении врага усиленным умением.",["name"]="Авангард I"}},
["SupportVanguardPlayerTwo"]={["Vanguard II"]={["enDescription"]="Supports Shield Skills, causing you to gain Guard on Stunning Enemies with the Supported Skill.",["description"]="Усиливает умения щитов, даруя вам оборону при оглушении врага усиленным умением.",["name"]="Авангард II"}},
["SupportVarashtasBlessingPlayer"]={["Varashta's Blessing"]={["enDescription"]="Supports any Skill that can deal damage, causing it to deal more damage for each different Command Skill you have used in the past few seconds. Cannot modify the Skills of Minions.",["description"]="Усиливает любое умение, способное наносить урон. Усиленное умение наносит больше урона за каждое отличное от других умение приказов, использованное вами за последние несколько секунд. Не усиливает умения приспешников.",["name"]="Благословение Варашты"}},
["SupportVerglasPlayer"]={["Verglas"]={["enDescription"]="Supports Skills you use yourself which can Hit Enemies. Supported Skills Gain a percentage of their Damage as Cold Damage when you destroy Ice Crystals.",["description"]="Усиливает самостоятельно используемые вами умения, которые могут наносить удары по врагам. Усиленные умения наносят часть своего урона в виде дополнительного урона от холода, когда вы уничтожаете ледяные кристаллы.",["name"]="Иней"}},
["SupportVilentasPropulsionPlayer"]={["Vilenta's Propulsion"]={["enDescription"]="Supports Spell Skills that fire Projectiles, causing increases and reductions to cast speed to also apply to Projectile speed.",["description"]="Усиливает умения чар, которые выпускают снаряды. Повышения и снижения скорости сотворения чар также влияют на скорость снарядов.",["name"]="Разгон Виленты"}},
["SupportVitalityPlayer"]={["Vitality I"]={["enDescription"]="Supports Persistent Buff Skills, causing you to gain Life Regeneration while the Skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами. Пока активно, усиленное умение даёт вам регенерацию здоровья.",["name"]="Живучесть I"}},
["SupportVitalityPlayerTwo"]={["Vitality II"]={["enDescription"]="Supports Persistent Buff Skills, causing you to gain Life Regeneration while the Skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами. Пока активно, усиленное умение даёт вам регенерацию здоровья.",["name"]="Живучесть II"}},
["SupportVolatilePowerPlayer"]={["Volatile Power"]={["enDescription"]="Supports Skills which you use yourself. On using Supported Skills while they are Empowered, you gain Volatility.",["description"]="Усиливает умения, которые вы используете самостоятельно. При использовании усиленных умений, пока они улучшены, вы получаете Нестабильность.",["name"]="Нестабильная мощь"}},
["SupportVolatilityPlayer"]={["Volatility"]={["enDescription"]="Supports Skills you use yourself which can cause Damaging Hits. Supported Skills grant Volatility on Critical Hit.",["description"]="Усиливает самостоятельно используемые вами умения, которые могут наносить урон ударами. Усиленные умения даруют Нестабильность при критическом попадании.",["name"]="Нестабильность"}},
["SupportVolcanicEruptionPlayer"]={["Volcanic Eruption"]={["enDescription"]="Supports Melee Strike Skills you use yourself. Supported Skills trigger Volcanic Eruption on Hit against Ignited Enemies.",["description"]="Усиливает умения ударов ближнего боя, которые вы используете самостоятельно. Усиленные умения вызывают срабатывание Извержения вулкана при нанесении удара по подожжённым врагам.",["name"]="Извержение вулкана"}},
["SupportVoltPlayer"]={["Volt"]={["enDescription"]="Supports Projectile Attack Skills you use yourself. Supported Skills gain Voltaic Charge as you move, up to a maximum. When used, Supported Skills expend that Charge to gain extra Lightning Damage.",["description"]="Усиливает умения атак снарядами, которые вы используете самостоятельно. Усиленные умения получают вольтаксовый заряд, пока вы передвигаетесь, вплоть до максимума. При использовании усиленные умения тратят этот заряд, нанося дополнительный урон от молнии.",["name"]="Разряд"}},
["SupportVoranasSiege"]={["Vorana's Siege"]={["enDescription"]="Supports skills which Hit targets and have an area of effect, increasing the affected area and causing it to Hit Isolated targets harder.",["description"]="Усиливает умения с областью действия, наносящие удары по целям. Область действия усиленных умений увеличивается и они сильнее бьют по обособленным целям.",["name"]="Осада Вораны"}},
["SupportVoranasTouch"]={["DNT Vorana's Touch"]={["enDescription"]="DNT Description",["description"]="DNT Description",["name"]="DNT Vorana's Touch"}},
["SupportVruunsAftermath"]={["Vruun's Aftermath"]={["enDescription"]="Supports Warcries, causing them to destroy Ice Crystals and Ice Fragments. Supported Skills empower additional Attacks if they destroy enough Ice Crystals and Ice Fragments.",["description"]="Усиливает боевые кличи, заставляя уничтожать ледяные кристаллы и куски льда. Усиленные умения улучшают дополнительные атаки, если уничтожат достаточно ледяных кристаллов и кусков льда.",["name"]="Последствие Рууна"}},
["SupportVruunsInevitability"]={["Vruun's Inevitability"]={["enDescription"]="Supports Melee Attack Skills. Supported Skills gain Combo when you successfully Strike Enemies with other Melee Attacks. Supported Skills expend their Combo when used, gaining more area of effect the higher Combo they had. Cannot support skills which already gain Combo. Cannot modify the Skills of Minions.",["description"]="Усиливает умения атак ближнего боя. Усиленные умения накапливают Комбо при успешных ударах по врагам другими атаками ближнего боя. Усиленные умения сбрасывают Комбо при  использовании и приобретают тем большую область действия, чем выше был счётчик Комбо. Не может усиливать умения, уже накапливающие Комбо. Не усиливает умения приспешников.",["name"]="Неизбежность Рууна"}},
["SupportWallFortressPlayer"]={["Fortress I"]={["enDescription"]="Supports skills that create walls in a line, causing them to be created in a circle instead but deal less Hit damage.",["description"]="Усиливает умения, которые создают линию из стен. Вместо этого усиленные умения создают стены в виде окружности, но наносят меньше урона от ударов.",["name"]="Крепость I"}},
["SupportWallFortressPlayerTwo"]={["Fortress II"]={["enDescription"]="Supports skills that create walls in a line, causing them to be created in a circle instead but deal less Hit damage and have lowered Area of Effect.",["description"]="Усиливает умения, которые создают линию из стен. Вместо этого усиленные умения создают стены в виде окружности, но наносят меньше урона от ударов и имеют сниженную область действия.",["name"]="Крепость II"}},
["SupportWarmbloodedPlayer"]={["Warm Blooded"]={["enDescription"]="Supports Persistent Buff Skills, causing Freeze applied to you to last for a shorter duration while the Supported Skill is active.",["description"]="Усиливает умения с постоянными положительными эффектами. Пока усиленное умение активно, наложенные на вас заморозки длятся меньше.",["name"]="Теплокровность"}},
["SupportWendigosAuthorityPlayer"]={["DNT Wendigos Authority"]={["enDescription"]="DNT Description",["description"]="DNT Description",["name"]="DNT Wendigos Authority"}},
["SupportWendigosPareidoliaPlayer"]={["DNT Wendigo's Pareidolia"]={["enDescription"]="DNT Description",["description"]="DNT Description",["name"]="DNT Wendigo's Pareidolia"}},
["SupportWildfirePlayer"]={["Wildfire"]={["enDescription"]="Supports any skill that Hits enemies, Spreading Ignites it inflicts to nearby enemies after a delay.",["description"]="Усиливает любое умение, наносящее удары по врагам. После задержки накладываемые умением поджоги распространяются на врагов поблизости.",["name"]="Пожар"}},
["SupportWildshardsPlayer"]={["Wildshards I"]={["enDescription"]="Supports Projectile Spells. Supported Spells have a chance to fire many additional Projectiles in a circle.",["description"]="Усиливает чары снарядов. Усиленные чары имеют шанс выпустить много дополнительных снарядов по кругу.",["name"]="Шальные осколки I"}},
["SupportWildshardsPlayerThree"]={["Sione's Temper"]={["enDescription"]="Supports Projectile Spells. Supported Spells have an increasingly higher chance to fire many additional Projectiles in a circle, resetting when they do.",["description"]="Усиливает чары снарядов. Усиленные чары имеют возрастающий шанс выпустить много дополнительных снарядов по кругу, который сбрасывается, когда это происходит.",["name"]="Гнев Сионы"}},
["SupportWildshardsPlayerTwo"]={["Wildshards II"]={["enDescription"]="Supports Projectile Spells. Supported Spells have a chance to fire many additional Projectiles in a circle.",["description"]="Усиливает чары снарядов. Усиленные чары имеют шанс выпустить много дополнительных снарядов по кругу.",["name"]="Шальные осколки II"}},
["SupportWindowOfOpportunityPlayer"]={["Window of Opportunity I"]={["enDescription"]="Supports Channelling skills that have special effects if released with Perfect Timing, causing them to deal much more damage if released with Perfect Timing but reducing the Perfect Timing window.",["description"]="Усиливает поддерживаемые умения, которые имеют особые эффекты, если прекратить поддержание в идеальный момент. Усиленные умения наносят намного больше урона, если прекратить их поддержание в идеальный момент, но промежуток идеального момента становится короче.",["name"]="Окно возможностей I"}},
["SupportWindowOfOpportunityPlayerTwo"]={["Window of Opportunity II"]={["enDescription"]="Supports Channelling skills that have special effects if released with Perfect Timing, causing them to deal much more damage and grant Perfect Deflection if released with Perfect Timing but reducing the Perfect Timing window.",["description"]="Усиливает поддерживаемые умения, которые имеют особые эффекты, если прекратить поддержание в идеальный момент. Усиленные умения наносят намного больше урона и даруют Идеальное отражение, если прекратить их поддержание в идеальный момент, но промежуток идеального момента становится короче.",["name"]="Окно возможностей II"}},
["SupportWitheringTouchPlayer"]={["Withering Touch"]={["enDescription"]="Supports any skill that Hits enemies, giving it a chance to Wither enemies on Hit.",["description"]="Усиливает любое умение, наносящее удары по врагам. Усиленные умения получают шанс наложить на врагов истощение при попадании.",["name"]="Губительное прикосновение"}},
["SupportXibaquasRendingPlayer"]={["Xibaqua's Rending"]={["enDescription"]="Supports Skills that leap into the air, causing Corpses in the area you land to violently explode, damaging surrounding enemies.",["description"]="Усиливает умения с прыжком в воздух, заставляя трупы в месте вашего приземления взрываться, нанося урон окружающим врагам.",["name"]="Разрывание Шибаквы"}},
["SupportXophsPyrePlayer"]={["Xoph's Pyre"]={["enDescription"]="Supports Skills that can cause Damaging Hits, granting extra Chaos damage and causing Chaos damage to Contribute to Ignites.",["description"]="Усиливает умения, которые могут наносить урон ударами, даруя дополнительный урон хаосом и позволяя урону хаосом влиять на поджоги.",["name"]="Костёр Ксофа"}},
["SupportZarokhsRefrainPlayer"]={["Zarokh's Refrain"]={["enDescription"]="Supports Cascadable Spells you cast yourself. Supported Spells Echo thrice, but are given a Cooldown. Cannot support skills which already have a Cooldown.",["description"]="Усиливает каскадные чары, которые вы сотворяете самостоятельно. Усиленные чары отражаются эхом трижды, но приобретают перезарядку. Не может усиливать умения, уже обладающие перезарядкой.",["name"]="Рефрен Зарока"}},
["SupportZarokhsRevoltPlayer"]={["Zarokh's Revolt"]={["enDescription"]="Supports Repeatable Spells you cast yourself, Sealing them over time and giving them a moderate Cooldown. The Seals are broken when cast, each causing the Spell to Repeat. Cannot support skills which already have a Cooldown or gain seals.",["description"]="Усиливает повторяемые чары, которые вы сотворяете самостоятельно, постепенно запечатывая их и добавляя им среднюю по длительности перезарядку. При сотворении печати разбиваются, и каждая вызывает повтор чар. Не может усиливать умения, уже обладающие с перезарядкой или уже накапливающие печати.",["name"]="Мятеж Зарока"}},
["SupportZenithPlayer"]={["Zenith I"]={["enDescription"]="Supports Spell Skills. Supported Skills deal more damage while you are above 90% of your Maximum Mana. Does not modify Skills used by Minions.",["description"]="Усиливает умения чар. Усиленные умения наносят больше урона, пока у вас более 90% от максимума маны. Не может усиливать умения, используемые приспешниками.",["name"]="Зенит I"}},
["SupportZenithPlayerTwo"]={["Zenith II"]={["enDescription"]="Supports Spell Skills. Supported Skills have increased Mana cost Efficiency and deal more damage while you are above 90% of your maximum Mana. Does not modify Skills used by Minions.",["description"]="Усиливает умения чар. Усиленные умения обладают повышенной эффективностью расхода маны и наносят больше урона, пока у вас более 90% от максимума маны. Не может усиливать умения, используемые приспешниками.",["name"]="Зенит II"}},
["SupportZerphisLegacyPlayer"]={["Zerphi's Infamy"]={["enDescription"]="Supports Attacks and Warcries you use yourself. Supported Skills gain a Glory requirement, and build Glory when you spend Life on Skills. Supported Skills deal more damage and have significantly\n increased area of effect.",["description"]="Усиливает атаки и боевые кличи, которые вы используете самостоятельно. Усиленные умения начинают требовать славу и накапливают славу, когда вы тратите здоровье на использование умений. Усиленные умения наносят больше урона и имеют значительно увеличенную область действия.",["name"]="Бесславие Зерфи"}},
["UnbreakableSupportPlayer"]={["Unbreakable"]={["enDescription"]="Supports any skill that you can use, making you harder to Stun while using it.",["description"]="Усиливает любое умение, которое вы можете использовать, повышая вашу устойчивость к оглушению во время его использования.",["name"]="Несломимость"}},
["ViciousHexSupportPlayer"]={["Impending Doom"]={["enDescription"]="Supports Curse skills you cast yourself, causing them to trigger Doom Blast on Cursed enemies when the Curse expires.",["description"]="Усиливает умения проклятий, которые вы сотворяете самостоятельно, вызывая срабатывание Рокового взрыва на проклятых врагах, когда проклятие истекает.",["name"]="Обречённость"}},
},
